window.__DICT_CHUNKS__=window.__DICT_CHUNKS__||{};window.__DICT_CHUNKS__["L"]={"3929":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /læb/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a laboratory:</div><ul class=\"examples\"><li><em>the school science lab</em></li></ul></div>","3930":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> la‧bel</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleɪbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a piece of paper or another material that is attached to something and gives information about it → care label:</div><ul class=\"examples\"><li><em>a luggage label</em></li><li><strong><em>on the label</strong>: It says ‘Dry clean’ on the label.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a word or phrase which is used to describe a person, group, or thing, but which is unfair or not correct:</div><ul class=\"examples\"><li><em>Men these days have to avoid attracting the ‘sexist’ label.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a record company:</div><ul class=\"examples\"><li><em>their new release on the Ace Sounds label</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>designer label</strong> clothes made by fashionable companies:</div><ul class=\"examples\"><li><em>Fancy designer labels tend to come with fancy price tags to match.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle labelled, present participle labelling British English, labeled, labeling American English)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to attach a label onto something or write information on something:</div><ul class=\"examples\"><li><em>Label the diagram clearly.</em></li><li><strong><em>label something something</strong>: The file was labelled ‘Top Secret’.</em></li><li><strong><em>label something with something</strong>: Each bag of seeds is labelled with the grower’s name.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to use a word or phrase to describe someone or something, but often unfairly or incorrectly</div><ul class=\"examples\"><li><strong><em>label somebody/something (as) something</strong>: The newspapers had unjustly labelled him a troublemaker. / The regime was inevitably labelled as ‘communist’.</em></li></ul></div></div>","3931":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> la‧bor‧a‧tory</span><span class=\"meta-item\"><strong>IPA:</strong> /ləˈbɒrətri $ ˈlæbrətɔːri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural laboratories)</span></div><div class=\"entry-body\"><div class=\"sense\">a special room or building in which a scientist does tests or prepares substances:</div><ul class=\"examples\"><li><em>a research laboratory</em></li><li><strong><em>laboratory tests/experiments/studies</em></strong></li><li><em>tests on laboratory animals</em></li></ul></div>","3932":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[work]</strong> <span class=\"gram\">[uncountable]</span> work, especially physical work: → hard labour</div><ul class=\"examples\"><li><em>The garage charges £30 an hour for labour.</em></li><li><em>Many women do hard manual labour (=work with their hands).</em></li><li><em>Workers withdrew their labour (=protested by stopping work) for twenty-four hours.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[workers]</strong> <span class=\"gram\">[uncountable]</span> all the people who work for a company or in a country:</div><ul class=\"examples\"><li><em>a shortage of skilled labor</em></li><li><em>We need to reduce our labour costs.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[baby]</strong> <span class=\"gram\">[singular, uncountable]</span> the process of giving birth to a baby</div><ul class=\"examples\"><li><strong><em>in labour</strong>: Meg was in labour for ten hours.</em></li><li><em>Diane went into labour at 2 o&#x27;clock.</em></li><li><strong><em>a long/short/difficult labour</em></strong></li><li><em>The labour pains were unbearable.</em></li><li><strong><em>labour ward/room</strong> (=a room in a hospital where women give birth)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a labour of love</strong> something that is hard work but that you do because you want to</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>somebody’s labours</strong> <em>formal</em> a period of hard work:</div><ul class=\"examples\"><li><em>After several hours&#x27; gardening, we sat down to admire the results of our labours.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to work hard:</div><ul class=\"examples\"><li><em>They laboured all day in the mills.</em></li><li><strong><em>labour over</strong>: I’ve been labouring over this report all morning.</em></li><li><strong><em>labour to do something</strong>: Ray had little talent but labored to acquire the skills of a writer.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>labour under a delusion/misconception/misapprehension etc</strong> to believe something that is not true:</div><ul class=\"examples\"><li><em>She had laboured under the misconception that Bella liked her.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>labour the point</strong> to describe or explain something in too much detail or when people have already understood it</div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[always + adverb/preposition]</span> to move slowly and with difficulty:</div><ul class=\"examples\"><li><em>I could see the bus labouring up the steep, windy road.</em></li></ul></div></div>","3933":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> la‧bour‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleɪbərə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone whose work needs physical strength, for example building work → worker:</div><ul class=\"examples\"><li><em>a farm labourer</em></li></ul></div>","3934":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /leɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a fine cloth made with patterns of many very small holes:</div><ul class=\"examples\"><li><em>a handkerchief trimmed with lace</em></li><li><em>lace curtains</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually plural]</span> a string that is pulled through special holes in shoes or clothing to pull the edges together and fasten them <em>SYN shoelace</em></div></div>","3935":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /læk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[singular, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">when there is not enough of something, or none of it <em>SYN shortage</em> <em>OPP surplus</em></div><ul class=\"examples\"><li><strong><em>lack of</strong>: new parents suffering from lack of sleep / Too many teachers are treated with a lack of respect.</em></li><li><em>comments based on a total lack of information</em></li><li><em>Does their apparent lack of progress mean they are not doing their job properly?</em></li><li><em>tours that are cancelled for lack of bookings</em></li><li><em>There was no lack of willing helpers.</em></li><li><em>health problems linked to poor diet and a relative lack of exercise</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to not have something that you need, or not have enough of it: ► Do not use ‘in’ or ‘of’ after the verb lack: We lack ideas (NOT We lack in/of ideas). However, you can use these prepositions after be lacking in and a lack: We are lacking in ideas. | There is a lack of ideas.</div><ul class=\"examples\"><li><em>Alex’s real problem is that he lacks confidence.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>not lack for something</strong> <em>formal</em> to have a lot of something:</div><ul class=\"examples\"><li><em>He does not lack for critics.</em></li></ul></div></div>","3936":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lack‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlækɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not having enough of something or any of it</div><ul class=\"examples\"><li><strong><em>lacking in</strong>: He was lacking in confidence. / She seems to be entirely lacking in intelligence.</em></li><li><em>The new designs have all been found lacking in some important way.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if something that you need or want is lacking, it does not exist:</div><ul class=\"examples\"><li><em>Financial backing for the project is still lacking.</em></li><li><em>These qualities are sadly lacking today.</em></li></ul></div>","3937":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /læd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>old-fashioned</em> <em>informal</em> a boy or young man → lass: ► see thesaurus at man</div><ul class=\"examples\"><li><em>a young lad</em></li><li><em>Things were different when I was a lad.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the lads</strong> <em>spoken</em> a group of male friends that a man works with or spends his free time with:</div><ul class=\"examples\"><li><em>a night out with the lads</em></li><li><strong><em>one of the lads</strong> (=a member of your group of friends)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a bit of a lad</strong> <em>spoken</em> a man that people like even though he behaves rather badly:</div><ul class=\"examples\"><li><em>That Chris is a bit of a lad, isn’t he?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>lad culture</strong> <em>informal</em> the way in which some young men behave, involving typically male activities such as drinking a lot of alcohol, driving fast cars, and watching football – used to show disapproval</div><div class=\"sense\"><span class=\"snum\">5</span> (also stable lad) a boy or man who works with horses <em>SYN stable boy</em></div></div>","3938":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lad‧der</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlædə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a piece of equipment used for climbing up to or down from high places. A ladder has two bars that are connected by rungs (=short bars that you use as steps): → Snakes and Ladders, rope ladder, stepladder</div><ul class=\"examples\"><li><em>She climbed up the ladder.</em></li><li><em>He hurt himself falling off a ladder.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a series of levels which someone moves up and down within an organization, profession, or society</div><ul class=\"examples\"><li><strong><em>career/corporate ladder</strong>: Stevens slowly worked his way up the corporate ladder.</em></li><li><em>Becoming a doctor would be a step up the social ladder.</em></li><li><em>the first step on the ladder of success</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> a long thin hole in stockings or tights where some stitches have broken SYN run<em>American English</em>:</div><ul class=\"examples\"><li><em>Yes, I know I’ve got a ladder in my tights.</em></li></ul></div>","3939":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> la‧dy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleɪdi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural ladies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> ► see thesaurus at woman RegisterLady often sounds old-fashioned, especially when it is used about younger women. In everyday English, people usually say woman:· His cousin is a 26-year-old woman who works in a kindergarten.</div><div class=\"subsense\"><span class=\"subnum\">a)</span> a woman of a particular type or age</div><ul class=\"examples\"><li><strong><em>young/old/elderly etc lady</em></strong></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a word meaning woman, used especially to describe women’s sports or products made for women</div><ul class=\"examples\"><li><strong><em>ladies’ team/champion/championship etc</strong>: the ladies’ darts team</em></li><li><strong><em>ladies’ fashion/clothing/shoes etc</strong>: ladies’ underwear</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> a word meaning woman, used in order to be polite → gentleman:</div><ul class=\"examples\"><li><em>The young lady at reception sent me up here.</em></li><li><em>Give your coat to the lady over there.</em></li><li><strong><em>lady doctor/lawyer etc</strong> (=a doctor, lawyer etc who is a woman. Some women think this use is offensive)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a woman who is polite and behaves very well → gentleman:</div><ul class=\"examples\"><li><em>She knows how to behave like a lady.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>Lady</strong> used as the title of the wife or daughter of a British nobleman or the wife of a knight:</div><ul class=\"examples\"><li><em>Lady Spencer</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the ladies</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>British English</em> a women’s toilet SYN ladies’ room<em>American English</em> → the gents’</div><div class=\"subsense\"><span class=\"subnum\">b)</span> a word meaning women, often used humorously: → ladies&#x27; man</div><ul class=\"examples\"><li><em>His boyish good looks made him a favourite with the ladies.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>ladies</strong> <em>spoken</em> <em>formal</em> used to speak to a group of women:</div><ul class=\"examples\"><li><em>Ladies and gentlemen, may I have your attention please?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> a woman, especially one with a strong character – used to show approval:</div><ul class=\"examples\"><li><em>She can be a tough lady to negotiate with.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>lady friend</strong> a woman that a man is having a romantic relationship with – often used humorously <em>SYN girlfriend</em>:</div><ul class=\"examples\"><li><em>I saw Chris with his new lady friend.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>lady of leisure</strong> a woman who does not work and has a lot of free time – used humorously:</div><ul class=\"examples\"><li><em>So you’re a lady of leisure now that the kids are at school?</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <em>American English</em> <em>spoken</em> used when talking directly to a woman you do not know, when you are angry with her: RegisterAddressing a woman directly as lady sounds rude. In polite American English, people use Miss or Ma&#x27;am instead: · Can I help you, Miss?</div><ul class=\"examples\"><li><em>Hey, lady, would you mind getting out of my way?</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>Our Lady</strong> an expression used to mean Mary, the mother of Jesus Christ</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>the lady of the house</strong> <em>old-fashioned</em> the most important woman in a house, usually the mother of a family</div><div class=\"sense\"><span class=\"snum\">12</span> <em>old-fashioned</em> a woman born into a high social class in Britain:</div><ul class=\"examples\"><li><em>I could see the Queen, surrounded by her lords and ladies.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <em>old-fashioned</em> a man’s wife:</div><ul class=\"examples\"><li><em>the captain and his lady</em></li></ul></div>","3940":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /læɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(past tense and past participle lagged, present participle lagging)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to move or develop more slowly than others</div><ul class=\"examples\"><li><strong><em>lag behind</strong>: She stopped to wait for Ian who was lagging behind. / Britain is lagging behind the rest of Europe.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> <em>British English</em> to cover water pipes etc with a special material to prevent the water inside them from freezing or the heat from being lost:</div><ul class=\"examples\"><li><em>We’ve had the hot-water tank lagged.</em></li></ul></div>","3941":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /leɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a large area of water surrounded by land:</div><ul class=\"examples\"><li><em>Lake Michigan</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>wine/milk etc lake</strong> <em>British English</em> a very large amount of wine, milk etc that has been produced but is not needed or used → mountain</div></div>","3942":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /læm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a young sheep</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the meat of a young sheep → mutton:</div><ul class=\"examples\"><li><em>roast lamb</em></li><li><em>a leg of lamb</em></li><li><strong><em>lamb chop/cutlet/stew etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> <em>spoken</em> used to talk to or talk about someone who is gentle and lovable, especially a child:</div><ul class=\"examples\"><li><em>Ben’s asleep now, the little lamb.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>like a lamb to the slaughter</strong> used when someone is going to do something dangerous, but they do not realize it or have no choice</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>like a lamb</strong> quietly and without any argument:</div><ul class=\"examples\"><li><em>Suzie went off to school like a lamb today.</em></li></ul></div>","3943":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /læmp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an object that produces light by using electricity, oil, or gas → fog lamp, headlamp, hurricane lamp, safety lamp, standard lamp</div><ul class=\"examples\"><li><strong><em>table/desk/bedside lamp</em></strong></li><li><strong><em>oil/electric/fluorescent lamp</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a piece of electrical equipment used to provide a special kind of heat, especially as a medical treatment</div><ul class=\"examples\"><li><strong><em>infra-red/ultraviolet lamp</em></strong></li></ul></div>","3944":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lænd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[ground]</strong> <span class=\"gram\">[uncountable]</span> an area of ground, especially when used for farming or building: ► see thesaurus at country → dockland, farmland</div><ul class=\"examples\"><li><em>They own a lot of land.</em></li><li><em>He bought a piece of land.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[not sea]</strong> <span class=\"gram\">[uncountable]</span> the solid dry part of the Earth’s surface: → dry land</div><ul class=\"examples\"><li><em>After 21 days at sea, we sighted land.</em></li><li><strong><em>by land</strong>: Troops began an assault on the city by land and sea.</em></li><li><strong><em>on land</strong>: The crocodile lays its eggs on land.</em></li><li><strong><em>land bird/animal</strong>: The white stork is one of the biggest land birds of the region.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[country]</strong> <span class=\"gram\">[countable]</span> <em>literary</em> a country or area: ► see thesaurus at ground</div><ul class=\"examples\"><li><em>Their journey took them to many foreign lands.</em></li><li><strong><em>native land</strong> (=the land where you were born): He’s fiercely proud of his native land.</em></li><li><em>Australia represented a real land of opportunity for thousands of people.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[not city]</strong> <strong>the land</strong> the countryside thought of as a place where people grow food</div><ul class=\"examples\"><li><strong><em>live off the land</strong> (=grow or catch all the food you need): A third of the region’s population still lives off the land.</em></li><li><strong><em>work/farm the land</strong> (=grow crops): Many people were forced to give up working the land.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[property]</strong> <span class=\"gram\">[uncountable]</span> the area of land that someone owns:</div><ul class=\"examples\"><li><em>He ordered us to get off his land.</em></li><li><strong><em>private/public/common land</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>see/find out how the land lies</strong> <em>spoken</em> to try to discover what the situation really is before you make a decision</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>in the land of the living</strong> <em>spoken</em> awake – used humorously</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>the land of milk and honey</strong> an imaginary place where life is easy and pleasant</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>(in) the land of nod</strong> <em>old-fashioned</em> asleep</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[plane/bird/insect]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[intransitive]</span> if a plane, bird, or insect lands, it moves safely down onto the ground <em>OPP take off</em>:</div><ul class=\"examples\"><li><em>Flight 846 landed five minutes ago.</em></li><li><em>The bird landed gracefully on the water.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[transitive]</span> to make a plane move safely down onto the ground at the end of a journey:</div><ul class=\"examples\"><li><em>The pilot managed to land the aircraft safely.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[arrive by boat/plane]</strong> <span class=\"gram\">[intransitive]</span> to arrive somewhere in a plane, boat etc ► see thesaurus at arrive</div><ul class=\"examples\"><li><strong><em>land on/in/at etc</strong>: We expect to be landing in Oslo in about fifty minutes. / In 1969, the first men landed on the Moon.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[fall/come down]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to come down through the air onto something <em>SYN drop</em></div><ul class=\"examples\"><li><strong><em>land in/on/under etc</strong>: A large branch landed on the hood of my car. / Louis fell out of the tree and landed in a holly bush. / She fell and landed heavily on the floor. / A couple of bombs landed quite near to the village.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[goods/people]</strong> <span class=\"gram\">[transitive]</span> if a boat or aircraft lands people or goods, it brings them to a place, and the people get out or the goods are carried out:</div><ul class=\"examples\"><li><em>The troops were landed by helicopter.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[job/contract etc]</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> to succeed in getting a job, contract etc that was difficult to get:</div><ul class=\"examples\"><li><em>He landed a job with a law firm.</em></li><li><strong><em>land yourself something</strong>: Bill’s just landed himself a part in a Broadway show.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>land somebody in trouble/hospital/court etc</strong> to cause someone to have serious problems or be in a difficult situation:</div><ul class=\"examples\"><li><em>Connie’s going to land herself in big trouble if she keeps arriving late for work.</em></li><li><em>She developed pneumonia which landed her in hospital.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>land somebody in it</strong> <em>British English</em> <em>spoken</em> <em>informal</em> to get someone into trouble by telling other people that they did something wrong <em>SYN drop somebody in it</em>:</div><ul class=\"examples\"><li><em>Geoff landed me in it by saying I should have checked that the door was locked.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[problems]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to arrive unexpectedly, and cause problems</div><ul class=\"examples\"><li><strong><em>land in/on/under etc</strong>: Just when I thought my problems were over, this letter landed on my desk.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>land a punch/blow etc</strong> to succeed in hitting someone</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>land on your feet</strong> to get into a good situation again, after having problems:</div><ul class=\"examples\"><li><em>She certainly landed on her feet when she got that job.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[catch fish]</strong> <span class=\"gram\">[transitive]</span> to catch a fish</div></div></div>","3945":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> land‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlændɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the action of bringing an aircraft down to the ground after being in the air <em>OPP take-off</em>: → soft landing</div><ul class=\"examples\"><li><em>take-off and landing procedures</em></li><li><strong><em>crash/emergency landing</strong> (=a sudden landing caused by a problem with the engine etc)</em></li><li><em>the Apollo Moon landings</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> the floor at the top of a set of stairs or between two sets of stairs:</div><ul class=\"examples\"><li><em>the first-floor landing</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> the action of bringing soldiers onto land that is controlled by the enemy:</div><ul class=\"examples\"><li><em>the first landings of American Marines at Da Nang</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a landing stage</div></div>","3946":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> land‧lord</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlændlɔːd $ -lɔːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a man who rents a room, building, or piece of land to someone → landlady</div><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> a man who owns or manages a pub → landlady</div></div>","3947":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> land‧mark</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlændmɑːk $ -mɑːrk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that is easy to recognize, such as a tall tree or building, and that helps you know where you are:</div><ul class=\"examples\"><li><em>One of Belfast’s most famous landmarks, the Grosvenor Hall, has been demolished.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> one of the most important events, changes, or discoveries that influences someone or something:</div><ul class=\"examples\"><li><em>The discovery of penicillin was a landmark in the history of medicine.</em></li><li><strong><em>landmark decision/case/ruling</strong>: The Supreme Court issued a landmark decision in January 2001.</em></li></ul></div>","3948":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> land‧own‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlændˌəʊnə $ -ˌoʊnər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who owns land, especially a large amount of it:</div><ul class=\"examples\"><li><em>wealthy landowners</em></li></ul></div>","3949":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> land‧scape</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlændskeɪp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> an area of countryside or land of a particular type, used especially when talking about its appearance: ► see thesaurus at country</div><ul class=\"examples\"><li><em>the beauty of the New England landscape</em></li><li><strong><em>rural/industrial/urban etc landscape</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a picture showing an area of countryside or land:</div><ul class=\"examples\"><li><em>English landscape artists</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the political/social landscape</strong> the general situation in which a particular activity takes place:</div><ul class=\"examples\"><li><em>Recent electoral shocks have shaken the European political landscape.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> a way of printing a document in which the long sides are horizontal and the short sides are vertical → portrait</div></div>","3950":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /leɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a narrow road in the countryside → path:</div><ul class=\"examples\"><li><em>a quiet country lane</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a road in a city, often used in road names:</div><ul class=\"examples\"><li><em>the Hilton Hotel in Park Lane</em></li><li><em>a network of alleys and back lanes (=narrow unimportant roads, often behind a row of houses)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> one of the two or three parallel areas on a road which are divided by painted lines to keep traffic apart: → bus lane, cycle lane</div><ul class=\"examples\"><li><em>That idiot changed lanes without signalling.</em></li><li><strong><em>the inside/middle/outside lane</strong>: Use the outside lane for overtaking only.</em></li><li><strong><em>the fast/slow lane</strong>: Cars in the fast lane were travelling at over 80 miles an hour.</em></li><li><strong><em>three-lane motorway/highway/road</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">4</span> one of the narrow parallel areas marked for each competitor in a running or swimming race</div><div class=\"sense\"><span class=\"snum\">5</span> a line or course along which ships or aircraft regularly travel between ports or airports:</div><ul class=\"examples\"><li><em>busy shipping lanes</em></li></ul></div>","3951":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lan‧guage</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlæŋɡwɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[English/French/Arabic etc]</strong> <span class=\"gram\">[countable, uncountable]</span> a system of communication by written or spoken words, which is used by the people of a particular country or area:</div><ul class=\"examples\"><li><em>How many languages do you speak?</em></li><li><em>one of the best-known poems in the English language</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[communication]</strong> <span class=\"gram\">[uncountable]</span> the use of written or spoken words to communicate:</div><ul class=\"examples\"><li><em>the origins of language</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[style/type of words]</strong> <span class=\"gram\">[uncountable]</span> a particular style or type of words</div><ul class=\"examples\"><li><strong><em>legal/medical/technical etc language</strong>: The letter was written in complicated legal language.</em></li><li><strong><em>spoken/written language</strong>: The expression is mainly used in written language.</em></li><li><strong><em>ordinary/everyday language</strong>: He is able to explain complicated ideas in simple everyday language.</em></li><li><strong><em>literary/poetic language</strong>: The plays are full of old-fashioned poetic language.</em></li><li><strong><em>language of</strong>: the language of science</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[swearing]</strong> <span class=\"gram\">[uncountable]</span> <em>informal</em> words that most people think are offensive</div><ul class=\"examples\"><li><strong><em>mind/watch your language<em>spoken</em></strong> (=stop swearing)</em></li><li><strong><em>bad/foul/abusive language</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>strong language</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> angry words used to tell people exactly what you mean</div><div class=\"subsense\"><span class=\"subnum\">b)</span> words that most people think are offensive <em>SYN swearing</em></div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[computers]</strong> <span class=\"gram\">[countable, uncountable]</span> <em>technical</em> a system of instructions for operating a computer:</div><ul class=\"examples\"><li><em>a programming language for the Web</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[signs/actions/sounds]</strong> <span class=\"gram\">[countable, uncountable]</span> signs, movements, or sounds that express ideas or feelings</div><ul class=\"examples\"><li><strong><em>language of</strong>: the language of bees / the language of dolphins</em></li></ul></div>","3952":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /læp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the upper part of your legs when you are sitting down <em>SYN knee</em></div><ul class=\"examples\"><li><strong><em>on somebody’s lap</strong>: Shannon sat on her mother’s lap.</em></li><li><strong><em>in somebody’s lap</strong>: His hands were folded in his lap.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a single journey around a race track:</div><ul class=\"examples\"><li><em>Rubens Barrichello finished a lap ahead of his team-mate.</em></li><li><strong><em>lap of honour<em>British English,</em></strong> <strong>victory lap</em>American English</strong><em> (=a lap to celebrate winning): The entire team took a victory lap in front of their cheering fans.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>American English</em> a single journey from one end of a swimming pool to another</div><ul class=\"examples\"><li><strong><em>do/run/swim a lap</strong>: Every morning she swims 50 laps in the pool.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a part of a long journey <em>SYN leg</em></div><ul class=\"examples\"><li><strong><em>lap of</strong>: The last lap of their journey was by ship.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>in the lap of luxury</strong> having an easy and comfortable life with a lot of money, possessions etc:</div><ul class=\"examples\"><li><em>She wasn’t used to living in the lap of luxury.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>in the lap of the gods</strong> <em>British English</em> if the result of something is in the lap of the gods, you do not know what will happen because it depends on things you cannot control</div></div>","3953":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lap‧top</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlæptɒp $ -tɑːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a small computer that you can carry with you → desktop</div></div>","3954":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɑːdʒ $ lɑːrdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(comparative larger, superlative largest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> big in size, amount, or number <em>OPP small</em>: ► see thesaurus at big</div><ul class=\"examples\"><li><em>Los Angeles is the second largest city in the US.</em></li><li><em>The T-shirt comes in Small, Medium and Large.</em></li><li><em>a large ovenproof pan</em></li><li><em>large sums of money</em></li><li><em>those who drink large amounts of coffee</em></li><li><em>A large number of students have signed up for the course.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a large person is tall and often fat <em>OPP small</em> ► see thesaurus at fat</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>be at large</strong> if a dangerous person or animal is at large, they have escaped from somewhere or have not been caught:</div><ul class=\"examples\"><li><em>The escaped prisoners are still at large.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the population/public/society/world etc at large</strong> people in general:</div><ul class=\"examples\"><li><em>The chemical pollution poses a threat to the population at large.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the larger issues/question/problem/picture</strong> more general facts, situations, or questions related to something:</div><ul class=\"examples\"><li><em>The book helps to explain the larger picture in the Middle East.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>in large part/measure</strong> <em>formal</em> mostly:</div><ul class=\"examples\"><li><em>Their success was due in large part to their ability to speak Spanish.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>(as) large as life</strong> <em>British English</em> <em>spoken</em> used when someone has appeared or is present in a place where you did not expect to see them:</div><ul class=\"examples\"><li><em>I turned a corner and there was Joe, as large as life.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>larger than life</strong> someone who is larger than life is very amusing or exciting in an attractive way</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>by and large</strong> used when talking generally about someone or something:</div><ul class=\"examples\"><li><em>Charities, by and large, do not pay tax.</em></li></ul></div>","3955":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌlarge-ˈscale</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> using or involving a lot of effort, people, supplies etc <em>OPP small-scale</em>:</div><ul class=\"examples\"><li><em>a large-scale rescue operation</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a large-scale map, model etc is drawn or made bigger than usual, so that more details can be shown</div></div>","3956":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> large‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɑːdʒli $ ˈlɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2</span></div><div class=\"entry-body\"><div class=\"sense\">mostly or mainly:</div><ul class=\"examples\"><li><em>The state of Nevada is largely desert.</em></li><li><em>It had been a tiring day, largely because of all the tedious waiting.</em></li></ul></div>","3957":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> la‧ser</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleɪzə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a piece of equipment that produces a powerful narrow beam of light that can be used in medical operations, to cut metals, or to make patterns of light for entertainment:</div><ul class=\"examples\"><li><em>laser surgery</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a beam of light produced by a laser</div></div>","3958":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">determiner</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɑːst $ læst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> most recent or nearest to the present time → next(12):</div><ul class=\"examples\"><li><em>I hadn’t seen him since the last meeting.</em></li><li><strong><em>last night/week/year etc</strong>: Did you see the game on TV last night? / The law was passed last August.</em></li><li><em>Interest in golf has grown rapidly in the last ten years.</em></li><li><em>Things have changed since the last time (=the most recent occasion) you were here.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> happening or existing at the end, with no others after <em>OPP first</em>:</div><ul class=\"examples\"><li><em>I didn’t read the last chapter of the book.</em></li><li><em>The next meeting will be held in the last week in June.</em></li><li><strong><em>the last person/thing etc to do something</strong>: Anna was the last person to see him alive.</em></li><li><strong><em>last but one/two etc</strong> (=last except for one other, two others etc): on the last but one day of his trial</em></li><li><strong><em>second/next to last</strong> (=last except for one other): the second to last paragraph</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> remaining after all others have gone, been used etc:</div><ul class=\"examples\"><li><em>Can I have the last piece of cake?</em></li><li><strong><em>every last</strong> (=used to emphasize that you mean all of something): All the money was gone; every last penny of it.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the last minute/moment</strong> the latest possible time before something happens:</div><ul class=\"examples\"><li><em>Travelers will find it hard to get a hotel room at the last minute.</em></li><li><em>He never makes a decision until almost the last moment.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the last person/thing</strong> used to make a strong negative statement about someone or something:</div><ul class=\"examples\"><li><em>She’s the last person I’d expect to meet in a disco (=I would not expect to meet her in a disco at all).</em></li><li><em>Money was the last thing I cared about right now.</em></li><li><strong><em>the last thing somebody needs/wants</strong>: The last thing she needed was for me to start crying too.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be the last straw</strong> to be the final thing in a series of annoying things that makes someone very angry:</div><ul class=\"examples\"><li><em>He’d broken his promise again, and it was the last straw.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>last thing (at night)</strong> at the very end of the day:</div><ul class=\"examples\"><li><em>Take a couple of these pills last thing at night to help you sleep.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>on your last legs</strong> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> very tired:</div><ul class=\"examples\"><li><em>Sarah looks as if she’s on her last legs.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> very ill and likely to die soon</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>on its last legs</strong> <em>informal</em> old or in bad condition, and likely to stop working soon:</div><ul class=\"examples\"><li><em>The car’s on its last legs.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>be the last word in something</strong> to be the best, most modern, or most comfortable example of something:</div><ul class=\"examples\"><li><em>It’s the last word in luxury holidays.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> most recently before now → next: GRAMMARChoosing the right tenseLast is used with the simple past: · I last saw her in 2008. ✗Don’t say: I have last seen her in 2008.Word order• Last usually comes before a main verb: · I last went to London in June.• Last comes after ‘be’ when it is the main verb: · I was last in London in June.• Last comes after the first auxiliary: · When did you last hear from Tara?</div><ul class=\"examples\"><li><em>When I last saw her, she was working in New York.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> after everything or everyone else <em>OPP first</em>:</div><ul class=\"examples\"><li><em>Who is speaking last?</em></li><li><em>Add the flour last.</em></li><li><strong><em>last of all</strong> (=used when giving a final point or piece of information): Last of all, I’d like to thank everyone for coming.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>last but not least</strong> used when mentioning the last person or thing in a list, to emphasize that they are still important:</div><ul class=\"examples\"><li><em>Last but not least, let me introduce Jane, our new secretary.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the last</strong> the person or thing that comes after all the others <em>OPP first</em>:</div><ul class=\"examples\"><li><em>I think this box is the last.</em></li><li><strong><em>the last to do something</strong>: He was the first to arrive and the last to leave.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>at (long) last</strong> if something happens at last, it happens after you have been hoping, waiting, or working for it a long time:</div><ul class=\"examples\"><li><em>At last it was time to leave.</em></li><li><em>We reached the summit at last.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the day/week/year etc before last</strong> the day, week etc before the one that has just finished:</div><ul class=\"examples\"><li><em>I sent the letter off the week before last.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the last of something</strong> the remaining parts of something:</div><ul class=\"examples\"><li><em>John ate the last of the bread at lunchtime.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>somebody hasn’t heard the last of somebody/something</strong> if you have not heard the last of someone or something, they may return and cause problems for you in the future:</div><ul class=\"examples\"><li><em>We haven’t heard the last of football violence.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>somebody will never hear the last of something</strong> if you will never hear the last of something, someone will be angry with you about it for a long time:</div><ul class=\"examples\"><li><em>If my mother sees me, I’ll never hear the last of this.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>the last I heard</strong> <em>spoken</em> used to tell someone the most recent news that you know about a person or situation:</div><ul class=\"examples\"><li><em>The last I heard, she was at college studying law.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>to the last</strong> <em>formal</em> until the end of an event or the end of someone’s life:</div><ul class=\"examples\"><li><em>He died in 1987, insisting to the last he was innocent.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive always + adverb/preposition, transitive]</span> to continue for a particular length of time ► see thesaurus at continue</div><ul class=\"examples\"><li><strong><em>last for/until/through etc</strong>: The hot weather lasted for the whole month of June.</em></li><li><strong><em>last an hour/ten minutes etc</strong>: Each lesson lasts an hour. / The ceasefire didn’t last long.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to continue to exist, be effective, or remain in good condition for a long time:</div><ul class=\"examples\"><li><em>This good weather won’t last.</em></li><li><strong><em>last (somebody) two days/three weeks etc</strong>: A good coat will last you ten years. / Cut flowers will last longer if you put flower food in the water.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> (also last out (something)<em>British English</em>) to manage to remain in the same situation, even when this is difficult:</div><ul class=\"examples\"><li><em>They won’t be able to last much longer without fresh supplies.</em></li><li><em>If you go into the job with that attitude, you won’t last long.</em></li><li><em>She feared she might not be able to last out the afternoon in court without fainting.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive, transitive always + adverb/preposition]</span> to be enough for someone for a period of time <em>SYN do</em></div><ul class=\"examples\"><li><strong><em>last (somebody) for/until/to etc</strong>: The batteries should last for 20 hours playing time. / We only had $50 to last us the rest of the month.</em></li></ul></div></div>","3959":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈlast name</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>especially American English</em> a surname</div></div>","3960":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌlast-ˈminute</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">happening or done as late as possible before something else happens:</div><ul class=\"examples\"><li><em>a few last-minute changes to the script</em></li></ul></div>","3961":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> last‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɑːstɪŋ $ ˈlæs-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[usually before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">strong enough, well enough planned etc to continue for a very long time <em>SYN long-lasting</em>: ► see thesaurus at long, permanent</div><ul class=\"examples\"><li><em>The reforms will bring lasting benefits.</em></li><li><em>Their generosity made a lasting impression on me.</em></li><li><em>a solution that would bring lasting peace</em></li></ul></div>","3962":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> last‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɑːstli $ ˈlæst-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[sentence adverb]</span></span></div><div class=\"entry-body\"><div class=\"sense\">used when telling someone the last thing at the end of a list or a series of statements <em>OPP firstly</em>:</div><ul class=\"examples\"><li><em>Lastly, could I ask all of you to keep this information secret.</em></li></ul></div>","3963":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /leɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(comparative later, superlative latest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[after expected time]</strong> arriving, happening, or done after the time that was expected, agreed, or arranged <em>OPP early</em>:</div><ul class=\"examples\"><li><em>Sorry I’m late – I overslept.</em></li><li><strong><em>ten minutes/two hours etc late</strong>: You’re half an hour late.</em></li><li><em>The train was even later than usual.</em></li><li><em>We apologize for the late departure of flight AZ709.</em></li><li><em>There are penalties if loan repayments are late.</em></li><li><strong><em>late for</strong>: Cheryl was late for school.</em></li><li><strong><em>late with</strong>: We’ve never been late with the rent.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[near the end]</strong> <span class=\"gram\">[only before noun]</span> used to refer to the part near the end of a period of time <em>OPP early</em>:</div><ul class=\"examples\"><li><em>Paul’s in his late forties.</em></li><li><em>a late eighteenth-century building</em></li><li><em>in the late 1980s</em></li><li><em>By late afternoon, she had done 10 drawings.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be too late</strong> to arrive or do something after the time when something could or should have been done:</div><ul class=\"examples\"><li><em>He shouted a warning but it was too late.</em></li><li><strong><em>too late to do something</strong>: Are we too late to get tickets? / It was too late to turn back.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[after usual time]</strong> happening or done after the usual or normal time:</div><ul class=\"examples\"><li><em>a late breakfast</em></li><li><em>The harvest was late this year because of the rain.</em></li><li><em>She looked tired – too many late nights (=nights when she went to bed after the normal time).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[evening]</strong> near the end of a day:</div><ul class=\"examples\"><li><em>the late movie</em></li><li><em>It’s late – I’d better go home.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[dead]</strong> <span class=\"gram\">[only before noun]</span> dead</div><ul class=\"examples\"><li><strong><em>late husband/wife</strong>: Mrs. Moore’s late husband</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>late developer/bloomer</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a child who develops socially, emotionally, or physically at a later age than other children</div><div class=\"subsense\"><span class=\"subnum\">b)</span> someone who does not become successful until they are older</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>it’s (a little/bit) late in the day (to do something)</strong> used to show disapproval because someone has done something too late:</div><ul class=\"examples\"><li><em>It’s a bit late in the day to start having objections.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>late of something</strong> <em>formal</em> used about someone who has died fairly recently:</div><ul class=\"examples\"><li><em>Billy Hicks, late of this parish</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\">(comparative later, superlative no superlative)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> after the usual time:</div><ul class=\"examples\"><li><em>The stores are open later on Thursdays.</em></li><li><em>Ellen has to work late tonight.</em></li><li><em>Can you stay late?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> after the arranged or expected time <em>OPP early</em></div><ul class=\"examples\"><li><strong><em>ten minutes/two hours etc late</strong>: The bus came ten minutes late.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>too late</strong> after the time when something could or should have been done:</div><ul class=\"examples\"><li><em>The advice came too late.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> near to the end of a period of time or an event</div><ul class=\"examples\"><li><strong><em>late in</strong>: The wedding took place late in May.</em></li><li><em>It was not a place to walk in late at night.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>as late as something</strong> used to express surprise that something considered old-fashioned was still happening so recently:</div><ul class=\"examples\"><li><em>Capital punishment was still used in Britain as late as the 1950s.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>of late</strong> <em>formal</em> recently:</div><ul class=\"examples\"><li><em>Birth rates have gone down of late.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>late in life</strong> if you do something late in life, you do it at an older age than most people do it</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>better late than never</strong> used to say that you are glad someone has done something, or to say that they should do something even though they are late</div></div></div>","3964":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> late‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleɪtli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\">recently: ► see thesaurus at recently GRAMMAR: Choosing the right tenseLately is usually used with perfect tenses (for example ‘I have been’), not with the simple past (for example ‘I was’). You say: · I’ve been very busy lately. ✗Don’t say: I was very busy lately.</div><ul class=\"examples\"><li><em>What have you been doing lately?</em></li><li><em>Lately, I’ve had trouble sleeping.</em></li></ul></div>","3965":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lat‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleɪtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> after the time you are talking about or after the present time: ► see thesaurus at after</div><ul class=\"examples\"><li><em>I’m going out for a bit – I’ll see you later.</em></li><li><strong><em>two years/three weeks etc later</strong>: He became Senator two years later.</em></li><li><strong><em>later that day/morning/week etc</strong>: The baby died later that night.</em></li><li><strong><em>later in the day/week/year</strong>: The dentist could fit you in later in the week.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>later on</strong> at some time after the present time:</div><ul class=\"examples\"><li><em>I can’t eat all of this – I’ll finish it later on.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>not later than something</strong> used to say that something must be done by a particular time in the future:</div><ul class=\"examples\"><li><em>Completed entry forms should arrive not later than 31st July.</em></li></ul></div>","3966":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lat‧est</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleɪtɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the most recent or the newest:</div><ul class=\"examples\"><li><em>all the latest gossip</em></li><li><em>His latest film is one of the funniest he’s ever made.</em></li></ul></div>","3967":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lat‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlætə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>the latter</strong> <em>formal</em> the second of two people or things just mentioned <em>OPP former</em>:</div><ul class=\"examples\"><li><em>Where unemployment and crime are high, it can be assumed that the latter is due to the former.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> being the second of two people or things, or the last in a list just mentioned <em>OPP former</em>:</div><ul class=\"examples\"><li><em>In the latter case, buyers pay a 15% commission.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the latter part of a period of time is nearest to the end of it:</div><ul class=\"examples\"><li><em>Celebrations are planned for the latter part of November.</em></li></ul></div></div>","3968":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɑːf $ læf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> to make sounds with your voice, usually while you are smiling, because you think something is funny:</div><ul class=\"examples\"><li><em>Maria looked at him and laughed.</em></li><li><strong><em>laugh at/about</strong>: ‘I didn’t know what I was doing,’ she said, laughing at the memory.</em></li><li><em>Tony was laughing so hard he had to steady himself on the table.</em></li><li><em>Nora laughed so much that she nearly cried.</em></li><li><strong><em>laugh heartily/uproariously/hysterically etc</strong> (=laugh a lot): The kids tumbled around on the floor, laughing hysterically.</em></li><li><em>He couldn’t help it; he burst out laughing (=suddenly started laughing).</em></li><li><strong><em>laugh your head off</em></strong></li><li><em>He’s one of the few writers who can make me laugh out loud.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to say something in a voice that shows you are amused:</div><ul class=\"examples\"><li><em>‘You look ridiculous!’ Nick laughed.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>not know whether to laugh or cry</strong> to feel upset or annoyed about something bad that has happened, but also able to see that there is something funny about it:</div><ul class=\"examples\"><li><em>And when I couldn’t find the passports – honestly, I didn’t know whether to laugh or cry!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>don’t make me laugh</strong> <em>spoken</em> used when someone has just told you something that is completely untrue, asked for something impossible etc:</div><ul class=\"examples\"><li><em>‘Can you finish this by tomorrow?’ ‘Don’t make me laugh.’</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>no laughing matter</strong> <em>informal</em> something serious that should not be joked about:</div><ul class=\"examples\"><li><em>It’s no laughing matter having to walk by a group of rowdy drunks every night just to get home.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be laughed out of court</strong> (also be laughed out of town/business etc<em>American English</em>) if a person or idea is laughed out of court etc, the idea is not accepted because people think it is completely stupid:</div><ul class=\"examples\"><li><em>We can’t propose that! We’d be laughed out of court!</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>you have to laugh</strong> <em>spoken</em> used to say that, even though a situation is annoying or disappointing, you can also see that there is something funny about it</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>be laughing all the way to the bank</strong> <em>informal</em> to make a lot of money without making much effort</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>somebody will be laughing on the other side of their face</strong> <em>spoken</em> used to say that although someone is happy or confident now, they will be in trouble later</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>be laughing</strong> <em>British English</em> <em>spoken</em> <em>informal</em> to be happy or in a good situation, for example because something has had a successful result for you:</div><ul class=\"examples\"><li><em>Well they paid me, didn’t they, so I’m laughing.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>laugh in somebody’s face</strong> to behave towards someone in a way that shows that you do not respect them:</div><ul class=\"examples\"><li><em>I told my sister what I thought, and she just laughed in my face.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>laugh up your sleeve</strong> to be secretly happy, especially because you have played a trick on someone or criticized them without them knowing</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> the act of laughing or the sound you make when you laugh:</div><ul class=\"examples\"><li><em>He gave a short laugh.</em></li><li><strong><em>with a laugh</strong>: ‘What a mess!’ she said, with a laugh.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> if something is a laugh, you have fun and enjoy yourself when you are doing it:</div><ul class=\"examples\"><li><em>We all went to the beach last night – it was a really good laugh.</em></li><li><em>The other campers were nice, and we had a great laugh together.</em></li><li><em>It was a great holiday with lots of laughs.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>somebody is a (good) laugh</strong> <em>British English</em> used to say that someone is amusing and fun to be with:</div><ul class=\"examples\"><li><em>I like Peter – he’s a good laugh.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>for laughs</strong> (also for a laugh<em>British English</em>) for fun:</div><ul class=\"examples\"><li><em>We took the hot-air balloon ride, just for laughs.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>that’s a laugh</strong> <em>spoken</em> used to say that something is silly or unlikely:</div><ul class=\"examples\"><li><em>Me? Star in a film? That’s a laugh.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>have the last laugh</strong> to finally be successful, win an argument etc, after other people have earlier criticized you, defeated you etc:</div><ul class=\"examples\"><li><em>Men make jokes about women drivers, but women have the last laugh – their insurance rates are cheaper.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>be a laugh a minute</strong> <em>informal</em> to be very funny – sometimes used humorously to mean that someone or something is not at all funny</div></div></div>","3969":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> laugh‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɑːftə $ ˈlæftər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">when people laugh, or the sound of people laughing:</div><ul class=\"examples\"><li><em>Foster joined in the laughter.</em></li><li><em>He looked shocked, then burst into laughter (=started laughing).</em></li><li><strong><em>roar/scream/shriek with laughter</strong> (=laugh very loudly): Audiences roared with laughter.</em></li><li><em>He shook with laughter.</em></li><li><strong><em>peals/gales/howls etc of laughter</strong> (=loud laughs): The comment brought peals of laughter from her classmates.</em></li></ul></div>","3970":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɔːntʃ $ lɒːntʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[start something]</strong> to start something, usually something big or important:</div><ul class=\"examples\"><li><em>The organization has launched a campaign to raise $150,000.</em></li><li><em>The Canadian police plan to launch an investigation into the deal.</em></li><li><strong><em>launch an attack/assault/offensive</strong>: The press launched a vicious attack on the president.</em></li><li><em>The book launched his career as a novelist.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[product]</strong> to make a new product, book etc available for sale for the first time:</div><ul class=\"examples\"><li><em>The company hopes to launch the new drug by next October.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[boat]</strong> to put a boat or ship into the water</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[sky/space]</strong> to send a weapon or spacecraft into the sky or into space: ► see thesaurus at shoot</div><ul class=\"examples\"><li><em>A test satellite was launched from Cape Canaveral.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[computer]</strong> to make a computer program start <em>SYN open</em>:</div><ul class=\"examples\"><li><em>Double-click on an icon to launch an application.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>launch yourself forwards/up/from etc</strong> to jump up and forwards into the air with a lot of energy</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> when a new product, book etc is made available or made known</div><ul class=\"examples\"><li><strong><em>launch of</strong>: the launch of a new women’s magazine</em></li><li><em>a new product launch</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a large boat with a motor</div><div class=\"sense\"><span class=\"snum\">3</span> when a weapon or spacecraft is sent into the sky or into space</div></div></div>","3971":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> laun‧dry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɔːndri $ ˈlɒːn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\">(plural laundries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> clothes, sheets etc that need to be washed or have just been washed:</div><ul class=\"examples\"><li><em>She did the laundry (=washed the clothes etc) and hung it out to dry.</em></li><li><em>Ben was folding laundry.</em></li><li><strong><em>clean/dirty laundry</strong>: a pile of dirty laundry</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a place or business where clothes etc are washed and ironed</div></div>","3972":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lav‧a‧to‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlævətəri $ -tɔːri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural lavatories)</span></div><div class=\"entry-body\"><div class=\"sense\"><em>formal</em> a toilet or the room a toilet is in</div></div>","3973":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lav‧ish</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlævɪʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> large, impressive, or expensive:</div><ul class=\"examples\"><li><em>a royal palace on a lavish scale</em></li><li><em>a lavish lifestyle</em></li><li><em>The food was lavish.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> very generous</div><ul class=\"examples\"><li><strong><em>lavish with/in</strong>: We were always lavish with financial aid in times of crisis. / He was always lavish in his praise of my efforts.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to give someone or something a lot of love, praise, money etc</div><ul class=\"examples\"><li><strong><em>lavish something on/upon somebody</strong>: He lavished attention on her.</em></li><li><strong><em>lavish somebody with something</strong>: Hug your children and lavish them with love.</em></li></ul></div></div>","3974":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɔː $ lɒː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[system of rules]</strong> <span class=\"gram\">[uncountable]</span> (also the law) the whole system of rules that people in a particular country or area must obey:</div><ul class=\"examples\"><li><em>Elected officials ought to obey the law.</em></li><li><strong><em>by law</strong>: By law, seat belts must be worn by all passengers.</em></li><li><strong><em>under English/international etc law</strong>: This is illegal under English law.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[a rule]</strong> <span class=\"gram\">[countable]</span> a rule that people in a particular country or area must obey: ► see thesaurus at rule</div><ul class=\"examples\"><li><em>laws passed by Parliament</em></li><li><strong><em>under a law</strong>: Five people arrested under anti-terrorism laws were released without charge.</em></li><li><strong><em>law on</strong>: European laws on equal opportunities</em></li><li><strong><em>law against</strong>: The laws against drug use were very strict.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>law and order</strong> a situation in which people respect the law, and crime is controlled by the police, the prison system etc:</div><ul class=\"examples\"><li><em>We are concerned about the breakdown of law and order in the country.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[police]</strong> <strong>the law</strong> the police:</div><ul class=\"examples\"><li><em>I think she may be in trouble with the law.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[what always happens]</strong> <span class=\"gram\">[countable]</span> something that always happens in nature or society, or a statement that describes this</div><ul class=\"examples\"><li><strong><em>law of</strong>: the law of supply and demand / the laws of nature / the law of gravity</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[study/profession]</strong> <span class=\"gram\">[uncountable]</span> (also the law) law as a subject of study, or the profession of being a lawyer:</div><ul class=\"examples\"><li><em>She’s studying law in London.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[sport/activity]</strong> <span class=\"gram\">[countable]</span> one of the rules which controls a sport or activity:</div><ul class=\"examples\"><li><em>the laws of football</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>the law of the jungle</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the idea that people should only look after themselves and not care about other people if they want to succeed</div><div class=\"subsense\"><span class=\"subnum\">b)</span> the principle that only the strongest creatures will stay alive</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>the law of averages</strong> the probability that one result will happen as often as another if you try something often enough:</div><ul class=\"examples\"><li><em>The law of averages says we’ll win at least once.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>be a law unto himself/herself etc</strong> to behave in an independent way and not worry about the usual rules of behaviour or what other people do or think:</div><ul class=\"examples\"><li><em>Boys his age are a law unto themselves.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>take the law into your own hands</strong> to do something illegal in order to put right something that you think is not fair, for example by violently punishing someone instead of telling the police:</div><ul class=\"examples\"><li><em>vigilantes who take the law into their own hands</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>go to law</strong> to go to court in order to settle a problem:</div><ul class=\"examples\"><li><em>the right of consumers to go to law if they need to</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>be above the law</strong> someone who is above the law does not have to obey the law:</div><ul class=\"examples\"><li><em>Many ministers seem to regard themselves as being above the law.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>there’s no law against something</strong> <em>spoken</em> used to tell someone who is criticizing you that you are not doing anything wrong</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>there ought to be a law against something</strong> <em>spoken</em> used to say that you do not think something should be accepted or allowed:</div><ul class=\"examples\"><li><em>There ought to be a law against cutting off power supplies in the middle of February.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>somebody’s word is law</strong> used to say that someone is always obeyed without argument</div></div>","3975":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> law‧ful</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɔːfəl $ ˈlɒː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">allowed or recognized by law <em>SYN legal</em>:</div><ul class=\"examples\"><li><em>It is not lawful to kill or injure a pet animal.</em></li><li><em>a lawful arrest</em></li><li><em>his lawful wife</em></li></ul></div>","3976":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> law‧mak‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɔːmeɪkə $ ˈlɒːmeɪkər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>especially American English</em> any elected official responsible for making laws <em>SYN legislator</em></div></div>","3977":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɔːn $ lɒːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> an area of ground in a garden or park that is covered with short grass:</div><ul class=\"examples\"><li><em>I spent all morning mowing the lawn (=cutting the grass).</em></li><li><em>a carefully tended lawn</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a fine cloth made from cotton or linen</div></div>","3978":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> law‧suit</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɔːsuːt, -sjuːt $ ˈlɒːsuːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a problem or complaint that a person or organization brings to a court of law to be settled <em>SYN suit</em></div><ul class=\"examples\"><li><strong><em>lawsuit against</strong>: His lawyer filed a lawsuit against the city.</em></li></ul></div>","3979":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> law‧yer</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɔːjə $ ˈlɒːjər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone whose job is to advise people about laws, write formal agreements, or represent people in court</div></div>","3980":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /leɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\">(past tense and past participle laid /leɪd/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[put somebody/something down]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to put someone or something down carefully into a flat position <em>SYN place</em>: ► see thesaurus at put</div><ul class=\"examples\"><li><em>He laid his hand on my shoulder.</em></li><li><em>They laid a wreath at the place where so many people died.</em></li><li><em>Lay the material flat on the table.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>lay bricks/carpet/concrete/cables etc</strong> to put or fasten bricks, a carpet etc in the correct place, especially on the ground or floor:</div><ul class=\"examples\"><li><em>The carpet was laid last week.</em></li><li><em>The project involved laying an oil pipeline across the desert.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[bird/insect etc]</strong> <span class=\"gram\">[intransitive, transitive]</span> if a bird, insect etc lays eggs, it produces them from its body:</div><ul class=\"examples\"><li><em>The flies lay their eggs on decaying meat.</em></li><li><em>A cuckoo is able to lay in a range of different nests.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[table]</strong> <span class=\"gram\">[transitive]</span> <em>British English</em> to put the cloth, plates, knives, forks etc on a table, ready for a meal <em>SYN set</em>:</div><ul class=\"examples\"><li><em>John was laying the table.</em></li><li><em>As she spoke, she was laying him a place at the table.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>lay the foundations/groundwork/base</strong> to provide the conditions that will make it possible for something to happen or be successful</div><ul class=\"examples\"><li><strong><em>lay for</strong>: Mandela helped lay the foundations for a new democratic South Africa.</em></li><li><em>It was an invention which laid the foundations of modern radio technology.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[give information]</strong> <span class=\"gram\">[transitive]</span> <em>formal</em> to make a statement, give information etc in an official or public way <em>SYN put</em>:</div><ul class=\"examples\"><li><em>Several proposals have been laid before the committee.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>lay emphasis/stress on something</strong> <em>formal</em> to emphasize something because you believe it is very important:</div><ul class=\"examples\"><li><em>a political philosophy that lays great stress on individual responsibility</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>lay a hand/finger on somebody</strong> <span class=\"gram\">[usually in negatives]</span> to touch someone with the intention of hurting them:</div><ul class=\"examples\"><li><em>I swear I didn’t lay a finger on him.</em></li><li><em>If you lay one hand on me, I’ll scream.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>lay something bare/open</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to show what something is really like, or stop hiding facts, feelings etc:</div><ul class=\"examples\"><li><em>Every aspect of their private life has been laid bare.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to remove the thing that is covering or hiding something else:</div><ul class=\"examples\"><li><em>When the tide goes out, vast stretches of sand are laid bare.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>lay somebody/something open to something</strong> to do something that makes it possible for other people to blame you, criticize you etc</div><ul class=\"examples\"><li><strong><em>lay yourself open to something</strong>: By doing that, he laid himself open to ridicule.</em></li><li><em>Not to have taken action would have laid the department open to charges of negligence.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>lay waste something</strong> (also lay waste to something) <em>formal</em> to destroy or damage something, especially in a war:</div><ul class=\"examples\"><li><em>The island was laid waste and abandoned.</em></li><li><em>an attack which laid waste to hundreds of villages</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>lay plans/a trap etc</strong> to carefully prepare all the details of something:</div><ul class=\"examples\"><li><em>We are laying plans now in order to be successful in the future.</em></li><li><strong><em>the best-laid plans</strong> (=plans that have been made carefully): Bad weather can upset even the best-laid travel plans.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>lay claim to (doing) something</strong> to say that something belongs to you or say that you deserve something:</div><ul class=\"examples\"><li><em>The town can lay claim to having the oldest theatre in Britain.</em></li><li><em>No one has laid claim to the property.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>lay siege to somebody/something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if a group of people lay siege to a place, they try to get control by surrounding it:</div><ul class=\"examples\"><li><em>The armies laid siege to Vienna in 1529.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to do everything you can to get someone to talk to you or notice you:</div><ul class=\"examples\"><li><em>A group of young men were always at the stage door, trying to lay siege to the girls.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[have sex]</strong> <strong>get laid</strong> <em>informal</em> to have sex with someone:</div><ul class=\"examples\"><li><em>All he wants to do is go out and get laid.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[lie]</strong> <span class=\"gram\">[intransitive]</span> <em>spoken</em> to be in a position in which you are flat – some people consider this use to be incorrect <em>SYN lie</em></div><div class=\"sense\"><span class=\"snum\">17</span> <strong>[risk money]</strong> <span class=\"gram\">[transitive]</span> <em>especially British English</em> to risk an amount of money on the result of a race, sports game etc <em>SYN bet</em></div><ul class=\"examples\"><li><strong><em>lay something on something</strong>: She laid £50 on the favourite, Golden Boy.</em></li><li><strong><em>lay money (that)</strong>: I’d lay money that he will go on to play for England.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>lay somebody/something on the line</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to state something, especially a threat, demand, or criticism, in a very clear way:</div><ul class=\"examples\"><li><em>Lay it on the line and tell them what’s really been happening.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> (also put somebody/something on the line) to risk losing your life, your job etc, especially in order to help someone:</div><ul class=\"examples\"><li><em>I’ve laid myself on the line for him once already.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>lay something at the door of somebody/something</strong> (also lay something at somebody’s door) to blame something or someone for something:</div><ul class=\"examples\"><li><em>The continued divisions within the party cannot be laid entirely at his door.</em></li><li><em>Many illnesses are being laid at the door of stress.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>lay somebody low</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if an illness lays someone low, they are unable to do their normal activities for a period of time GRAMMAR Lay low is usually passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be laid low with something</strong>: She’s been laid low with flu for a week.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>literary</em> to make someone fall down, or injure them seriously</div><div class=\"sense\"><span class=\"snum\">21</span> <strong>lay somebody to rest</strong> <em>formal</em> to bury someone after they have died: → lay/put something to rest at rest1(10)</div><ul class=\"examples\"><li><em>She was laid to rest beside her husband.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>lay the ghost (of something)</strong> to finally stop being worried or upset by something from the past</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"subsense\"><span class=\"subnum\">a)</span> not trained or not knowing much about a particular profession or subject → layman:</div><ul class=\"examples\"><li><em>lay witnesses</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> not in an official position in the church:</div><ul class=\"examples\"><li><em>a lay preacher</em></li></ul></div></div>","3981":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lay‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleɪə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an amount or piece of a material or substance that covers a surface or that is between two other things → ozone layer</div><ul class=\"examples\"><li><strong><em>layer of</strong>: A thick layer of dust lay on the furniture. / The moon was shining through a thin layer of cloud. / He pulled off layer upon layer of clothing (=many layers of clothing).</em></li><li><strong><em>in layers</strong>: Arrange the peppers, garlic and tomatoes in layers.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> one of several different levels in a complicated organization, system, set of ideas etc</div><ul class=\"examples\"><li><strong><em>layer of</strong>: We are operating with fewer layers of management. / There are multiple layers of meaning in the story.</em></li><li><em>the multi-layered nature of organizations (=they have many layers)</em></li></ul></div>","3982":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lay‧out</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleɪaʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the way in which something such as a town, garden, or building is arranged</div><ul class=\"examples\"><li><strong><em>layout of</strong>: the layout of the park</em></li><li><em>All the flats in the building had the same layout.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the way in which writing and pictures are arranged on a page</div><ul class=\"examples\"><li><strong><em>layout of</strong>: the layout of a business letter</em></li><li><em>page layout software</em></li></ul></div>","3983":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> la‧zy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleɪzi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\">(comparative lazier, superlative laziest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not liking work and physical activity, or not making any effort to do anything:</div><ul class=\"examples\"><li><em>the laziest boy in the class</em></li><li><em>He felt too lazy to get out of bed.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a lazy period of time is spent doing nothing except relaxing <em>OPP busy</em>:</div><ul class=\"examples\"><li><em>We spent lazy days relaxing on the beach.</em></li></ul></div>","3984":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /liːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle led /led/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[take somebody somewhere]</strong> <span class=\"gram\">[intransitive, transitive usually + adverb/preposition]</span> to take someone somewhere by going in front of them while they follow, or by pulling them gently ► see thesaurus at take</div><ul class=\"examples\"><li><strong><em>lead somebody to/into etc something</strong>: A nurse took her arm and led her to a chair. / The horses were led to safety.</em></li><li><strong><em>lead somebody away/down etc</strong>: She was led away from the courtroom in tears.</em></li><li><em>The manager led the way through the office.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[go in front]</strong> <span class=\"gram\">[intransitive, transitive]</span> to go in front of a line of people or vehicles:</div><ul class=\"examples\"><li><em>A firetruck was leading the parade.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[be in charge]</strong> <span class=\"gram\">[intransitive, transitive]</span> to be in charge of an organization, country, or team, or a group of people who are trying to do something:</div><ul class=\"examples\"><li><em>He has led the party for over twenty years.</em></li><li><em>Some people say she is too old to lead the country (=be in charge of its government).</em></li><li><em>Beckham led his team to victory.</em></li><li><strong><em>lead an investigation/inquiry/campaign</strong>: The investigation will be led by Inspector Scarfe. / They are leading a campaign to warn teenagers about the dangers of drug abuse.</em></li><li><strong><em>lead a revolt/rebellion/coup etc</strong>: The rebellion was led by the King’s brother.</em></li><li><strong><em>lead an attack/assault</strong>: Nelson preferred to lead the attack himself from the front.</em></li><li><em>a man who was born to lead</em></li><li><em>a communist-led strike</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[cause something to happen]</strong> <span class=\"gram\">[intransitive, transitive]</span> to cause something to happen or cause someone to do something</div><ul class=\"examples\"><li><strong><em>lead to</strong>: the events that led to the start of the First World War / A degree in English could lead to a career in journalism.</em></li><li><strong><em>lead somebody into something</strong>: Her trusting nature often led her into trouble.</em></li><li><strong><em>lead somebody to do something</strong>: What led him to kill his wife?</em></li><li><strong><em>lead to somebody doing something</strong>: His actions could lead to him losing his job.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[cause somebody to believe something]</strong> <span class=\"gram\">[transitive]</span> to make someone believe something, especially something that is not true</div><ul class=\"examples\"><li><strong><em>lead somebody to believe/expect/understand something</strong>: He had led everyone to believe that his family was very wealthy. / The hotel was terrible, and not at all what we had been led to expect.</em></li><li><em>Our research led us to the conclusion that the present system is unfair.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[influence]</strong> <span class=\"gram\">[transitive]</span> to influence someone to make them do something that is wrong</div><ul class=\"examples\"><li><strong><em>lead somebody into something</strong>: His brother led him into a life of crime.</em></li><li><em>He’s not a bad boy. He’s just easily led (=it is easy for other people to persuade him to do things that he should not do).</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[be more successful]</strong> <span class=\"gram\">[transitive]</span> to be more successful than other people, companies, or countries in a particular activity → leading1(1)</div><ul class=\"examples\"><li><strong><em>lead the world/market/pack/field</strong>: US companies lead the world in biotechnology.</em></li><li><strong><em>lead the way</strong> (=be the first to do something, and show other people how to do it): The Swedes have led the way in data protection.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[be winning]</strong> <span class=\"gram\">[intransitive, transitive]</span> to be winning a game, competition etc <em>OPP lose</em>:</div><ul class=\"examples\"><li><em>At half-time, Brazil led 1–0.</em></li><li><em>With 15 laps to go, Schumacher led the race.</em></li><li><em>The polls showed Obama leading Romney by 3 percent.</em></li><li><strong><em>lead by ten points/two goals etc</strong>: Nadal was leading by two sets.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[path/door etc]</strong> <span class=\"gram\">[intransitive, transitive always + adverb/preposition]</span> used to say where a path, wire etc goes or what place is on the other side of a door</div><ul class=\"examples\"><li><strong><em>lead to/towards</strong>: The path led down to a small lake.</em></li><li><strong><em>lead from/out of</strong>: the major artery leading from the heart</em></li><li><strong><em>lead into</strong>: the door leading into the hallway</em></li><li><strong><em>lead somebody to/into something</strong>: The riverside path leads visitors to a small chapel.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[life]</strong> <span class=\"gram\">[transitive]</span> if you lead a particular kind of life, that is what your life is like</div><ul class=\"examples\"><li><strong><em>lead a normal/quiet/busy etc life</strong>: If the operation succeeds, Carly will be able to lead a normal life. / He has led a charmed life (=been very fortunate).</em></li><li><strong><em>lead a life of luxury/poverty etc</em></strong></li><li><strong><em>lead the life of a...</strong>: She now leads the life of a recluse.</em></li><li><strong><em>lead a double life</strong> (=deceive people by keeping different parts of your life separate and not letting anyone know the whole truth): Joe had been leading a double life, seeing an ex-model while his wife believed he was on business.</em></li><li><em>They lead a nomadic existence.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[discussion etc]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to control the way a discussion, conversation etc develops:</div><ul class=\"examples\"><li><em>I tried to lead the conversation back to the subject of money.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>lead somebody up the garden path</strong> <em>informal</em> to deliberately deceive someone</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>lead somebody astray</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to encourage someone to do bad or immoral things which they would not normally do</div><div class=\"subsense\"><span class=\"subnum\">b)</span> to make someone believe something that is not true</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>lead nowhere/not lead anywhere</strong> to not produce any useful result:</div><ul class=\"examples\"><li><em>So far police investigations seem to have led nowhere.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>lead by example</strong> to show the people you are in charge of what you want them to do by doing it yourself:</div><ul class=\"examples\"><li><em>The best managers lead by example.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>lead somebody by the nose</strong> to influence someone so much that you can completely control everything that they do:</div><ul class=\"examples\"><li><em>Politicians think they can easily lead people by the nose.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>this/that leads (me) to something</strong> used to introduce a new subject that is connected to the previous one:</div><ul class=\"examples\"><li><em>That leads me to my final point. Where are we going to get the money?</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>somebody has their own life to lead</strong> used to say that someone wants to be able to live their life independently, without having to do things that other people want them to do</div><div class=\"sense\"><span class=\"snum\">19</span> <strong>lead somebody a merry old dance/a right old dance</strong> <em>British English</em> to cause a lot of problems or worries for someone</div><div class=\"sense\"><span class=\"snum\">20</span> <strong>market-led/export-led etc</strong> most influenced by the market, by exports etc:</div><ul class=\"examples\"><li><em>an export-led economic recovery</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>lead the eye</strong> if a picture, view etc leads the eye in a particular direction, it makes you look in that direction:</div><ul class=\"examples\"><li><em>marble columns that lead the eye upward</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>[card game]</strong> <span class=\"gram\">[intransitive, transitive]</span> to play a particular card as your first card in one part of a card game</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the lead</strong> the first position in a race or competition:</div><ul class=\"examples\"><li><em>She was in the lead from start to finish.</em></li><li><em>The Canadians went into the lead after only 30 seconds.</em></li><li><em>The goal put Holland into the lead.</em></li><li><em>The Bears took the lead for the first time this season.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> the amount or distance by which one competitor is ahead of another:</div><ul class=\"examples\"><li><em>The Chicago Bulls had a narrow lead (=were winning by a small number of points).</em></li><li><strong><em>lead over</strong>: The Socialists now have a commanding lead over their opponents.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> if someone follows someone else’s lead, they do the same as the other person has done:</div><ul class=\"examples\"><li><em>Other countries are likely to follow the U.S.&#x27;s lead.</em></li><li><em>The Government should give industry a lead in tackling racism (=show what other people should do).</em></li><li><em>The black population in the 1960s looked to Ali for a lead (=looked to him to show them what they should do).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>take the lead (in doing something)</strong> to be the first to start doing something or be most active in doing something:</div><ul class=\"examples\"><li><em>The U.S. took the lead in declaring war on terrorism.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> a piece of information that may help you to solve a crime or mystery <em>SYN clue</em>:</div><ul class=\"examples\"><li><em>The police have checked out dozens of leads, but have yet to find the killer.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[countable]</span> the main acting part in a play, film etc, or the main actor</div><ul class=\"examples\"><li><strong><em>play the lead/the lead role</strong>: He will play the lead role in ‘Hamlet’.</em></li><li><em>Powers was cast in the lead role (=he was chosen to play it).</em></li><li><strong><em>the male/female lead</strong>: They were having trouble casting the female lead.</em></li><li><em>the film’s romantic lead</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>lead singer/guitarist etc</strong> the main singer, guitarist etc in a group</div><ul class=\"examples\"><li><strong><em>lead of/with</strong>: the lead singer of Nirvana</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <span class=\"gram\">[countable]</span> <em>British English</em> a piece of rope, leather, or chain for holding or controlling a dog <em>SYN leash</em></div><ul class=\"examples\"><li><strong><em>on a lead</strong>: All dogs must be kept on a lead.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <span class=\"gram\">[countable]</span> <em>British English</em> a wire used to connect a piece of electrical equipment to the power supply SYN cord<em>American English</em> → jump leads</div></div></div>","3985":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lead‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈliːdə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[in control]</strong> the person who directs or controls a group, organization, country etc → ruler</div><ul class=\"examples\"><li><strong><em>leader of</strong>: the leader of the local black community</em></li><li><strong><em>party/union/government/opposition etc leader</em></strong></li><li><strong><em>political/military/religious leader</em></strong></li><li><em>the largest ever gathering of world leaders (=people who are in charge of countries)</em></li><li><strong><em>natural/born leader</strong> (=someone who naturally has all the qualities needed to be a leader): His air of confidence makes him a natural leader.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[competition]</strong> the person or group that is in front of all the others in a race or competition:</div><ul class=\"examples\"><li><em>County Championship leaders of Hampshire</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[product/company]</strong> the product or company that is the best or most successful</div><ul class=\"examples\"><li><strong><em>leader in</strong>: a world leader in defence and space electronics</em></li><li><em>These products are firmly established as the market leaders.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[newspaper]</strong> <em>British English</em> a piece of writing in a newspaper giving the paper’s opinion on a subject <em>SYN editorial</em>:</div><ul class=\"examples\"><li><em>‘The Times’ leader column</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[musician]</strong> <em>British English</em> the main violin player in an orchestra SYN concertmaster<em>American English</em></div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[musical director]</strong> <em>American English</em> someone who directs the playing of a musical group SYN conductor<em>British English</em></div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[tape]</strong> <em>technical</em> the part at the beginning of a film or recording tape which has nothing on it</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[branch]</strong> <em>technical</em> a long thin branch that grows from the stem of a bush or tree beyond other branches</div></div>","3986":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lead‧er‧ship</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈliːdəʃɪp $ -ər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the position of being the leader of a group, organization, country etc</div><ul class=\"examples\"><li><strong><em>leadership of</strong>: the leadership of the Labour party</em></li><li><strong><em>under somebody’s leadership</strong>: Our prospects of winning an election will be better under his leadership.</em></li><li><em>The US must now take a firm leadership role.</em></li><li><em>the Conservative leadership contest</em></li><li><em>The next leadership election is due in November.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the quality of being good at leading a group, organization, country etc:</div><ul class=\"examples\"><li><em>She has great faith in her own leadership qualities.</em></li><li><em>someone with vision and leadership</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> <em>British English</em> all the people who lead a group, organization, country etc: GRAMMAR: Singular or plural verb?• In this meaning, leadership is usually followed by a singular verb: · The leadership supports the change in the law.• In British English, you can also use a plural verb: · The leadership support the change in the law.Grammar guide ‒ NOUNS</div><ul class=\"examples\"><li><em>the country’s military leadership</em></li><li><em>The party leadership is in agreement.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> the position of being in front of others in an activity or competition:</div><ul class=\"examples\"><li><em>Leadership in science is important to our nation.</em></li></ul></div>","3987":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lead‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈliːdɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> best, most important, or most successful:</div><ul class=\"examples\"><li><em>The army played a leading role in organizing the attempted coup.</em></li><li><em>the leading industrial nations</em></li><li><em>a leading heart specialist</em></li><li><em>leading members of the government</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>leading edge</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>technical</em> the part of something that is at the front of it when it moves</div><div class=\"subsense\"><span class=\"subnum\">b)</span> the part of an activity where the most modern and advanced equipment and methods are used → leading-edge</div><ul class=\"examples\"><li><strong><em>leading of</strong>: This is the leading edge of medical technology.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>leading light</strong> a respected person who leads a group or organization, or is important in a particular area of knowledge or activity:</div><ul class=\"examples\"><li><em>The two women were leading lights of the women’s union.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>leading question</strong> a question that deliberately tricks someone into giving the answer you want:</div><ul class=\"examples\"><li><em>Don’t ask leading questions.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>leading lady/man</strong> the woman or man who acts the most important female or male part in a film, play etc</div></div>","3988":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /liːf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\">(plural leaves /liːvz/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[plant]</strong> <span class=\"gram\">[countable]</span> one of the flat green parts of a plant that are joined to its stem or branches:</div><ul class=\"examples\"><li><em>a flowering bush with large shiny leaves</em></li><li><strong><em>leaf of</strong>: Add a few leaves of fresh basil to the salad.</em></li><li><strong><em>be in leaf/come into leaf</strong> (=have or start growing leaves, at a particular time of year): The forest was just coming into leaf.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>take a leaf out of somebody’s book</strong> to copy the way someone else behaves because you want to be like them or be as successful as they are:</div><ul class=\"examples\"><li><em>They are committing $3m to research. We could take a leaf out of their book.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>turn over a new leaf</strong> to change the way you behave and become a better person:</div><ul class=\"examples\"><li><em>I see fatherhood as a chance to turn over a new leaf.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[page]</strong> <span class=\"gram\">[countable]</span> <em>formal</em> a page of a book: → loose-leaf, overleaf</div><ul class=\"examples\"><li><em>He slipped the letter between the leaves of his notebook.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[part of table]</strong> <span class=\"gram\">[countable]</span> a part of the top of a table that can be taken out to make the table smaller</div></div>","3989":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> leaf‧let</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈliːflɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a small book or piece of paper advertising something or giving information on a particular subject</div><ul class=\"examples\"><li><strong><em>leaflet on</strong>: a leaflet on skin cancer</em></li><li><strong><em>hand/pass/give/send out a leaflet</strong>: Students were handing out election leaflets at the station.</em></li></ul></div>","3990":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /liːɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a group of sports teams or players who play games against each other to see who is best:</div><ul class=\"examples\"><li><em>He makes his football league debut tomorrow.</em></li><li><em>the Rugby League Championship</em></li><li><strong><em>be (at the) top/bottom of the league</strong> (=be the best or the worst team in a group)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a group of people or countries who have joined together because they have similar aims, political beliefs etc:</div><ul class=\"examples\"><li><em>the National Socialist League</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>not be in the same league (as somebody/something)</strong> to be not nearly as good or important as someone or something else:</div><ul class=\"examples\"><li><em>They’re not in the same league as the French at making wine.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be in a different league</strong> to be much better than someone or something else:</div><ul class=\"examples\"><li><em>For most of the match, Brazil were in a different league, and won 4–0.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be out of your league</strong> to not be skilled or experienced enough to do or deal with something</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>be in league (with somebody)</strong> to be working with someone secretly, especially for a bad purpose:</div><ul class=\"examples\"><li><em>Vernon was accused by his enemies of being in league with the devil.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> an ancient unit for measuring distance, equal to three miles or about 4,828 metres on land, and three nautical miles or 5,556 metres at sea</div></div>","3991":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /liːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> if a container, pipe, roof etc leaks, or if it leaks gas, liquid etc, there is a small hole or crack in it that lets gas or liquid flow through:</div><ul class=\"examples\"><li><em>The roof is leaking.</em></li><li><em>A tanker is leaking oil off the coast of Scotland.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if a gas or liquid leaks somewhere, it gets through a hole in something <em>SYN seep</em></div><ul class=\"examples\"><li><strong><em>leak into/from/out</strong>: Sea water was leaking into the batteries which powered the electric motors.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to deliberately give secret information to a newspaper, television company etc: ► see thesaurus at reveal</div><ul class=\"examples\"><li><em>The report’s findings had been leaked.</em></li><li><strong><em>leak something to somebody</strong>: civil servants who leak information to the press</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small hole that lets liquid or gas flow into or out of something: ► see thesaurus at hole</div><ul class=\"examples\"><li><em>There is a leak in the ceiling.</em></li><li><em>The boat had sprung a leak (=a hole had appeared in it).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a gas/oil/water etc leak</strong> an escape of gas or liquid through a hole in something:</div><ul class=\"examples\"><li><em>A gas leak caused the explosion.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a situation in which secret information is deliberately given to a newspaper, television company etc:</div><ul class=\"examples\"><li><em>It became evident from the leaks that something important was going on.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>take/have a leak</strong> <em>informal</em> to get rid of waste liquid from your body <em>SYN urinate</em></div></div></div>","3992":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /liːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\">(past tense and past participle leaned or leant /lent/ especially British English)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to move or bend your body in a particular direction</div><ul class=\"examples\"><li><strong><em>lean forward/back/over etc</strong>: They were leaning forward, facing each other. / Lean back and enjoy the ride. / She leant towards him and listened.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to support yourself in a sloping position against a wall or other surface</div><ul class=\"examples\"><li><strong><em>lean against/on</strong>: He was leaning on the bridge, watching the boats go by.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive always + adverb/preposition]</span> to put something in a sloping position where it is supported, or to be in that position</div><ul class=\"examples\"><li><strong><em>lean (something) against/on something</strong>: A huge mirror was leaning against the wall. / He leant his bicycle against the fence.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive]</span> to slope or bend from an upright position:</div><ul class=\"examples\"><li><em>trees leaning in the wind</em></li></ul></div>","3993":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /liːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle leapt /lept/ especially British English, leaped especially American English)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[jump]</strong> ► see thesaurus at jump</div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to jump high into the air or to jump in order to land in a different place:</div><ul class=\"examples\"><li><em>She leapt over the fence.</em></li><li><em>The smaller animals can easily leap from tree to tree.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[transitive]</span> <em>literary</em> to jump over something:</div><ul class=\"examples\"><li><em>Brenda leaped the gate and ran across the field.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[move fast]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to move very quickly and with a lot of energy:</div><ul class=\"examples\"><li><em>I leapt up the stairs three at a time.</em></li><li><em>He leapt out of bed.</em></li><li><em>She leapt to her feet (=stood up quickly) and started shouting.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[increase]</strong> <span class=\"gram\">[intransitive]</span> to increase quickly and by a large amount <em>OPP tumble</em></div><ul class=\"examples\"><li><strong><em>leap to</strong>: Profits leapt to £376m. / He leapt 27 places to second spot.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>leap at the chance/opportunity</strong> to accept an opportunity very eagerly:</div><ul class=\"examples\"><li><em>I leapt at the chance of studying abroad.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>leap to somebody’s defence</strong> <em>British English</em>, leap to somebody’s defense<em>American English</em> to quickly defend someone:</div><ul class=\"examples\"><li><em>When her younger brother was being bullied she leapt to his defence.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[heart]</strong> <span class=\"gram\">[intransitive]</span> <em>literary</em> if your heart leaps, you feel a sudden surprise, happiness, or excitement:</div><ul class=\"examples\"><li><em>My heart leaped when I saw Paul at the airport.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a big jump <em>SYN bound</em>:</div><ul class=\"examples\"><li><em>He threw a stick into the river and the dog went after it in a flying leap.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a large increase or change</div><ul class=\"examples\"><li><strong><em>quantum/great/huge etc leap</strong>: a quantum leap (=very great increase or change) in population levels</em></li><li><strong><em>leap in</strong>: a 16% leap in pre-tax profits</em></li><li><strong><em>leap forward</strong>: the huge leap forward that took place in the 1980s</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>by/in leaps and bounds</strong> if something increases, develops, grows etc by leaps and bounds, it does it very quickly:</div><ul class=\"examples\"><li><em>Lifeboat technology has advanced by leaps and bounds.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a leap of (the) imagination</strong> (also an imaginative leap) a mental process that is needed to understand something difficult or see the connection between two very different ideas</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>leap in the dark</strong> something you do without knowing what will happen as a result</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>leap of faith</strong> something you do even though it involves a risk, hoping that it will have a good result</div></div></div>","3994":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɜːn $ lɜːrn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle learned or learnt /lɜːnt $ lɜːrnt/ especially British English)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[subject/skill]</strong> <span class=\"gram\">[intransitive, transitive]</span> to gain knowledge of a subject or skill, by experience, by studying it, or by being taught → teach: GRAMMAR: Patterns with learn• You learn to do something: · She’s learning to play the piano.• You learn how to do something: · She is learning how to play the piano. ✗Don’t say: She is learning playing the piano.Grammar guide ‒ VERBS</div><ul class=\"examples\"><li><em>What’s the best way to learn a language?</em></li><li><strong><em>learn (how) to do something</strong>: I learnt to drive when I was 17. / Hector spent the winter learning how to cope with his blindness.</em></li><li><em>The teacher’s task is to help the pupil learn.</em></li><li><strong><em>learn (something) from somebody</strong>: I learned a lot from my father.</em></li><li><strong><em>learn about</strong>: Kids can have fun and learn about music at the same time.</em></li><li><strong><em>learn what</strong>: Youngsters must learn what is dangerous and what is not to be feared.</em></li><li><em>The student will learn from experience about the importance of planning.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[find out]</strong> <span class=\"gram\">[intransitive, transitive]</span> <em>formal</em> to find out information or news by hearing it from someone else or reading it <em>SYN discover</em>:</div><ul class=\"examples\"><li><em>I didn’t tell her the truth. She would learn it for herself soon enough.</em></li><li><strong><em>learn of/about</strong>: He learned about his appointment by telephone yesterday.</em></li><li><strong><em>learn (that)</strong>: Last week I learned that I was pregnant. / She was surprised to learn that he was a lot older than she had thought.</em></li><li><strong><em>learn whether/who/why</strong>: I waited to learn whether I’d secured a college place. / We have yet to learn who will be the new manager.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[remember]</strong> <span class=\"gram\">[transitive]</span> to get to know something so well that you can easily remember it <em>SYN memorize</em>:</div><ul class=\"examples\"><li><em>The actors hardly had time to learn their lines before filming started.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[change your behaviour]</strong> <span class=\"gram\">[intransitive, transitive]</span> to gradually understand a situation and start behaving in the way that you should</div><ul class=\"examples\"><li><strong><em>learn (that)</strong>: They have to learn that they can’t just do whatever they like.</em></li><li><strong><em>learn to do something</strong>: Young hairdressers must learn to treat the client as a person, not a head of hair.</em></li><li><em>I’ve told him a hundred times not to bully people, but he never learns.</em></li><li><strong><em>learn from</strong>: You have to learn from your mistakes (=understand why what you did was wrong).</em></li><li><em>the lessons learned in the Gulf War</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>somebody has learned their lesson</strong> used to say that someone will not do something wrong or stupid again, because they suffered as a result:</div><ul class=\"examples\"><li><em>I’ve learned my lesson; I’ve now got a burglar alarm and a guard dog.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>learn (something) the hard way</strong> to understand a situation or develop a skill by learning from your mistakes and bad experiences</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>that’ll learn somebody!</strong> <em>spoken</em> used when something bad has just happened to someone as a result of their actions, especially when they ignored a warning</div></div>","3995":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> learn‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɜːnə $ ˈlɜːrnər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is learning to do something ► see thesaurus at student</div><ul class=\"examples\"><li><strong><em>learner of</strong>: a new dictionary for learners of business English</em></li><li><em>the needs of slow learners</em></li><li><em>attractive grammar books for adult learners</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also learner driver) <em>British English</em> someone who is learning to drive a car</div></div>","3996":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> learn‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɜːnɪŋ $ ˈlɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">knowledge gained through reading and study:</div><ul class=\"examples\"><li><em>a man of great learning</em></li></ul></div>","3997":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /liːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a legal agreement which allows you to use a building, car etc for a period of time, in return for rent</div><ul class=\"examples\"><li><strong><em>lease on</strong>: They took out a lease on a seven-acre field.</em></li><li><em>The landlord refused to renew his lease.</em></li><li><em>The 99-year lease expired in 1999.</em></li><li><em>Do you understand all the terms of the lease?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a new lease of life</strong> <em>especially British English</em>, a new lease on life<em>American English</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if something has a new lease of life, it is changed or repaired so that it can continue:</div><ul class=\"examples\"><li><em>Historic buildings can have a new lease of life through conversion.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if someone has a new lease of life, they become healthy, active, or happy again after being weak, ill, or tired:</div><ul class=\"examples\"><li><em>an operation to give her a new lease of life</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to use a building, car etc under a lease:</div><ul class=\"examples\"><li><em>I’m interested in leasing your cottage.</em></li><li><strong><em>lease something from somebody</strong>: They lease the site from the council.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also lease out) to let someone use a building, car etc under a lease</div><ul class=\"examples\"><li><strong><em>lease something to somebody</strong>: The building was leased to a health club.</em></li></ul></div></div>","3998":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /liːʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a piece of rope, leather etc fastened to a dog’s collar in order to control it SYN lead<em>British English</em></div><ul class=\"examples\"><li><strong><em>on/off a leash</strong>: At her side on a leash trotted a small grey dog. / Never leave your dog off the leash outside a store.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>keep/have somebody on a leash</strong> to control someone – used humorously:</div><ul class=\"examples\"><li><em>Marcus keeps you on a short leash, does he?</em></li></ul></div>","3999":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">determiner</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /liːst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>at least</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> not less than a particular number or amount:</div><ul class=\"examples\"><li><em>It will take you at least 20 minutes to get there.</em></li><li><em>He had at least £100,000 in savings.</em></li><li><strong><em>at the (very) least</strong> (=not less than and probably much more than): It would cost $1 million at the very least.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> even if something better is not true or is not done:</div><ul class=\"examples\"><li><em>At least he didn’t lie to me.</em></li><li><em>I don’t expect you to pay me, but you could at least cover my expenses.</em></li><li><em>The house still needed a lot of work, but at least the kitchen was finished.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> used when you are correcting or changing something that you have just said:</div><ul class=\"examples\"><li><em>They all knew I was on their side. At least, that’s what they said.</em></li><li><em>I made everything perfectly clear – or at least I thought I did.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>at the (very) least</strong> used when mentioning the least extreme thing that happens, is needed etc:</div><ul class=\"examples\"><li><em>Computer viruses are at the very least annoying and often actually destructive.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the least</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the smallest amount:</div><ul class=\"examples\"><li><em>Women work in those sectors of the job market which pay the least.</em></li><li><em>Which method causes the least damage to the environment?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to emphasize how small something is, especially when it hardly exists at all:</div><ul class=\"examples\"><li><em>I haven’t the least idea what you are talking about.</em></li><li><em>He used to wake at the least noise.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> used when you are saying what someone should do in a situation, and suggesting that they should really do more:</div><ul class=\"examples\"><li><em>The least you could do is give me her phone number.</em></li><li><em>The least they could have given her is some money towards the rent.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>not the least/not in the least/not the least bit</strong> none at all, or not at all:</div><ul class=\"examples\"><li><em>I tried to convince them, but they weren’t the least interested.</em></li><li><em>I’m not in the least afraid of you anymore.</em></li><li><em>His voice was alert, not the least bit sleepy.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>to say the least</strong> used to show that something is worse or more serious than you are actually saying:</div><ul class=\"examples\"><li><em>His teaching methods were strange, to say the least.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>the least of somebody’s worries/problems/troubles/concerns</strong> something that someone is not worried about because there are other more important problems:</div><ul class=\"examples\"><li><em>What I looked like was the least of my problems.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>it’s the least I can do</strong> <em>spoken</em> used to say that you are very willing to do something or to reply to someone’s thanks:</div><ul class=\"examples\"><li><em>I’ll look after them – it’s the least I can do.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> less than anything or anyone else <em>OPP most</em>:</div><ul class=\"examples\"><li><em>The journey would impose extra expense on those least able to afford it.</em></li><li><em>It is quite amazing what turns up when you are least expecting it.</em></li><li><em>He’s my least favourite member of staff.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>least of all</strong> especially not a particular person or thing:</div><ul class=\"examples\"><li><em>She hardly ever lost her temper – least of all with Anne.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>not least</strong> <em>formal</em> used to emphasize that something is important:</div><ul class=\"examples\"><li><em>My mother was upset about his appearance here, not least because she felt it was invading her privacy.</em></li></ul></div></div>","4000":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> leath‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleðə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> animal skin that has been treated to preserve it, and is used for making shoes, bags etc:</div><ul class=\"examples\"><li><em>The inside of the bag was lined with soft leather.</em></li><li><em>elegant leather boots</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>leathers</strong> <span class=\"gram\">[plural]</span> special leather clothes worn for protection by someone riding a motorcycle</div></div>","4001":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /liːv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle left /left/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[go away]</strong> <span class=\"gram\">[intransitive, transitive]</span> to go away from a place or a person:</div><ul class=\"examples\"><li><em>My baby gets upset when I leave the room.</em></li><li><em>Before leaving the train, make sure you have all your belongings with you.</em></li><li><em>Leave the motorway at Junction 7.</em></li><li><strong><em>leave at</strong>: The plane leaves at 12.30.</em></li><li><strong><em>leave for</strong>: I tried calling him, but he’d already left for work.</em></li><li><strong><em>leave (something/somebody) soon/now/later etc</strong>: If he left immediately, he’d catch the 7.30 train.</em></li><li><strong><em>leave (something/somebody) to do something</strong>: Frances left work early to meet her mother.</em></li><li><strong><em>leave somebody doing something</strong>: Never leave children playing near water unattended.</em></li><li><strong><em>leave somebody to something</strong>: I’ll leave you to it (=go away and let you continue with what you are doing).</em></li><li><em>My youngest boy has not left my side (=has stayed near me) since his daddy was killed.</em></li><li><strong><em>leave somebody in peace</strong> (=go away from someone so that they can think, work etc alone): Just a few more questions, then we’ll leave you in peace.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[stop]</strong> <span class=\"gram\">[intransitive, transitive]</span> if you leave your job, home, school etc, you permanently stop doing that job, living at home etc:</div><ul class=\"examples\"><li><em>Over the past two years, 20 staffers have left.</em></li><li><strong><em>leave home/school/college etc</strong>: How old were you when you left home (=your parents’ home)? / My daughter got a job after she left school. / The lawsuit will be postponed until the president leaves office.</em></li><li><strong><em>leave a job/country/Spain etc</strong>: Many missionaries were forced to leave the country. / It seems that Tony has left the band for good (=permanently).</em></li><li><strong><em>leave (somebody/something) to do something</strong>: Laura left her native England to live in France.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>leave somebody/something alone</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to stop annoying or upsetting someone:</div><ul class=\"examples\"><li><em>Oh, just leave me alone, will you?</em></li><li><em>Leave the boy alone, he can make up his own mind.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to go away from someone so that they are on their own:</div><ul class=\"examples\"><li><em>Six-year-old Gemma had been left alone in the house.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> to stop touching something:</div><ul class=\"examples\"><li><em>Leave that alone. You’ll break it.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">d)</span> (also leave well (enough) alone) to stop being involved in or trying to change a situation:</div><ul class=\"examples\"><li><em>Why can’t they just leave well alone and let us concentrate on teaching?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[let something/somebody stay]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to make or allow something or someone to stay in a place when you go away</div><ul class=\"examples\"><li><strong><em>leave something/somebody in/with/behind etc</strong>: Are you leaving the kids with Grandma on Saturday? / As soon as I’d shut the door, I realized I’d left the keys inside. / Did anybody leave a jacket behind last night?</em></li><li><em>She left her son in the care of a friend.</em></li><li><strong><em>leave somebody to do something</strong>: He left Ruth to find her own way home. / Students were left to their own devices (=left alone and allowed to do whatever they wanted) for long periods.</em></li><li><strong><em>leave somebody for dead</strong>: The girl had been attacked and left for dead.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[not change/move something]</strong> <span class=\"gram\">[transitive]</span> to let something remain in a particular state, position, or condition</div><ul class=\"examples\"><li><strong><em>leave something on/off/out etc</strong>: You’ve left your lights on. / She must have left the phone off the hook.</em></li><li><strong><em>leave something open/empty/untidy etc</strong>: I wish you’d stop leaving the door open.</em></li><li><em>The trial left many questions unanswered.</em></li><li><strong><em>leave a space/gap etc</strong>: Leave the next two lines blank for the tutor’s comments. / Drivers should always leave room for cyclists.</em></li><li><strong><em>leave something doing something</strong>: I’ll just leave the engine running while I go in.</em></li><li><em>Don’t leave tools lying about.</em></li><li><strong><em>leave something to do something</strong>: Leave the pots to soak overnight.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[result of accident/illness/event]</strong> <span class=\"gram\">[transitive]</span> if an event, accident, illness etc leaves you in a particular condition, you are in that condition because of it:</div><ul class=\"examples\"><li><em>An explosion at a chemical plant has left one worker dead and four injured.</em></li><li><strong><em>leave somebody with something</strong>: Although the infection cleared up, he was left with a persistent cough.</em></li><li><strong><em>leave somebody doing something</strong>: The incident left her feeling confused and hurt. / The announcement has left shareholders nursing huge losses.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>be left</strong> (also have something left) if something is left, it remains after everything else has gone, been taken away, or used:</div><ul class=\"examples\"><li><em>I’ve only got a few dollars left.</em></li><li><em>There were a couple of seats left at the back.</em></li><li><em>We don’t have much time left.</em></li><li><em>He pointed to what was left of the house (=used when very little is left).</em></li><li><em>All that was left was a pile of bones.</em></li><li><strong><em>leave over</strong>: After we’ve paid the bills, there’s never much left over. / They ate some bread rolls left over from the night before.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[letter/message/thing]</strong> <span class=\"gram\">[transitive]</span> to deliver a message, note, package etc for someone or put it somewhere so that they will get it later:</div><ul class=\"examples\"><li><em>She left a message on his answerphone.</em></li><li><strong><em>leave somebody something</strong>: Can you leave me some money for the bus?</em></li><li><strong><em>leave something with somebody</strong>: Ian left this note with me.</em></li><li><strong><em>leave something for somebody</strong>: A guy left these flowers for you.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[delay]</strong> <span class=\"gram\">[transitive]</span> to not do something or to do it later than you intended:</div><ul class=\"examples\"><li><em>Leave the dishes. I’ll do them later.</em></li><li><em>So much had been left undone.</em></li><li><strong><em>leave something until the last minute/until last</strong>: If you leave your preparation until the last minute, you’ll reduce your chances of passing. / I left the best bit until last.</em></li><li><em>I want to think about it. Can I leave it for now?</em></li><li><em>I’m afraid you’ve left it too late to change your ticket.</em></li><li><strong><em>leave it at that</strong> (=used to say that you will not do any more of something, because you have done enough): Let’s leave it at that for today.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[let somebody decide/be responsible]</strong> <span class=\"gram\">[transitive]</span> to let someone else decide something or be responsible for something</div><ul class=\"examples\"><li><strong><em>leave something to somebody</strong>: Leave it to me. I’ll make sure it gets posted. / The choice of specialist subject is left entirely to the students.</em></li><li><strong><em>leave it (up) to somebody to do something</strong>: I’ll leave it up to you to decide. / She leaves it to the reader to draw their own conclusions.</em></li><li><strong><em>leave doing something to somebody</strong>: Is it okay if I leave writing the results to you?</em></li><li><strong><em>leave something with somebody</strong>: Leave it with me, I’ll fix it for you.</em></li><li><em>He’s not the sort to leave things to chance (=take no action and just wait to see what happens).</em></li><li><strong><em>leave somebody with no choice/option</strong> (=force someone to take a particular action): You leave me with no choice but to fire you.</em></li><li><strong><em>leave somebody to do something<em>British English</em></strong>: Clive moved to London, leaving Edward to run the Manchester office.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[husband/wife etc]</strong> <span class=\"gram\">[intransitive, transitive]</span> to stop living with or having a relationship with your husband, partner etc:</div><ul class=\"examples\"><li><em>Martha was always threatening to leave, but I never believed her.</em></li><li><strong><em>leave somebody for somebody</strong>: Mr Rushworth left his partner of 10 years for a younger woman.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[when you die]</strong> <span class=\"gram\">[transitive]</span> ► see thesaurus at give</div><div class=\"subsense\"><span class=\"subnum\">a)</span> to arrange for someone to receive your money, property etc after you die <em>SYN bequeath</em>:</div><ul class=\"examples\"><li><em>Aunt Alice died, leaving almost $5 million.</em></li><li><strong><em>leave somebody something</strong>: Hugo left me his mother’s ring. / In his will, he had left all his children a small sum of money.</em></li><li><strong><em>leave something to somebody/something</strong>: Have you thought of leaving a gift to charity after you die?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>leave a wife/children etc</strong> used when someone dies before their wife, children etc:</div><ul class=\"examples\"><li><em>PC Davis leaves a wife and three small children.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[mark]</strong> <span class=\"gram\">[transitive]</span> to make a mark that remains afterwards</div><ul class=\"examples\"><li><strong><em>leave a mark/stain/scar etc</strong>: The wine had left a permanent mark on the tablecloth.</em></li><li><em>He staggered to the door, leaving a trail of blood.</em></li><li><em>Make sure that you don’t leave any footprints.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[not eat/drink]</strong> <span class=\"gram\">[transitive]</span> if you leave food or drink that you have been given, you do not eat or drink it:</div><ul class=\"examples\"><li><em>‘I’m really hungry now.’ ‘That’s because you left half your lunch.’</em></li><li><em>He rose from the table, leaving his brandy untouched.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>leave somebody/something standing</strong> (also leave somebody/something in the dust<em>American English</em>) <em>informal</em> to be much better, quicker, more successful etc than someone or something else:</div><ul class=\"examples\"><li><em>In terms of fitness, he discovered that Kate left him standing.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>leave a lot/something/much to be desired</strong> to be very unsatisfactory:</div><ul class=\"examples\"><li><em>Inspectors say health and safety procedures at the factory leave a lot to be desired.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>[mathematics]</strong> <span class=\"gram\">[transitive]</span> in a sum, to have a particular amount remaining:</div><ul class=\"examples\"><li><em>Three from seven leaves four.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>leave something aside/to one side</strong> to not think about or consider one part of something for a time, so that you can consider another part of it:</div><ul class=\"examples\"><li><em>Leaving aside for a moment the question of expense, what would your view be of the suggested changes?</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>leave somebody/something be</strong> <em>old-fashioned</em> to not upset, speak to, or annoy someone or to not touch something</div><div class=\"sense\"><span class=\"snum\">20</span> <strong>leave go/hold of something</strong> <em>British English</em> <em>spoken</em> <em>informal</em> to stop holding something</div><div class=\"sense\"><span class=\"snum\">21</span> <strong>leave it to somebody (to do something)</strong> <em>American English</em> <em>spoken</em> <em>informal</em> used to say that no one should be surprised that someone does something, because it is typical or expected of them:</div><ul class=\"examples\"><li><em>Leave it to you to have the whole day planned out!</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>Elvis/somebody/something has left the building</strong> <em>especially American English</em> <em>informal</em> used humorously to emphasize that something is definitely over or that someone has gone and will not return</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[holiday]</strong> <span class=\"gram\">[uncountable]</span> time that you are allowed to spend away from your work, especially in the armed forces:</div><ul class=\"examples\"><li><em>I’ve applied for three days’ leave.</em></li><li><strong><em>on leave</strong>: navy officers home on leave</em></li><li><em>Your basic annual leave is 20 days.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>maternity/sick/compassionate leave</strong> time that you are allowed to spend away from work because you have had a baby, because you are ill, or because of a personal problem such as the death of a relative</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>leave of absence</strong> a period of time that you are allowed to spend away from work for a particular purpose:</div><ul class=\"examples\"><li><em>She’s been given leave of absence to attend a computer course.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[permission]</strong> <span class=\"gram\">[uncountable]</span> <em>formal</em> permission to do something:</div><ul class=\"examples\"><li><em>All this was done entirely without my leave.</em></li><li><strong><em>leave to do something</strong>: a petition for leave to appeal to the European court</em></li><li><strong><em>grant/obtain/ask/seek etc leave (to do something)</strong>: He asked leave to speak to her in private.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>without so much as a by your leave</strong> <em>old-fashioned</em> without asking permission, in a way that seems very rude:</div><ul class=\"examples\"><li><em>He marched into my office without so much as a by your leave.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>take leave of your senses</strong> to suddenly start behaving in a strange way:</div><ul class=\"examples\"><li><em>You want to marry him? Have you taken leave of your senses?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>take leave of somebody/take your leave</strong> <em>formal</em> to say goodbye to someone</div></div></div>","4002":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lec‧ture</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlektʃə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a long talk on a particular subject that someone gives to a group of people, especially to students in a university → speech ► see thesaurus at speech</div><ul class=\"examples\"><li><strong><em>lecture on</strong>: He regularly gives lectures on modern French literature.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an act of criticizing someone or warning them about something in a long serious talk, in a way that they think is unfair or unnecessary</div><ul class=\"examples\"><li><strong><em>lecture on/about</strong>: My father caught me and gave me a long lecture about the dangers of drink.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to talk angrily or seriously to someone in order to criticize or warn them, in a way that they think is unfair or unnecessary:</div><ul class=\"examples\"><li><em>I wish you’d stop lecturing me!</em></li><li><strong><em>lecture somebody about/on something</strong>: He began to lecture us about making too much noise.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> to talk to a group of people on a particular subject, especially to students in a university ► see thesaurus at teach</div><ul class=\"examples\"><li><strong><em>lecture on</strong>: He lectures on European art at Manchester University.</em></li></ul></div></div>","4003":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lec‧tur‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlektʃərə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">► see thesaurus at teacher</div><div class=\"subsense\"><span class=\"subnum\">a)</span> someone who gives lectures, especially in a university:</div><ul class=\"examples\"><li><em>She’s a brilliant lecturer.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a teacher in a British university or college</div><ul class=\"examples\"><li><strong><em>lecturer in</strong>: a lecturer in medieval studies at Edinburgh University</em></li></ul></div>","4004":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ledʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a narrow flat piece of rock that sticks out on the side of a mountain or cliff:</div><ul class=\"examples\"><li><em>We crept carefully along the narrow ledge.</em></li><li><em>He leapt onto a ledge of rock.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a narrow shelf:</div><ul class=\"examples\"><li><em>There’s some money on the window ledge (=narrow shelf below the window).</em></li></ul></div>","4005":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /left/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> your left side is the side of your body that contains your heart <em>OPP right</em>:</div><ul class=\"examples\"><li><em>She held out her left hand.</em></li><li><em>a scar on the left side of his face</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> on the same side of something as your left side <em>OPP right</em>:</div><ul class=\"examples\"><li><em>Take the next left turn.</em></li><li><em>the left bank of the river</em></li><li><em>a pile of papers on the left side of the desk</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>have two left feet</strong> <em>informal</em> to move in an awkward way when you are running or doing a sport:</div><ul class=\"examples\"><li><em>a tall, clumsy-looking boy with two left feet</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the left hand doesn’t know what the right hand is doing</strong> used to say that one part of a group or organization does not know what the other parts are doing</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\">towards the direction or side that is on the left <em>OPP right</em>:</div><ul class=\"examples\"><li><em>Turn left just after the school.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the left/somebody’s left</strong> the side of your body that contains your heart <em>OPP right</em></div><ul class=\"examples\"><li><strong><em>on/to the left (of something)</strong>: Take the next road on the left. / Our house is just to the left of the school.</em></li><li><strong><em>on/to somebody’s left</strong>: On your left you can see the Houses of Parliament.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>(from) left to right</strong> from the left side to the right side of something:</div><ul class=\"examples\"><li><em>The photo shows, from left to right, his daughters Molly, Fiona, and Anne.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the left/the Left</strong> political parties and groups that support the ideas and beliefs of socialism. They usually want large industries to be owned by the state, and to use taxes to help solve social problems <em>OPP right</em>:</div><ul class=\"examples\"><li><em>He has support from the Left.</em></li><li><em>politicians on the left of the party</em></li><li><em>The party is moving further to the left.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a hit made with your left hand <em>OPP right</em></div><div class=\"sense\"><span class=\"snum\">5</span> <strong>take a left</strong> (also hang a left<em>American English</em>) to turn left:</div><ul class=\"examples\"><li><em>Take the next left (=turn left at the next road).</em></li></ul></div></div>","4006":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌleft-ˈhand</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">on the left side of something <em>OPP right-hand</em>:</div><ul class=\"examples\"><li><em>We live about halfway down the street on the left-hand side.</em></li></ul></div>","4007":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌleft-ˈhanded</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a left-handed person uses their left hand for writing, throwing etc <em>OPP right-handed</em></div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> left-handed tools have been made for left-handed people to use:</div><ul class=\"examples\"><li><em>left-handed scissors</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>left-handed compliment</strong> <em>American English</em> a statement that seems to express admiration or praise, but at the same time is insulting SYN backhanded compliment<em>British English</em></div></div>","4008":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌleft-ˈwing</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">a left-wing person or group supports the political aims of groups such as Socialists and Communists <em>OPP right-wing</em>:</div><ul class=\"examples\"><li><em>a left-wing newspaper</em></li><li><em>a left-wing political organization</em></li><li><em>She’s got very left-wing views.</em></li></ul></div>","4009":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /leɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[body part]</strong> <span class=\"gram\">[countable]</span> one of the long parts of your body that your feet are joined to, or a similar part on an animal or insect:</div><ul class=\"examples\"><li><em>a young boy with skinny legs</em></li><li><em>She fell and broke her leg.</em></li><li><strong><em>four-legged/long-legged etc</strong>: four-legged animals</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[meat]</strong> <span class=\"gram\">[countable, uncountable]</span> the leg of an animal when it is cooked and eaten as food:</div><ul class=\"examples\"><li><em>roast leg of lamb</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[furniture]</strong> <span class=\"gram\">[countable]</span> one of the upright parts that support a piece of furniture:</div><ul class=\"examples\"><li><em>One of the legs on the table was a bit wobbly.</em></li><li><em>a chair leg</em></li><li><em>a three-legged stool</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[clothing]</strong> <span class=\"gram\">[countable]</span> the part of your trousers that covers your leg:</div><ul class=\"examples\"><li><em>The legs of my jeans were covered in mud.</em></li><li><em>He rolled up his trouser legs and waded out into the stream.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[journey/race]</strong> <span class=\"gram\">[countable]</span> one part of a long journey or race</div><ul class=\"examples\"><li><strong><em>leg of</strong>: the final leg of the Tour de France</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[sport]</strong> <span class=\"gram\">[countable]</span> <em>British English</em> one of the series of games in a football competition played between two teams:</div><ul class=\"examples\"><li><em>Leeds will have to win the second leg if they are to go forward to the finals.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>not have a leg to stand on</strong> <em>informal</em> to be in a situation where you cannot prove or legally support what you say:</div><ul class=\"examples\"><li><em>If you didn’t sign a contract, you won’t have a leg to stand on.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>get your leg over</strong> <em>British English</em> <em>informal</em> <em>not polite</em> to have sex with someone</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>have legs</strong> <em>American English</em> <em>informal</em> if a piece of news has legs, people continue to be interested in it and talk about it</div></div>","4010":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> leg‧a‧cy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleɡəsi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural legacies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that happens or exists as a result of things that happened at an earlier time</div><ul class=\"examples\"><li><strong><em>legacy of</strong>: The invasion left a legacy of hatred and fear.</em></li><li><strong><em>legacy from</strong>: a legacy from the colonial period</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> money or property that you receive from someone after they die <em>SYN inheritance</em>:</div><ul class=\"examples\"><li><em>She received a small legacy from her aunt.</em></li></ul></div>","4011":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> le‧gal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈliːɡəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if something is legal, you are allowed to do it or have to do it by law <em>OPP illegal</em>:</div><ul class=\"examples\"><li><em>What the company has done is perfectly legal.</em></li><li><em>plans to make the carrying of identity cards a legal requirement</em></li><li><em>He had twice the legal limit of alcohol in his bloodstream.</em></li><li><em>a pressure group that is campaigning to make cannabis legal</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> concerned with or relating to the law:</div><ul class=\"examples\"><li><em>free legal advice</em></li><li><em>a costly legal dispute</em></li><li><em>the Scottish legal system</em></li><li><strong><em>the legal profession</strong> (=lawyers)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>legal action/proceedings</strong> the use of the legal system to settle an argument, put right an unfair situation etc:</div><ul class=\"examples\"><li><em>She threatened to take legal action against the hospital.</em></li></ul></div>","4012":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> le‧gal‧ize</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈliːɡəlaɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make something legal so that people are allowed to do it <em>OPP criminalize</em>:</div><ul class=\"examples\"><li><em>Abortion was legalized in the 1960s.</em></li></ul></div>","4013":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> le‧gal‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈliːɡəli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> according to the law:</div><ul class=\"examples\"><li><em>They are still legally married.</em></li><li><em>Which of them is legally responsible for the accident?</em></li><li><em>a legally binding agreement</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if you can do something legally, you are allowed to do it by law <em>OPP illegally</em>:</div><ul class=\"examples\"><li><em>The station can now broadcast legally.</em></li></ul></div>","4014":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> le‧gend</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈledʒənd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> an old well-known story, often about brave people, adventures, or magical events → myth: ► see thesaurus at story</div><ul class=\"examples\"><li><em>a book of ancient Greek legends</em></li><li><strong><em>legend of</strong>: the legend of St George and the dragon</em></li><li><strong><em>according to legend</strong>: According to legend, he escaped by leaping from the cliffs into the sea.</em></li><li><em>Local legend has it that (=says that) the island was the original Garden of Eden.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> someone who is famous and admired for being extremely good at doing something ► see thesaurus at star → living legend at living1(6)</div><ul class=\"examples\"><li><strong><em>tennis/footballing/music etc legend</strong>: We must put more money into the sport if we want to create the tennis legends of the future.</em></li><li><em>a marvellous player who was a legend in his own lifetime</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be a legend</strong> <em>British English</em> <em>informal</em> to be a person that you admire a lot – used especially by young people:</div><ul class=\"examples\"><li><em>My stepfather is an absolute legend.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> <em>literary</em> words that have been written somewhere, for example on a sign:</div><ul class=\"examples\"><li><em>A sign above the door bore the legend ‘Patience is a Virtue’.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> <em>technical</em> the words that explain a picture or map → key</div></div>","4015":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> le‧gen‧da‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈledʒəndəri $ -deri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very famous and admired: ► see thesaurus at famous</div><ul class=\"examples\"><li><em>Lonnie Johnson, the legendary blues guitarist</em></li><li><em>Her singing was legendary.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> talked about in a legend → mythical:</div><ul class=\"examples\"><li><em>The cave is the home of a legendary giant.</em></li></ul></div>","4016":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> le‧gis‧la‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌledʒəˈsleɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a law or set of laws:</div><ul class=\"examples\"><li><em>It is a very important piece of legislation.</em></li><li><strong><em>legislation on</strong>: the legislation on abortion</em></li><li><strong><em>legislation to do something</strong>: new legislation to protect children</em></li><li><strong><em>introduce/bring in legislation</strong>: The government is bringing in legislation to combat this problem.</em></li><li><strong><em>under new/existing/current etc legislation</strong>: The company can be prosecuted under the new legislation.</em></li></ul></div>","4017":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> le‧gis‧la‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈledʒəslətɪv $ -leɪtɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">concerned with making laws:</div><ul class=\"examples\"><li><em>The new assemblies will have no legislative power.</em></li><li><strong><em>legislative assembly/council/body etc</strong> (=one with the power to make laws): the main legislative body of the EU</em></li><li><em>new legislative measures to stem the flow of drugs into the US</em></li><li><em>legislative elections</em></li></ul></div>","4018":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> le‧gis‧la‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈledʒəsleɪtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who has the power to make laws or belongs to an institution that makes laws</div></div>","4019":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> le‧gis‧la‧ture</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈledʒəsleɪtʃə, -lətʃə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an institution that has the power to make or change laws</div><ul class=\"examples\"><li><strong><em>state/national/federal etc legislature</strong>: the state legislature of Virginia</em></li></ul></div>","4020":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> le‧git‧i‧mate</span><span class=\"meta-item\"><strong>IPA:</strong> /ləˈdʒɪtəmət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> fair or reasonable:</div><ul class=\"examples\"><li><em>That’s a perfectly legitimate question.</em></li><li><em>Most scientists believe it is legitimate to use animals in medical research.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> acceptable or allowed by law:</div><ul class=\"examples\"><li><em>Their business operations are perfectly legitimate.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a legitimate child is born to parents who are legally married to each other <em>OPP illegitimate</em></div></div>","4021":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lei‧sure</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleʒə $ ˈliːʒər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> time when you are not working or studying and can relax and do things you enjoy: ► see thesaurus at fun</div><ul class=\"examples\"><li><em>Most people now enjoy shorter working hours and more leisure time.</em></li><li><em>Watching television is now the nation’s most popular leisure activity.</em></li><li><em>The hotel offers various leisure facilities such as a swimming pool and sauna.</em></li><li><em>The leisure industry (=the business of providing leisure activities) is now an important part of the economy.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>at (your) leisure</strong> if you do something at your leisure, you do it slowly and without hurrying:</div><ul class=\"examples\"><li><em>Come round for lunch and then we can discuss it at leisure.</em></li><li><em>Take the leaflets home and read them at your leisure.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>gentleman/lady of leisure</strong> someone who does not have to work – used humorously</div></div>","4022":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈleisure ˌcentre</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>British English</em> a place where people can do many different sports activities, exercise classes etc</div></div>","4023":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lem‧on</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlemən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a fruit with a hard yellow skin and sour juice:</div><ul class=\"examples\"><li><em>a slice of lemon</em></li><li><em>Add a few drops of lemon juice.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>British English</em> a drink that tastes of lemons:</div><ul class=\"examples\"><li><em>a glass of fizzy lemon</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> (also lemon yellow) a pale yellow colour</div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> <em>especially American English</em> <em>informal</em> something that is useless because it fails to work or to work properly:</div><ul class=\"examples\"><li><em>I soon realized the van was a lemon.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> <em>British English</em> <em>informal</em> a silly person:</div><ul class=\"examples\"><li><em>He just stood there looking like a real lemon.</em></li></ul></div>","4024":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lem‧on‧ade</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌleməˈneɪd◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>British English</em> a sweet fizzy drink that tastes of lemons:</div><ul class=\"examples\"><li><em>a glass of lemonade</em></li><li><em>Would you like a lemonade?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a drink made from lemons, sugar, and water</div></div>","4025":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\">(past tense and past participle lent /lent/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[transitive]</span> to let someone borrow money or something that belongs to you for a short time → borrow</div><ul class=\"examples\"><li><strong><em>lend something to somebody</strong>: I lent my CD player to Dave and I haven’t got it back yet.</em></li><li><strong><em>lend somebody something</strong>: The hospital agreed to lend us a wheelchair. / Can you lend me £10 until tomorrow?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[intransitive, transitive]</span> if a bank or financial institution lends money, it lets someone have it on condition that they pay it back later, often gradually, with an additional amount as interest:</div><ul class=\"examples\"><li><em>The government is trying to encourage the banks to lend more.</em></li><li><strong><em>lend something to somebody</strong>: A lot of banks are unwilling to lend money to new businesses.</em></li><li><strong><em>lend somebody something</strong>: The building society agreed to lend us £60,000.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>lend (somebody) a hand</strong> to help someone do something, especially something that needs physical effort:</div><ul class=\"examples\"><li><em>Can you lend me a hand with this?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> <em>formal</em> to give a situation, event etc a particular quality</div><ul class=\"examples\"><li><strong><em>lend something to something</strong>: The presence of members of the royal family lent a certain dignity to the ceremony.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>lend an ear</strong> to listen to someone, especially in a sympathetic way:</div><ul class=\"examples\"><li><em>He’s always prepared to lend a sympathetic ear.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>lend itself to something</strong> to be suitable for being used in a particular way:</div><ul class=\"examples\"><li><em>None of her books really lends itself to being made into a film.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>lend (your) support (to something)</strong> to support or help someone:</div><ul class=\"examples\"><li><em>The government has now lent its support to the campaign.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>lend weight/support to something</strong> to make an opinion or belief seem more likely to be correct:</div><ul class=\"examples\"><li><em>The police have new evidence which lends weight to their theory.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>lend your name to something</strong> to announce publicly that you support something that someone is trying to do:</div><ul class=\"examples\"><li><em>The French prime minister has now lent his name to the protest.</em></li></ul></div>","4026":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˈlendə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a person or organization that lends money to people on condition that they pay it back:</div><ul class=\"examples\"><li><em>Several lenders are offering very attractive rates of interest at the moment.</em></li></ul></div>","4027":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /leŋθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[size]</strong> <span class=\"gram\">[countable, uncountable]</span> the measurement of how long something is from one end to the other → breadth, width:</div><ul class=\"examples\"><li><em>We measured the length and width of the living room.</em></li><li><strong><em>a length of 1 metre/2 feet etc</strong>: Some fish can grow to a length of four feet.</em></li><li><strong><em>2 feet/10 metres etc in length</strong>: The hotel pool is 15 metres in length. / You’ll need several pieces of string of different lengths.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[time]</strong> <span class=\"gram\">[countable, uncountable]</span> the amount of time that you spend doing something or that something continues → duration RegisterIn everyday English, people usually talk about how long something is in space or time, rather than using the noun length: We need to know the length of the table. ➔ We need to know how long the table is. | He was annoyed by the length of time he had to wait. ➔ He was annoyed by how long he had to wait.</div><ul class=\"examples\"><li><strong><em>length of</strong>: Your pension will depend on your length of employment. / What’s the average length of stay in hospital?</em></li><li><strong><em>(not) for any length of time</strong> (=not for very long): He wasn’t left alone for any length of time.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[books/films etc]</strong> <span class=\"gram\">[countable, uncountable]</span> the amount of writing in a book, or the amount of time that a film, play etc continues</div><ul class=\"examples\"><li><strong><em>length of</strong>: We had to cut the length of the book by one third.</em></li><li><strong><em>of this length</strong>: Films of this length (=as long as this) are pretty unusual.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>run/stretch/walk etc the (full) length of something</strong> to go or move from one end to the other of something:</div><ul class=\"examples\"><li><em>The wall ran the full length of the garden.</em></li><li><em>They walked the length of the pier.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>shoulder-length/knee-length etc</strong> reaching down as far as your shoulders etc:</div><ul class=\"examples\"><li><em>shoulder-length hair</em></li><li><em>an ankle-length dress</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>go to some/great/any lengths (to do something)</strong> to try very hard or to do whatever is necessary to achieve something that is important to you:</div><ul class=\"examples\"><li><em>He went to great lengths to keep their name out of the papers.</em></li><li><em>Bella would go to any lengths to fulfil her ambition.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>at (some/great etc) length</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if you talk at length about something, you talk about it for a long time</div><ul class=\"examples\"><li><strong><em>speak/talk etc at length</strong>: The young people spoke at length about their experiences.</em></li><li><em>We’ve already discussed the subject at great length.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>literary</em> after a long time:</div><ul class=\"examples\"><li><em>‘I don’t agree,’ she said at length.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>the length and breadth of the area/country/land etc</strong> in or through every part of a large area:</div><ul class=\"examples\"><li><em>The police searched the length and breadth of the country.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[piece]</strong> <span class=\"gram\">[countable]</span> a piece of something long and thin</div><ul class=\"examples\"><li><strong><em>a length of rope/pipe/wire etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[in races]</strong> <span class=\"gram\">[countable]</span> the measurement of a horse, boat etc from one end to the other – used when saying how far the horse, boat etc is ahead of another:</div><ul class=\"examples\"><li><em>The horse won by three lengths.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[swimming]</strong> <span class=\"gram\">[countable]</span> the distance from one end of a swimming pool to the other</div><ul class=\"examples\"><li><strong><em>do/swim a length</strong>: She does at least 20 lengths a day.</em></li></ul></div>","4028":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> length‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈleŋθi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[usually before noun]</span></span><span class=\"meta-item\">(comparative lengthier, superlative lengthiest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> continuing for a long time, often too long <em>OPP brief</em>: ► see thesaurus at long</div><ul class=\"examples\"><li><em>A lengthy period of training is required.</em></li><li><em>An accident is causing some lengthy delays.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a speech, piece of writing etc that is lengthy is long and often contains too many details:</div><ul class=\"examples\"><li><em>a lengthy report</em></li></ul></div>","4029":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lenz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the part of a camera through which light travels onto the surface where the image is recorded: → telephoto lens, wide-angle lens, zoom lens</div><ul class=\"examples\"><li><em>a standard 50 mm lens</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a piece of curved glass or plastic which makes things look bigger, smaller, or clearer when you look through it:</div><ul class=\"examples\"><li><em>glasses with powerful lenses</em></li><li><em>the lens of the microscope</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the clear part inside your eye that focuses so you can see things clearly</div><div class=\"sense\"><span class=\"snum\">4</span> a contact lens</div></div>","4030":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /les/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not so much or to a smaller degree <em>OPP more</em>:</div><ul class=\"examples\"><li><em>Maybe he would worry less if he understood the situation.</em></li><li><em>In recent years she has appeared in public less frequently.</em></li><li><strong><em>less (...) than</strong>: Tickets were less expensive than I had expected.</em></li><li><strong><em>much/a lot/far less</strong>: Social class matters a lot less than it used to.</em></li><li><strong><em>not... any the less/no less</strong> (=not less): Your second point is no less important. / It’s a common problem but this doesn’t make it any the less disturbing. / I know he’s done a dreadful thing, but I don’t love him any the less.</em></li><li><strong><em>be less a... than a...</strong> (=be not so much like one thing as another): ‘Will you please come with me?’ It was less a request than a command.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>less than helpful/honest/enthusiastic etc</strong> not at all helpful, honest etc:</div><ul class=\"examples\"><li><em>He was less than enthusiastic about the idea.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>less and less</strong> used to say that a quality, situation etc gradually decreases <em>OPP more and more</em>:</div><ul class=\"examples\"><li><em>As the years went by, he seemed to care less and less about his reputation.</em></li><li><em>Smoking is becoming less and less acceptable.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>much/still less</strong> used to say that a greater thing is even less true, likely, or possible than the thing you have just mentioned:</div><ul class=\"examples\"><li><em>These people can scarcely afford to buy food, still less luxury goods like perfume.</em></li><li><em>I didn’t think Dave would ever read a book, much less write one himself.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">determiner</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a smaller amount or not as much <em>OPP more</em>: USAGE: Less, fewer• You use less before an uncountable noun: · These light bulbs use less electricity.• You use fewer before a plural noun: · There were fewer cars in those days. ✗Don&#x27;t say: There were less cars in those days. Although you will hear people say this in everyday spoken English, it is considered to be incorrect.</div><ul class=\"examples\"><li><em>Doctors recommend eating less salt.</em></li><li><em>People today seem to have less time for each other.</em></li><li><em>Most of us got £4 an hour, but some received even less.</em></li><li><strong><em>less of</strong>: The map covered less of the area than I’d thought. / Flying is less of a risk than driving.</em></li><li><strong><em>less (...) than</strong>: She knows less than I do about it.</em></li><li><strong><em>less than 10/100 etc</strong>: a distance of less than 100 metres</em></li><li><strong><em>much/a lot less</strong>: It costs much less to go by bus.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>no less</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to emphasize that an amount or number is large</div><ul class=\"examples\"><li><strong><em>no less than</strong>: By 1977, the USA was importing no less than 45% of its oil.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to emphasize that the person or thing you are talking about is important or impressive:</div><ul class=\"examples\"><li><em>Our awards were presented by the mayor, no less.</em></li><li><em>The message came from no less a person than the prime minister.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>nothing less than something</strong> used to emphasize how important, serious, or impressive something is:</div><ul class=\"examples\"><li><em>His appearance in the show was nothing less than a sensation.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>less and less</strong> a decreasing amount of something <em>OPP more and more</em>:</div><ul class=\"examples\"><li><em>They began spending less and less time together.</em></li><li><strong><em>less of</strong>: The band was doing less and less of that kind of music.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>in less than no time</strong> very quickly or very soon:</div><ul class=\"examples\"><li><em>In less than no time they found that they owed over $10,000.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>less of something</strong> <em>British English</em> <em>spoken</em> used to tell a child to stop doing something:</div><ul class=\"examples\"><li><em>Less of that noise, please!</em></li></ul></div></div>","4031":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> less‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlesən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to become smaller in size, importance, or value, or make something do this <em>SYN reduce</em></div><ul class=\"examples\"><li><strong><em>lessen the risk/chance/possibility etc (of something)</strong>: Exercise lessens the risk of heart disease.</em></li><li><strong><em>lessen the impact/effect/importance (of something)</strong>: The new project will lessen the effects of car pollution.</em></li><li><em>Gradually her anxiety lessened.</em></li></ul></div>","4032":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> less‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlesə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>formal</em> not as large, as important, or as much as something else <em>OPP greater</em>: → lesser mortals at mortal2, → to a greater or lesser extent at extent(1)</div><ul class=\"examples\"><li><em>They originally asked for $5 million, but finally settled for a lesser sum.</em></li><li><strong><em>to a lesser extent/degree</strong>: This was true in Madrid and, to a lesser extent, Valencia and Seville.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the lesser of two evils</strong> (also the lesser evil) the less unpleasant or harmful of two unpleasant choices</div><div class=\"sense\"><span class=\"snum\">3</span> <em>technical</em> used in the names of some types of animal, bird, or plant that are slightly smaller than the main type</div></div>","4033":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> les‧son</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlesən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[learning a skill]</strong> a period of time in which someone is taught a particular skill, for example how to play a musical instrument or drive a car:</div><ul class=\"examples\"><li><em>piano lessons</em></li><li><strong><em>have/take lessons</strong>: She’s started taking driving lessons.</em></li><li><strong><em>lesson in/on</strong>: lessons in First Aid / lessons in road safety</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[in school]</strong> <em>British English</em> a period of time in which school students are taught a particular subject SYN class<em>American English</em>:</div><ul class=\"examples\"><li><em>Lessons start at 9 o&#x27;clock.</em></li><li><strong><em>French/physics/art etc lesson</strong>: I’ve got a double maths lesson next.</em></li><li><strong><em>lesson in/on</strong>: Andrew gives private lessons in Spanish.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[experience]</strong> something that provides experience or information that you can learn from and use</div><ul class=\"examples\"><li><strong><em>learn a lesson</strong> (=gain useful experience or information): There were important lessons to be learned from these discoveries. / The government has failed to learn the lessons of history.</em></li><li><strong><em>lesson to</strong>: The men’s courage and faith is a lesson to us all.</em></li><li><em>Now let that be a lesson to you all (=be careful to avoid having the same bad experience again).</em></li><li><em>Her fate should be a salutary lesson (=one that teaches or warns you about something).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[book]</strong> a part of a book that is used for learning a particular subject, especially in school:</div><ul class=\"examples\"><li><em>Turn to lesson 25.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[church]</strong> a short piece that is read from the Bible during a religious ceremony</div></div>","4034":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lest/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in order to make sure that something will not happen:</div><ul class=\"examples\"><li><em>She turned away from the window lest anyone see them.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to show that someone is afraid or worried that a particular thing might happen</div><ul class=\"examples\"><li><strong><em>worried/concerned/anxious etc lest...</strong>: He paused, afraid lest he say too much. / She worried lest he should tell someone what had happened.</em></li></ul></div>","4035":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /let/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle let, present participle letting)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[allow]</strong> <span class=\"gram\">[transitive not in passive]</span> to allow someone to do something → allow, permit: ► see thesaurus at allow RegisterIn written English, people often prefer to use allow somebody to do something rather than let somebody do something, as it is slightly more formal:· We must allow young people to develop independence.</div><ul class=\"examples\"><li><em>I can’t come out tonight – my dad won’t let me.</em></li><li><strong><em>let somebody do something</strong>: Let Johnny have a go on the computer now. / Some people seem to let their kids do whatever they like. / Let me have a look at that letter.</em></li><li><strong><em>let somebody have something</strong> (=give something to someone): I can let you have another £10, but no more.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[not stop something happening]</strong> <span class=\"gram\">[transitive]</span> to not stop something happening, or to make it possible for it to happen</div><ul class=\"examples\"><li><strong><em>let somebody/something do something</strong>: Jenny let the note fall to the ground. / Don’t let anyone know it was me who told you. / Max let the door swing open. / Let the cookies cool down before you try them.</em></li><li><strong><em>let yourself be beaten/persuaded/fooled etc</strong>: I stupidly let myself be persuaded to take part in a live debate.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>let go</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to stop holding something or someone:</div><ul class=\"examples\"><li><em>Let go! You’re hurting me.</em></li><li><strong><em>let of</strong>: The guard let go of the lead, and the dog lunged forward.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to accept that you cannot change something and stop thinking or worrying about it:</div><ul class=\"examples\"><li><em>Sometimes you just have to learn to let go.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>let somebody go</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to allow someone to leave a place where they have been kept <em>SYN release</em>:</div><ul class=\"examples\"><li><em>The police had to let him go through lack of evidence.</em></li><li><em>The hijackers were persuaded to let some hostages go.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to make someone leave their job – used in order to avoid saying this directly:</div><ul class=\"examples\"><li><em>I’m afraid we had to let several of our staff go.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>let yourself go</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to relax completely and enjoy yourself:</div><ul class=\"examples\"><li><em>For goodness sake, Peter, why don’t you just let yourself go for once?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to stop looking after yourself properly, for example by not caring about your appearance:</div><ul class=\"examples\"><li><em>Poor Dad. He’s really let himself go since Mum died.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>let something go</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to not punish or criticize someone for something they have done wrong:</div><ul class=\"examples\"><li><em>OK, I’ll let it go this time.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to stop worrying or thinking too much about something:</div><ul class=\"examples\"><li><em>It’s time to let the past go.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <em>informal</em> to sell something for a particular amount</div><ul class=\"examples\"><li><strong><em>let something go for £20/$200 etc</strong>: I couldn’t let it go for less than £300.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[wish]</strong> <span class=\"gram\">[transitive not in passive]</span> used to say that you wish or hope that something happens, or does not happen</div><ul class=\"examples\"><li><strong><em>(not) let somebody/something do something</strong>: Don’t let him be the one who died, she prayed.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>let alone</strong> used after a negative statement to say that the next thing you mention is even more unlikely:</div><ul class=\"examples\"><li><em>The baby can’t even sit up yet, let alone walk!</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>let something drop/rest/lie</strong> to stop talking about or trying to deal with something:</div><ul class=\"examples\"><li><em>It seems the press are not going to let the matter rest.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>let slip</strong> to accidentally tell someone something that should have been kept secret</div><ul class=\"examples\"><li><strong><em>let that</strong>: Liz let slip that she’d seen him quite recently.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>[rent]</strong> <span class=\"gram\">[transitive]</span> <em>especially British English</em> to charge someone an amount of money for the use of a room or building <em>SYN lease</em> → hire, rent:</div><ul class=\"examples\"><li><em>Interhome has over 20,000 houses to let across Europe.</em></li><li><strong><em>let something to somebody</strong>: I’ve let my spare room to a student.</em></li><li><strong><em>let somebody something</strong>: Would you consider letting me the garage for a few months?</em></li><li><strong><em>let something out to somebody</strong>: We let the smaller studios out to local artists.</em></li><li><strong><em>To Let<em>written</em></strong> (=written on a sign outside a building to show that it is available for renting)</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>[mathematics]</strong> <strong>let something be/equal/represent something</strong> <em>technical</em> used in mathematics to mean that you give something a particular measurement or value in order to make a calculation:</div><ul class=\"examples\"><li><em>Let angle A equal the sum of the two opposite sides.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>let yourself in for something</strong> <em>informal</em> to do something that will cause you a lot of trouble:</div><ul class=\"examples\"><li><em>I don’t think Carol realizes what she’s letting herself in for.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>never let a day/week/year etc go by without doing something</strong> used to say that someone does a particular thing very regularly:</div><ul class=\"examples\"><li><em>They never seem to let a year go by without introducing a new version of their software.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>let the good times roll</strong> <em>informal</em> used to say that it is time for people to start having fun</div><div class=\"sense\"><span class=\"snum\">22</span> <strong>let somebody have it</strong> <em>informal</em> to attack someone</div></div>","4036":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> let’s</span><span class=\"meta-item\"><strong>IPA:</strong> /lets/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span></div><div class=\"entry-body\"><div class=\"sense\">the short form of ‘let us’, used especially to make suggestions:</div><ul class=\"examples\"><li><em>Let’s go!</em></li></ul></div>","4037":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> let‧down</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈletdaʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[singular]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>informal</em> an event, performance etc that is not as good as you expected it to be <em>SYN disappointment</em>:</div><ul class=\"examples\"><li><em>The end of the book was a real letdown.</em></li></ul></div>","4038":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> le‧thal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈliːθəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> causing death, or able to cause death → fatal:</div><ul class=\"examples\"><li><em>a lethal dose of heroin</em></li><li><em>a lethal weapon</em></li><li><em>death by lethal injection</em></li><li><em>a lethal cocktail of drink and pills</em></li><li><strong><em>lethal to</strong>: These chemicals are lethal to fish.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> likely to be powerful or dangerous – often used humorously:</div><ul class=\"examples\"><li><em>They were all drinking lethal amounts of tequila!</em></li><li><em>Higher taxes and higher inflation were a lethal combination.</em></li></ul></div>","4039":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> let‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈletə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a written or printed message that is usually put in an envelope and sent by mail → chain letter, letter of credit, open letter</div><ul class=\"examples\"><li><strong><em>letter from/to</strong>: I got a letter from Melanie today. / Bart’s writing a letter to his parents.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a sign in writing or printing that represents a speech sound: → block letters</div><ul class=\"examples\"><li><em>There are 26 letters in the English alphabet.</em></li><li><em>Fill in the form in capital letters (=written in their large form).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>to the letter</strong> paying exact attention to the details of something:</div><ul class=\"examples\"><li><em>I followed the instructions to the letter, but it still wouldn’t work.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the letter of the law</strong> the exact words of a law or agreement rather than the intended or general meaning: → the spirit of the law at spirit1(11)</div><ul class=\"examples\"><li><em>employees who stick to the letter of the law in their contracts</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>American English</em> a large cloth letter that you sew onto a jacket, given as a reward for playing in a school or college sports team:</div><ul class=\"examples\"><li><em>Mark got a letter in soccer.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>English/American/German etc letters</strong> <span class=\"gram\">[plural]</span> <em>formal</em> the study of the literature of a particular country or language:</div><ul class=\"examples\"><li><em>a major figure in English letters</em></li></ul></div>","4040":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> let‧tuce</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈletɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a round vegetable with thin green leaves eaten raw in salads</div></div>","4041":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lev‧el</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlevəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[amount]</strong> the amount or degree of something, compared to another amount or degree: ► see thesaurus at amount</div><ul class=\"examples\"><li><em>Inflation fell to its lowest level in 30 years.</em></li><li><strong><em>level of</strong>: Increased supplies are needed to meet the level of demand. / Dolphins show a high level of intelligence.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[standard]</strong> a particular standard of skill or ability, for example in education or sport → A level</div><ul class=\"examples\"><li><strong><em>at... level</strong>: Students at this level may have problems with basic grammar. / What level do you think you’re at?</em></li><li><strong><em>beginner/advanced/national etc level</strong>: Few athletes can compete at international level. / an advanced-level coursebook</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[height]</strong> the height of something in relation to the ground or to another object → ground level, sea level</div><ul class=\"examples\"><li><strong><em>at... level</strong>: Your arms should be at the same level as your desk.</em></li><li><strong><em>eye/knee/shoulder etc level</strong> (=the same height as your eyes etc): Skirts this year are just above knee level.</em></li><li><strong><em>water/oil etc level</strong> (=the height of the water etc from the ground or the bottom of a container): Check the water level in the car radiator.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[floor/ground]</strong> a floor or area of ground that is at a particular height, especially when you can go up or down to other floors or areas → split-level</div><ul class=\"examples\"><li><strong><em>on... level</strong>: Didn’t we park the car on Level 2? / The town is built on different levels. / The medical center is on one level (=so that you do not have to go up or down).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[rank of job]</strong> a particular position in a system that has different ranks of importance → high-level, low-level</div><ul class=\"examples\"><li><strong><em>at... level</strong>: Training is offered at each level in the department.</em></li><li><strong><em>at board/management/senior etc level</strong>: Further talks at ministerial level were held.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[way of understanding]</strong> a way of considering or understanding something</div><ul class=\"examples\"><li><strong><em>on... level</strong>: The story can be understood on many different levels.</em></li><li><strong><em>on a personal/practical/superficial etc level</strong>: I agree with you, but only on a theoretical level.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>at local/state/national etc level</strong> happening within a small area or the whole area of a state, country etc:</div><ul class=\"examples\"><li><em>These changes are taking place at regional level.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>be on the level</strong> <em>informal</em> to be honest and legal:</div><ul class=\"examples\"><li><em>This is all on the level, right?</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>descend/sink to somebody’s level</strong> to behave as badly as someone:</div><ul class=\"examples\"><li><em>If you hit him back, you’ll only be descending to his level.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[tool]</strong> a tool used for checking that a surface is flat <em>SYN spirit-level</em></div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> flat and not sloping in any direction: ► see thesaurus at flat</div><ul class=\"examples\"><li><em>The floors in the old house were not completely level.</em></li><li><em>a level surface suitable for wheelchairs</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> two things that are level are at the same height as each other</div><ul class=\"examples\"><li><strong><em>level with</strong>: Your eyes should be level with the top of the screen.</em></li><li><em>The curtains aren’t quite level.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>British English</em> two sports teams, competitors etc that are level have the same number of points → level-pegging</div><ul class=\"examples\"><li><strong><em>level with</strong>: Before the weekend, Madrid was level with Barcelona.</em></li><li><em>They finished level, with ten points each.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> having the same value or position as something or someone else</div><ul class=\"examples\"><li><strong><em>level with</strong>: Borrowing rates rose to over 8%, roughly level with those in America.</em></li><li><em>He cycled along beside her, keeping level.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a level playing field</strong> a situation in which different people, companies, countries etc can all compete fairly because no one has special advantages:</div><ul class=\"examples\"><li><em>Small businesses want to compete on a level playing field with larger ones.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>do your level best (to do something)</strong> to try as hard as possible to do something:</div><ul class=\"examples\"><li><em>I’ll do my level best to help you.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>level voice/look/gaze</strong> a steady voice, look etc that shows you are calm or determined</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>level teaspoon/cup etc (of something)</strong> an amount of a substance that fills a spoon, cup etc to the top but no more, used as a measure in cooking → heaped: → draw level at draw1(11)</div><ul class=\"examples\"><li><em>Add one level teaspoon of salt.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(past tense and past participle levelled, present participle levelling British English, leveled, leveling American English)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> (also level something ↔ off/out) to make something flat and smooth:</div><ul class=\"examples\"><li><em>Workers leveled the wet concrete with a piece of wood.</em></li><li><em>Cover with a layer of sand and level it off.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to knock down or destroy a building or area completely:</div><ul class=\"examples\"><li><em>Bombs levelled a large part of the town.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> <em>British English</em> to make the score in a game or competition equal:</div><ul class=\"examples\"><li><em>He slipped the ball into the net to level the score at 1–1.</em></li><li><em>United went ahead but the visitors levelled in the 73rd minute.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>level the playing field</strong> to make a situation in which people are competing fair, with no one having special advantages</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>level criticism/charges/accusations etc at/against somebody</strong> to aim criticism etc at a particular person, country etc, especially publicly:</div><ul class=\"examples\"><li><em>the criticism levelled at the United States</em></li><li><em>Serious allegations were levelled against the minister.</em></li></ul></div></div>","4042":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> le‧ver</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈliːvə $ ˈlevər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a stick or handle on a machine or piece of equipment, that you move to operate it: → gear lever</div><ul class=\"examples\"><li><em>Pull this lever to open the gate.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a long thin piece of metal that you use to lift something heavy by putting one end under the object and pushing the other end down</div><div class=\"sense\"><span class=\"snum\">3</span> something you use to influence a situation to get the result that you want:</div><ul class=\"examples\"><li><em>Rich countries use foreign aid as a lever to achieve political aims.</em></li></ul></div>","4043":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> li‧a‧bil‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌlaɪəˈbɪləti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> legal responsibility for something, especially for paying money that is owed, or for damage or injury</div><ul class=\"examples\"><li><strong><em>liability for</strong>: Tenants have legal liability for any damage they cause.</em></li><li><strong><em>liability to</strong>: your liability to capital gains tax</em></li><li><strong><em>liability to do something</strong>: The court ruled there was no liability to pay any refund.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>liabilities</strong> <span class=\"gram\">[plural]</span> <em>technical</em> the amount of debt that must be paid <em>OPP assets</em></div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> someone or something that is likely to cause problems for someone:</div><ul class=\"examples\"><li><em>A kid like Tom would be a liability in any classroom.</em></li><li><strong><em>liability to</strong>: The outspoken minister has become a liability to the government.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>liability to something</strong> <em>law</em> the amount by which something is likely to be affected by a particular kind of problem, illness etc</div></div>","4044":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> li‧a‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>liable to do something</strong> likely to do or say something or to behave in a particular way, especially because of a fault or natural tendency <em>SYN likely</em>:</div><ul class=\"examples\"><li><em>The car is liable to overheat on long trips.</em></li><li><em>He was liable to just show up without warning.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> legally responsible for the cost of something</div><ul class=\"examples\"><li><strong><em>liable for</strong>: people who are liable for income tax at a higher rate</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> likely to be affected by a particular kind of problem, illness etc <em>SYN prone</em></div><ul class=\"examples\"><li><strong><em>liable to</strong>: You’re more liable to injury when you don’t get regular exercise.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>law</em> likely to be legally punished or forced to do something by law</div><ul class=\"examples\"><li><strong><em>liable to/for</strong>: Anyone found trespassing is liable to a maximum fine of $100.</em></li></ul></div>","4045":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> li‧ai‧son</span><span class=\"meta-item\"><strong>IPA:</strong> /liˈeɪzən $ ˈliːəzɑːn, liˈeɪ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular, uncountable]</span> the regular exchange of information between groups of people, especially at work, so that each group knows what the other is doing</div><ul class=\"examples\"><li><strong><em>liaison between</strong>: close liaison between the army and police</em></li><li><strong><em>liaison with</strong>: better liaison with other agencies</em></li><li><strong><em>in liaison with something</strong>: The project has been set up in liaison with the art department.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> (also liaison officer) someone whose job is to talk to different departments or groups and to tell each of them about what the others are doing</div><ul class=\"examples\"><li><strong><em>liaison to</strong>: Renee Ball, liaison to the State Parks Authority</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a secret sexual relationship between a man and a woman, especially a man and a woman who are married but not to each other → affair</div></div>","4046":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> li‧ar</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who deliberately says things which are not true:</div><ul class=\"examples\"><li><em>Are you calling me a liar?</em></li></ul></div>","4047":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> li‧bel</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">when someone writes or prints untrue statements about someone so that other people could have a bad opinion of them → slander</div><ul class=\"examples\"><li><strong><em>for libel</strong>: Holt sued the newspaper for libel.</em></li><li><strong><em>a libel action/case/trial</strong> (=a court case against someone for libel)</em></li><li><em>restrictions on press freedom, such as libel laws</em></li></ul></div>","4048":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lib‧e‧ral</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪbərəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> willing to understand and respect other people’s ideas, opinions, and feelings:</div><ul class=\"examples\"><li><em>a more liberal attitude towards sexuality</em></li><li><em>I had quite liberal parents.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> supporting or allowing gradual political and social changes <em>OPP conservative</em>:</div><ul class=\"examples\"><li><em>a more liberal policy on issues of crime and punishment</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> allowing people or organizations a lot of political or economic freedom</div><ul class=\"examples\"><li><strong><em>liberal state/society/democracy etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">4</span> generous or given in large amounts: → liberally</div><ul class=\"examples\"><li><em>a liberal supply of drinks</em></li><li><strong><em>liberal with</strong>: If only they were as liberal with their cash.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> not exact:</div><ul class=\"examples\"><li><em>a liberal interpretation of the original play</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>liberal education</strong> a kind of education which encourages you to develop a large range of interests and knowledge and respect for other people’s opinions</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone with liberal opinions or principles <em>OPP conservative</em></div></div></div>","4049":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lib‧e‧rate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪbəreɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to free someone from feelings or conditions that make their life unhappy or difficult</div><ul class=\"examples\"><li><strong><em>liberate somebody from something</strong>: women’s freedom to pursue careers liberated from childcare</em></li><li><em>the liberating power of education</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to free prisoners, a city, a country etc from someone’s control:</div><ul class=\"examples\"><li><em>A few days later, our armies liberated the city.</em></li></ul></div>","4050":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lib‧er‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪbəti $ -ər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(plural liberties)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[freedom]</strong> <span class=\"gram\">[uncountable]</span> the freedom and the right to do whatever you want without asking permission or being afraid of authority:</div><ul class=\"examples\"><li><em>the fight for liberty and equality</em></li><li><strong><em>individual/personal liberty</strong>: threats to individual liberty</em></li><li><strong><em>religious/political/economic liberty</strong>: struggles for political liberty</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[legal right]</strong> <span class=\"gram\">[countable usually plural]</span> a particular legal right: → civil liberty</div><ul class=\"examples\"><li><em>liberties such as freedom of speech</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[without permission]</strong> <span class=\"gram\">[singular]</span> something you do without asking permission, especially which may offend or upset someone else</div><ul class=\"examples\"><li><strong><em>take the liberty of doing something</strong>: I took the liberty of cancelling your reservation.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be at liberty to do something</strong> <em>formal</em> to have the right or permission to do something:</div><ul class=\"examples\"><li><em>I am not at liberty to discuss these matters.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>take liberties with somebody/something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to make unreasonable changes in something such as a piece of writing:</div><ul class=\"examples\"><li><em>The film-makers took too many liberties with the original novel.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>old-fashioned</em> to treat someone without respect by being too friendly too quickly, especially in a sexual way:</div><ul class=\"examples\"><li><em>He’s been taking liberties with our female staff.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>at liberty</strong> <em>formal</em> if a prisoner or an animal is at liberty, they are no longer in prison or enclosed in a small place <em>SYN free</em></div></div>","4051":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> li‧brar‧i‧an</span><span class=\"meta-item\"><strong>IPA:</strong> /laɪˈbreəriən $ -ˈbrer-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who works in a library</div></div>","4052":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> li‧bra‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪbrəri, -bri $ -breri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural libraries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a room or building containing books that can be looked at or borrowed → bookshop:</div><ul class=\"examples\"><li><em>a public library</em></li><li><strong><em>school/college/university library</em></strong></li><li><em>a library book</em></li><li><em>library staff</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a group of books, CDs etc, collected by one person</div><div class=\"sense\"><span class=\"snum\">3</span> a room in a large house where books are kept</div><div class=\"sense\"><span class=\"snum\">4</span> a set of books, CDs, videos etc that are produced by the same company and have the same general appearance:</div><ul class=\"examples\"><li><em>a library of modern classics</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>library pictures/footage</strong> <em>British English</em> film or pictures used in a television programme which are not recent</div></div>","4053":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> li‧cence</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪsəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[document]</strong> <span class=\"gram\">[countable]</span> an official document giving you permission to own or do something for a period of time → permit: → driving licence</div><ul class=\"examples\"><li><em>The dealers applied for an export licence.</em></li><li><em>He was arrested for driving without a license.</em></li><li><em>The Tennessee Valley Authority applied for a license to operate the facility.</em></li><li><em>The owner of land could grant a licence to cut and remove timber.</em></li><li><em>I forgot to renew my licence.</em></li><li><em>Persistent offenders face losing their licence.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[agreement]</strong> <span class=\"gram\">[countable, uncountable]</span> an agreement with a company or organization giving permission to make, sell, or use their product</div><ul class=\"examples\"><li><strong><em>under licence</strong>: Guinness is brewed under licence in South Africa.</em></li><li><strong><em>single-user/10-user/site licence</strong> (=permission for computer software to be used by a certain number of people or in a certain place only)</em></li><li><em>a licence agreement</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[freedom]</strong> <span class=\"gram\">[uncountable]</span> freedom to do or say what you think is best:</div><ul class=\"examples\"><li><em>Headteachers should be allowed greater licence in the exercise of their power.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>artistic/poetic licence</strong> the way in which a painter or writer changes the facts of the real world to make their story, description, or picture of events more interesting or more beautiful</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[excuse]</strong> <span class=\"gram\">[countable, uncountable]</span> the freedom or opportunity to behave in a way that is wrong or immoral</div><ul class=\"examples\"><li><strong><em>licence to do something</strong>: Police say it gives youngsters licence to break the law.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>licence to print money</strong> an opportunity to make a lot of money without much work or effort – especially used to show disapproval</div></div>","4054":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> li‧censed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪsənst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>British English</em> having a licence to sell alcoholic drinks:</div><ul class=\"examples\"><li><em>a licensed restaurant</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a car, gun etc that is licensed is one that someone has official permission to own or use</div><div class=\"sense\"><span class=\"snum\">3</span> having been given official permission to do a particular job:</div><ul class=\"examples\"><li><em>a licensed private investigator</em></li></ul></div>","4055":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[tongue]</strong> <span class=\"gram\">[transitive]</span> to move your tongue across the surface of something in order to eat it, wet it, clean it etc:</div><ul class=\"examples\"><li><em>The dog jumped up and licked her face.</em></li><li><strong><em>lick something ↔ up</strong>: A cat licked up the drops spilt on the floor.</em></li><li><strong><em>lick something off something</strong>: He licked the drops off his upper lip.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[sport]</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> to defeat an opponent:</div><ul class=\"examples\"><li><em>I bet we could lick the best teams in Georgia.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[flames/waves]</strong> <span class=\"gram\">[intransitive, transitive]</span> <em>literary</em> if flames or waves lick something, they touch it again and again with quick movements</div><ul class=\"examples\"><li><strong><em>lick at/against</strong>: Soon the flames were licking at the curtains.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>have (got) something licked</strong> <em>informal</em> to have succeeded in dealing with a difficult problem:</div><ul class=\"examples\"><li><em>Just when you think you’ve got it licked, it comes back.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>lick your lips</strong> (also lick your chops<em>American English</em>) to feel eager and excited because you are expecting to get something good:</div><ul class=\"examples\"><li><em>Scottish rugby fans are licking their lips in anticipation.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>lick your wounds</strong> to quietly think about the defeat or disappointment you have just suffered</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>lick somebody’s boots</strong> to obey someone completely because you are afraid of them or want to please them</div></div>","4056":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[cover]</strong> <span class=\"gram\">[countable]</span> a cover for the open part of a pot, box, or other container → top1(4)</div><ul class=\"examples\"><li><strong><em>dustbin/saucepan etc lid</strong>: the name on the coffin lid</em></li><li><strong><em>lid of</strong>: He carefully lifted the lid of the box.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[eye]</strong> <span class=\"gram\">[countable]</span> an eyelid</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>keep a/the lid on something</strong> to control a situation very carefully, especially so that it does not cause problems:</div><ul class=\"examples\"><li><em>keeping the lid on inflation</em></li><li><em>Kline keeps a very tight lid on his private life.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>put a/the lid on something</strong> <em>informal</em> to do something that finally stops something or ruins or ends someone’s plans or hopes:</div><ul class=\"examples\"><li><em>Let’s put a lid on all these rumours.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>take the lid off something</strong> (also lift the lid on something) to let people know the true facts about a bad or shocking situation:</div><ul class=\"examples\"><li><em>a documentary that takes the lid off the world of organized crime</em></li></ul></div>","4057":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /laɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\">(past tense lay /leɪ/, past participle lain /leɪn/, present participle lying, third person singular lies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[flat position]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[intransitive]</span> to be in a position in which your body is flat on the floor, on a bed etc</div><ul class=\"examples\"><li><strong><em>lie on/in etc</strong>: He was lying on the bed smoking a cigarette. / Don’t lie in the sun for too long.</em></li><li><strong><em>lie there</strong>: For a few minutes he just lay there.</em></li><li><strong><em>lie still/awake etc</strong>: She would lie awake worrying.</em></li><li><em>The dog was lying dead on the floor.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> (also lie down) <span class=\"gram\">[intransitive always + adverb/preposition]</span> to put yourself in a position in which your body is flat on the floor or on a bed</div><ul class=\"examples\"><li><strong><em>lie on</strong>: Lie flat on the floor.</em></li><li><strong><em>lie back</strong>: She lay back against the pillows.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to be in a flat position on a surface</div><ul class=\"examples\"><li><strong><em>lie on/in etc</strong>: The papers were lying neatly on his desk.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[exist]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if a problem, an answer, blame etc lies somewhere, it is caused by, exists, or can be found in that thing, person, or situation</div><ul class=\"examples\"><li><strong><em>fault/blame/responsibility lies with somebody</strong>: Part of the blame must lie with social services.</em></li><li><strong><em>the problem/answer etc lies with/in something</strong>: The difficulty lies in providing sufficient evidence.</em></li><li><em>The strength of the book lies in the fact that the material is from classroom experience.</em></li><li><strong><em>herein/therein lies the problem/dilemma etc</strong>: And herein lies the key to their achievements.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[place]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if a town, village, etc lies in a particular place, it is in that place:</div><ul class=\"examples\"><li><em>The town lies in a small wooded valley.</em></li><li><em>The Tasman Sea lies between Tasmania and Australia.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[future]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if something lies ahead of you, lies in the future etc, it is going to happen to you in the future</div><ul class=\"examples\"><li><strong><em>lie ahead</strong>: How will we cope with the difficulties that lie ahead?</em></li><li><strong><em>lie before</strong>: A blank and empty future lay before me.</em></li><li><em>I was wondering what lay in store for us.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[condition]</strong> <span class=\"gram\">[linking verb]</span> to be in a particular state or condition</div><ul class=\"examples\"><li><strong><em>lie empty/open/hidden etc</strong>: The book lay open on the table.</em></li><li><em>The town now lay in ruins.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>lie at the heart/centre/root of something</strong> to be the most important part of something, especially the main cause of it:</div><ul class=\"examples\"><li><em>the issue that lies at the heart of the present conflict</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>lie low</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to remain hidden because someone is trying to find you or catch you:</div><ul class=\"examples\"><li><em>We’ll have to lie low until tonight.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to wait and try not to be noticed by anyone:</div><ul class=\"examples\"><li><em>He decided to lie low for a while after the report came out.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>lie in wait (for somebody)</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to remain hidden in a place and wait for someone so that you can attack them:</div><ul class=\"examples\"><li><em>a giant crocodile lying in wait for its prey</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if something bad lies in wait for you, it is going to happen to you</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>lie (in) second/third/fourth etc (place)</strong> <em>British English</em> to be in second, third etc position in a competition:</div><ul class=\"examples\"><li><em>Liverpool are lying third in the football championship.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>lie heavy on somebody</strong> <em>formal</em> if something lies heavy on you, it makes you feel unhappy:</div><ul class=\"examples\"><li><em>The feelings of guilt lay heavy on him.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[dead person]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if someone lies in a particular place, they are buried there:</div><ul class=\"examples\"><li><em>Here lies Percival Smythe (=written on a gravestone).</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>lie in state</strong> if an important person who has died lies in state, their body is put in a public place so that people can go and look at the body in order to show their respect for that person</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span><span class=\"meta-item\">(past tense and past participle lied, present participle lying, third person singular lies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to deliberately tell someone something that is not true:</div><ul class=\"examples\"><li><em>I could tell from her face that she was lying.</em></li><li><strong><em>lie to</strong>: I would never lie to you.</em></li><li><strong><em>lie about</strong>: She lied about her age.</em></li><li><strong><em>lie through your teeth</strong> (=say something that is completely untrue)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if a picture, account etc lies, it does not show the true facts or the true situation:</div><ul class=\"examples\"><li><em>Statistics can often lie.</em></li><li><em>The camera never lies.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> something that you say or write that you know is untrue:</div><ul class=\"examples\"><li><em>I always know when he’s telling lies.</em></li><li><strong><em>lie about</strong>: I knew that soon she would hear the lies about me.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>give the lie to something</strong> <em>formal</em> to show that something is untrue:</div><ul class=\"examples\"><li><em>This report gives the lie to the company’s claims.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the lie of the land</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the way that a situation is developing at a particular time:</div><ul class=\"examples\"><li><em>I’ll talk to him and get the lie of the land before we go over.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the way an area of land has been formed and the physical features it has</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>(I) tell a lie</strong> <em>British English</em> <em>spoken</em> used when you realize that something you have just said is not correct:</div><ul class=\"examples\"><li><em>It was £25, no, tell a lie, £35.</em></li></ul></div></div>","4058":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /laɪf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(plural lives /laɪvz/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[time somebody is alive]</strong> <span class=\"gram\">[countable, uncountable]</span> the period of time when someone is alive:</div><ul class=\"examples\"><li><em>Learning goes on throughout life.</em></li><li><em>You have your whole life ahead of you.</em></li><li><strong><em>in somebody’s life</strong>: For the first time in my life I was happy. / I’ve never been so embarrassed in my life!</em></li><li><em>I’ve known John all my life (=since I was born).</em></li><li><em>His main aim in life was to have fun.</em></li><li><em>It was one of the best days of my life.</em></li><li><em>The accident scarred him for life (=for the rest of his life).</em></li><li><em>She knew she’d feel guilty for the rest of her life.</em></li><li><em>Raj spent his life caring for others.</em></li><li><em>Bonington spent his entire adult life in France.</em></li><li><em>We don’t know much about the poet’s early life (=when he was young).</em></li><li><em>Poor diet can lead to a whole range of diseases in later life (=when you are older).</em></li><li><em>She married late in life (=when she was fairly old).</em></li><li><em>He’s a life member (=continuing until he dies) of the club.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[state of being alive]</strong> <span class=\"gram\">[countable, uncountable]</span> the state of being alive:</div><ul class=\"examples\"><li><em>The right to life is the most basic of human rights.</em></li><li><em>Danny was a cheerful little boy who loved life.</em></li><li><em>Two firefighters risked their lives to save the children.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[way somebody lives]</strong> <span class=\"gram\">[countable usually singular]</span> the way you live your life, and what you do and experience during it</div><ul class=\"examples\"><li><strong><em>lead/live/have a... life</strong>: The operation should enable Bobby to lead a normal life. / She just wanted to live a quiet life.</em></li><li><em>Having a baby changes your life completely.</em></li><li><em>The family moved to Australia to start a new life.</em></li><li><em>Ken’s whole life revolved around surfing (=that was the main interest and purpose of his life).</em></li><li><em>You shouldn’t let your boyfriend rule your life (=control and affect everything you do).</em></li><li><em>My grandmother had a hard life (=a life full of problems).</em></li><li><em>She’s led a very sheltered life (=a life in which you have been protected from unpleasant things).</em></li><li><strong><em>a life of crime/poverty/misery etc</strong>: He had been drawn into a life of crime.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[particular situation/job]</strong> <span class=\"gram\">[countable, uncountable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the experiences, activities, and ways of living that are typical of being in a particular job, situation, society etc:</div><ul class=\"examples\"><li><em>Why do so few women enter political life?</em></li><li><em>the British way of life</em></li><li><strong><em>city/country/village etc life</strong>: Noise has become one of the main pollutants of modern city life.</em></li><li><strong><em>army/student/college etc life</strong>: He missed the routine of army life.</em></li><li><em>Are you enjoying married life?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the time in your life when you are doing a particular job, are in a particular situation etc</div><ul class=\"examples\"><li><strong><em>somebody’s life as something</strong>: Now a celebrity chef, he rarely talks about his life as an army cook.</em></li><li><em>Sara admits to having affairs throughout her married life.</em></li><li><em>Most of his working life was spent in the shipyards.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>social/personal/sex etc life</strong> the activities in your life relating to your friends, your family, sex etc:</div><ul class=\"examples\"><li><em>I don’t need advice about my love life.</em></li><li><em>traditional views of family life</em></li><li><em>Children need a caring and happy home life.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[human existence]</strong> <span class=\"gram\">[uncountable]</span> human existence, considered as a variety of experiences and activities:</div><ul class=\"examples\"><li><em>My Aunt Julia had very little experience of life.</em></li><li><em>Life has a way of changing the best of plans.</em></li><li><em>For some people, religion gives life a meaning.</em></li><li><strong><em>daily/everyday life</strong>: the frustrations and disappointments of everyday life</em></li><li><em>I try to see the funny side of life.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[time when something exists/works]</strong> <span class=\"gram\">[countable usually singular]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the period of time during which something happens or exists</div><ul class=\"examples\"><li><strong><em>life of</strong>: The issues will not be resolved during the life of the present parliament.</em></li><li><strong><em>start/begin/come to life as something</strong>: The building began life as a monastery.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the period of time during which something is still good enough to use → shelf life</div><ul class=\"examples\"><li><strong><em>life of</strong>: What’s the average life of a passenger aircraft?</em></li><li><em>Careful use can extend the life of your washing machine.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[living things]</strong> <span class=\"gram\">[uncountable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the quality of being alive that people, animals, plants etc have and that objects and dead things do not have:</div><ul class=\"examples\"><li><em>Ben felt her neck for a pulse or any other sign of life.</em></li><li><em>In the springtime, everything comes to life again.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> living things, such as people, animals, or plants: → wildlife</div><ul class=\"examples\"><li><em>Is there life on other planets?</em></li><li><strong><em>human/animal/plant/bird etc life</strong>: The island is rich in bird life.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>be somebody’s (whole) life</strong> to be the most important thing or person to someone:</div><ul class=\"examples\"><li><em>Music is Laura’s whole life.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>life and death</strong> (also life or death) used for emphasizing that a situation, decision etc is extremely urgent and important, especially because someone is at risk of dying:</div><ul class=\"examples\"><li><em>Don’t call me unless it’s a matter of life and death.</em></li><li><em>a life or death decision</em></li><li><em>A doctor’s job involves life and death situations.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[game]</strong> <span class=\"gram\">[countable]</span> a chance in a game, especially a computer game, in which you can be defeated or do something wrong and can still continue playing:</div><ul class=\"examples\"><li><em>He’s up to level five and still has three lives left.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[activity]</strong> <span class=\"gram\">[uncountable]</span> activity or movement:</div><ul class=\"examples\"><li><em>The house was quiet and there was no sign of life.</em></li><li><em>She was always so cheerful and full of life.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[interest/excitement]</strong> <span class=\"gram\">[uncountable]</span> a quality of being interesting or exciting:</div><ul class=\"examples\"><li><em>Try to put some life into your writing.</em></li><li><em>The game really came to life after a magnificent goal from Rooney.</em></li><li><em>A gifted teacher can really bring literature to life for his or her students.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>come to life/roar into life/splutter into life etc</strong> to suddenly start working:</div><ul class=\"examples\"><li><em>Finally the car spluttered into life.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>make life difficult/easier etc</strong> to make it difficult, easier etc to do something:</div><ul class=\"examples\"><li><em>Surely computers are supposed to make life easier, not more complicated!</em></li><li><strong><em>life for</strong>: Why make life difficult for yourself?</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>the life and soul of the party</strong> <em>British English</em>, the life of the party<em>American English</em> someone who enjoys social occasions and is fun and exciting to be with</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>life and limb</strong> <em>formal</em> your life and physical health – used especially when this is threatened in some way:</div><ul class=\"examples\"><li><em>She risks life and limb every day in her job as an undercover investigator.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>get a life!</strong> <em>spoken</em> used to tell someone that you think they are boring and should find more exciting things to do:</div><ul class=\"examples\"><li><em>You guys should just stop moaning and get a life!</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>that’s life</strong> (also such is life) <em>spoken</em> used to say that something is disappointing but you have to accept it:</div><ul class=\"examples\"><li><em>Oh well, that’s life!</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>life’s a bitch</strong> <em>spoken</em> <em>not polite</em> used to say that bad things happen in life</div><div class=\"sense\"><span class=\"snum\">21</span> <strong>this is the life</strong> <em>spoken</em> used when you are relaxing and doing something you enjoy:</div><ul class=\"examples\"><li><em>Ah, this is the life! Lying on the beach, sipping cool drinks.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>the shock/surprise/game etc of somebody’s life</strong> the biggest shock or surprise, the best game etc that someone has ever had: → have the time of your life at time1(41)</div><ul class=\"examples\"><li><em>I had the surprise of my life when I saw John standing there.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>how’s life?</strong> <em>spoken</em> used to ask someone if they are well, what they have been doing etc:</div><ul class=\"examples\"><li><em>Hi Bob! How’s life?</em></li><li><em>How’s life been with you?</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>life goes on</strong> <em>spoken</em> used to say that you must continue to live a normal life even when something sad or disappointing has happened:</div><ul class=\"examples\"><li><em>We both miss him, but life goes on.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>a life of its own</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if something has a life of its own, it seems to move or work by itself:</div><ul class=\"examples\"><li><em>The ball seemed to have acquired a life of its own.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if something has a life of its own, it exists and develops without depending on other things:</div><ul class=\"examples\"><li><em>Slowly but surely, the project is taking on a life of its own.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>cannot for the life of me</strong> <em>spoken</em> used to say that you cannot remember or understand something even when you try hard:</div><ul class=\"examples\"><li><em>I couldn’t for the life of me remember his name.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>life’s too short</strong> <em>spoken</em> used to say that you should not waste time doing something or worrying about something:</div><ul class=\"examples\"><li><em>Forget about it. Life’s too short.</em></li><li><strong><em>life for</strong>: Life’s too short for moping about.</em></li><li><strong><em>life’s too short to do something</strong>: Life’s too short to bear grudges.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>not on your life</strong> <em>spoken</em> used as a reply to a question or suggestion to say that you definitely will not do something:</div><ul class=\"examples\"><li><em>‘Are you going to go and work for him then?’ ‘Not on your life!’</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>the woman/man/girl etc in your life</strong> the woman or man you are married to or are having a relationship with – used especially in advertisements:</div><ul class=\"examples\"><li><em>This is the ideal gift for the man in your life.</em></li></ul><div class=\"sense\"><span class=\"snum\">30</span> <strong>[prison]</strong> <span class=\"gram\">[uncountable]</span> (also life imprisonment) the punishment of being put in prison for the rest of your life → life sentence, lifer</div><ul class=\"examples\"><li><strong><em>be sentenced to/get/be given life</strong>: He was sentenced to life for the murder. / I think she should get life.</em></li></ul><div class=\"sense\"><span class=\"snum\">31</span> <strong>[art]</strong> <span class=\"gram\">[uncountable]</span> when you paint, draw etc something you are looking at, especially a person or animal: → still life</div><ul class=\"examples\"><li><em>She’s taking classes in life drawing.</em></li></ul><div class=\"sense\"><span class=\"snum\">32</span> <strong>frighten/scare the life out of somebody</strong> <em>informal</em> to make someone feel very frightened:</div><ul class=\"examples\"><li><em>Don’t do that! You scared the life out of me!</em></li></ul><div class=\"sense\"><span class=\"snum\">33</span> <strong>there’s life in the old dog yet</strong> <em>spoken</em> used to say that although someone or something is old, they are still able to do something – used humorously</div><div class=\"sense\"><span class=\"snum\">34</span> <strong>live/lead/have the life of Riley</strong> <em>informal</em> to have a very easy and comfortable life and not have to work hard:</div><ul class=\"examples\"><li><em>He spends all day lounging by the pool and living the life of Riley.</em></li></ul><div class=\"sense\"><span class=\"snum\">35</span> <strong>[book/film]</strong> <span class=\"gram\">[uncountable]</span> the story of someone’s life <em>SYN biography</em>:</div><ul class=\"examples\"><li><em>Boswell’s ‘Life of Johnson’</em></li></ul><div class=\"sense\"><span class=\"snum\">36</span> <strong>the next life</strong> (also the life to come, life after death) the time after death, in which some people believe life continues in another form:</div><ul class=\"examples\"><li><em>She expects to meet her dead husband in the next life.</em></li></ul></div>","4059":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> life‧long</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪflɒŋ $ -lɒːŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">continuing or existing all through your life:</div><ul class=\"examples\"><li><em>She became a lifelong friend of ours.</em></li><li><em>David finally realized his lifelong ambition.</em></li></ul></div>","4060":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> life‧span</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪfspæn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the average length of time that someone will live or that something will continue to work → lifetime:</div><ul class=\"examples\"><li><em>Men have a shorter lifespan than women.</em></li><li><strong><em>a lifespan of 5 days/10 years etc</strong>: A TV set has an average lifespan of 11 years.</em></li></ul></div>","4061":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> life‧style</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪfstaɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the way a person or group of people live, including the place they live in, the things they own, the kind of job they do, and the activities they enjoy:</div><ul class=\"examples\"><li><em>Regular exercise is part of a healthy lifestyle.</em></li><li><strong><em>lavish/comfortable/simple etc lifestyle</strong>: They lead an extremely lavish lifestyle.</em></li></ul></div>","4062":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> life‧time</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪftaɪm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable usually singular]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the period of time during which someone is alive or something exists → lifespan</div><ul class=\"examples\"><li><strong><em>during/in somebody’s lifetime</strong>: During her lifetime she had witnessed two world wars.</em></li><li><em>It’s the sort of opportunity you see only once in a lifetime.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the chance/experience etc of a lifetime</strong> the best opportunity, experience etc that you will ever have:</div><ul class=\"examples\"><li><em>It was the holiday of a lifetime.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>not in this lifetime</strong> <em>spoken</em> not at all <em>SYN never</em>:</div><ul class=\"examples\"><li><em>‘Would you go out with him after he dropped you?’ ‘Not in this lifetime.’</em></li></ul></div>","4063":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɪft/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[move something upwards]</strong> <span class=\"gram\">[transitive]</span> (also lift up) to move something or someone upwards into the air:</div><ul class=\"examples\"><li><em>Sophie lifted the phone before the second ring.</em></li><li><em>He lifted the lid on the pot of soup.</em></li><li><em>The lumber was lifted by crane and dropped into the truck.</em></li><li><strong><em>lift somebody/something onto/into/out of etc something</strong>: They lifted Andrew onto the bed.</em></li><li><strong><em>lift somebody from something</strong>: The driver was lifted from the wreck.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[part of the body]</strong> <span class=\"gram\">[intransitive, transitive]</span> (also lift up) to move part of your body up to a higher position <em>SYN raise</em></div><ul class=\"examples\"><li><strong><em>lift your hand/arm/leg etc</strong>: She lifted her hand to knock on the door once again. / Pam lifted her shoulders in a little shrug.</em></li><li><strong><em>lift your head/eyes</strong> (=move your head or eyes up so that you can look at something): She lifted her head to gaze at him.</em></li><li><em>He heard a scream and the hairs on the back of his neck began to lift.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[controls/laws]</strong> <span class=\"gram\">[transitive]</span> to remove a rule or a law that says that something is not allowed</div><ul class=\"examples\"><li><strong><em>lift a restriction/an embargo/sanctions etc</strong>: The government plans to lift its ban on cigar imports.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[by plane]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to take people or things to or from a place by aircraft:</div><ul class=\"examples\"><li><em>More troops are being lifted into the area as the fighting spreads.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>not lift a finger (to do something)</strong> <em>informal</em> to do nothing to help:</div><ul class=\"examples\"><li><em>He never lifted a finger to help me with the kids.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>lift somebody’s spirits</strong> to make someone feel more cheerful and hopeful</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[clouds/mist]</strong> <span class=\"gram\">[intransitive]</span> if cloud or mist lifts, it disappears</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[sad feelings]</strong> <span class=\"gram\">[intransitive]</span> if feelings of sadness lift, they disappear:</div><ul class=\"examples\"><li><em>Jan’s depression seemed to be lifting at last.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[use somebody’s ideas/words]</strong> <span class=\"gram\">[transitive]</span> to take words, ideas etc from someone else’s work and use them in your work, without stating where they came from and as if they were your own words etc</div><ul class=\"examples\"><li><strong><em>lift something from somebody/something</strong>: The words were lifted from an article in a medical journal.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[steal]</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> to steal something</div><ul class=\"examples\"><li><strong><em>lift something from somebody/something</strong>: They had lifted dozens of CDs from the store.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[voice]</strong> <span class=\"gram\">[transitive]</span> (also lift up) <em>literary</em> if you lift your voice, you speak, shout, or sing more loudly <em>SYN raise</em></div><div class=\"sense\"><span class=\"snum\">12</span> <strong>[increase]</strong> <span class=\"gram\">[transitive]</span> to make prices, profit etc increase:</div><ul class=\"examples\"><li><em>The U.S. may use tax cuts to lift the economy.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[vegetables]</strong> <span class=\"gram\">[transitive]</span> to dig up vegetables that grow under the ground:</div><ul class=\"examples\"><li><em>She was lifting potatoes.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[in a building]</strong> <span class=\"gram\">[countable]</span> <em>British English</em> a machine that you can ride in, that moves up and down between the floors in a tall building SYN elevator<em>American English</em>:</div><ul class=\"examples\"><li><em>They took the lift down to the bar.</em></li><li><em>It’s on the 3rd floor. Let’s use the lift.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[in a car]</strong> <span class=\"gram\">[countable]</span> if you give someone a lift, you take them somewhere in your car <em>SYN ride</em>:</div><ul class=\"examples\"><li><em>Do you want a lift into town?</em></li><li><em>John gave me a lift home.</em></li><li><em>He very kindly offered me a lift.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>give somebody/something a lift</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to make someone feel more cheerful and more hopeful:</div><ul class=\"examples\"><li><em>The new park has given everyone in the neighbourhood a lift.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to make something such as a business, the economy etc operate better:</div><ul class=\"examples\"><li><em>The Bank of England’s announcement gave the stock market a lift today.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[lifting movement]</strong> <span class=\"gram\">[countable]</span> a movement in which something is lifted or raised up:</div><ul class=\"examples\"><li><em>She does sit-ups and leg lifts every morning.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[wind/aircraft]</strong> <span class=\"gram\">[uncountable]</span> the pressure of air that keeps something such as an aircraft up in the air or lifts it higher</div></div></div>","4064":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /laɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[natural/artificial light]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[uncountable]</span> the energy from the Sun, a flame, a lamp etc that allows you to see things:</div><ul class=\"examples\"><li><em>We saw a flash of light.</em></li><li><strong><em>in/by the light of something</strong>: Everything looked grey in the dim light of the oil lamp. / I read by the light of the fire.</em></li><li><strong><em>in/into the light</strong>: The man moved forward into the light.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[countable]</span> a particular type of light, with its own particular colour, level of brightness etc:</div><ul class=\"examples\"><li><em>The colours look different in different lights.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[lamp/electric light etc]</strong> <span class=\"gram\">[countable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> something that produces light, especially electric light, to help you to see: → the bright lights at bright(14)</div><ul class=\"examples\"><li><em>Ahead of us we could see the lights of the city.</em></li><li><em>We’re having a mixture of wall lights and ceiling lights in different parts of the house.</em></li><li><strong><em>turn/switch/put on a light</strong>: I switched on the light in the bedroom.</em></li><li><strong><em>turn/switch/put off a light</strong>: Don’t forget to switch the lights off when you go out.</em></li><li><strong><em>turn/switch/put out a light</strong>: Can you turn the light out downstairs?</em></li><li><strong><em>a light is/comes/goes on</strong>: The lights in the office were still on. / The street lights were just beginning to come on. / He left a light on in the kitchen.</em></li><li><strong><em>a light is off/out</strong>: Make sure all the lights are off when you leave. / Suddenly all the lights in the house went out.</em></li><li><em>Can you turn the light down (=make it less bright) a bit?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> something such as a lamp that you can carry to give you light:</div><ul class=\"examples\"><li><em>Shine a light over here, will you?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[traffic control]</strong> <span class=\"gram\">[countable usually plural]</span> one of a set of red, green, and yellow lights used for controlling traffic <em>SYN traffic lights</em>: → green light</div><ul class=\"examples\"><li><em>We waited for the lights to change.</em></li><li><em>Eventually the lights turned green.</em></li><li><em>The driver had failed to stop at a red light.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[on a vehicle]</strong> <span class=\"gram\">[countable usually plural]</span> one of the lights on a car, bicycle etc that help you to see at night: → brake light, headlight, parking light</div><ul class=\"examples\"><li><em>He was dazzled by the lights of oncoming traffic.</em></li><li><em>You’ve left your lights on.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>first light</strong> <em>literary</em> the time when light first appears in the morning sky:</div><ul class=\"examples\"><li><em>We set out at first light the next day.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be/stand in somebody’s light</strong> to prevent someone from getting all the light they need to see or do something:</div><ul class=\"examples\"><li><em>Could you move to the left a little – you’re standing in my light.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[for a cigarette]</strong> <strong>a light</strong> a match or something else to light a cigarette:</div><ul class=\"examples\"><li><em>Have you got a light, please?</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[in somebody’s eyes]</strong> <span class=\"gram\">[singular]</span> <em>literary</em> an expression in someone’s eyes that shows an emotion or intention <em>SYN gleam</em>:</div><ul class=\"examples\"><li><em>There was a murderous light in his eyes.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>set light to something</strong> to make something start burning:</div><ul class=\"examples\"><li><em>The candle fell over and set light to the barn.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>come to light/be brought to light</strong> if new information comes to light, it becomes known:</div><ul class=\"examples\"><li><em>This evidence did not come to light until after the trial.</em></li><li><em>The mistake was only brought to light some years later.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>throw/shed/cast light on something</strong> to provide new information that makes a difficult subject or problem easier to understand:</div><ul class=\"examples\"><li><em>Melanie was able to shed some light on the situation.</em></li><li><em>These discoveries may throw new light on the origins of the universe.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>in the light of something</strong> <em>British English</em>, in light of something<em>American English</em> if you do or decide something in the light of something else, you do it after considering that thing:</div><ul class=\"examples\"><li><em>In light of this tragic event, we have canceled the 4th of July celebrations.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>in a new/different/bad etc light</strong> if someone or something is seen or shown in a particular light, people can see that particular part of their character:</div><ul class=\"examples\"><li><em>I suddenly saw my father in a new light.</em></li><li><em>This incident will put the company in a very bad light.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>see the light</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to suddenly understand something:</div><ul class=\"examples\"><li><em>At last doctors have seen the light!</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to begin to believe in a religion very strongly</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>see the light (of day)</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if an object sees the light of day, it is taken from the place where it has been hidden, and becomes publicly known:</div><ul class=\"examples\"><li><em>Some of these documents will probably never see the light of day.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if a law, decision etc sees the light of day, it comes into existence for the first time</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>light at the end of the tunnel</strong> something that gives you hope for the future after a long and difficult period:</div><ul class=\"examples\"><li><em>It’s been a hard few months, but we’re finally beginning to see the light at the end of the tunnel.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>have your name in lights</strong> <em>informal</em> to be successful and famous in theatre or films</div><div class=\"sense\"><span class=\"snum\">18</span> <strong>go/be out like a light</strong> <em>informal</em> to go to sleep very quickly because you are very tired:</div><ul class=\"examples\"><li><em>I went straight to bed and went out like a light.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>a leading light in/of something</strong> <em>informal</em> someone who is important in a particular organization:</div><ul class=\"examples\"><li><em>She’s one of the leading lights of the local dramatic society.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>the light of somebody’s life</strong> the person that someone loves more than anyone else:</div><ul class=\"examples\"><li><em>Her son was the light of her life.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>[window]</strong> <span class=\"gram\">[countable]</span> a window in a roof or wall that allows light into a room</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(comparative lighter, superlative lightest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[colour]</strong> a light colour is pale and not dark: ► see thesaurus at colour</div><ul class=\"examples\"><li><em>You look nice in light colours.</em></li><li><strong><em>light blue/green/grey etc</strong>: She had blue eyes and light brown hair.</em></li><li><em>I wanted a lighter yellow paint for the walls.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[daylight]</strong> <strong>it is/gets light</strong> if it is light, there is the natural light of day <em>OPP dark</em>:</div><ul class=\"examples\"><li><em>We’ll keep on looking while it’s still light.</em></li><li><em>It was seven o&#x27;clock and just starting to get light.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[rooms]</strong> a room that is light has plenty of light in it, especially from the sun <em>OPP dark</em>: ► see thesaurus at bright</div><ul class=\"examples\"><li><em>The kitchen was light and spacious.</em></li><li><em>The office was a big light room at the back of the house.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[not heavy]</strong> not very heavy: → lighten, lightweight2</div><ul class=\"examples\"><li><em>You can carry this bag – it’s fairly light.</em></li><li><em>You should wear light, comfortable shoes.</em></li><li><em>The truck was quite light and easy to drive.</em></li><li><em>She was as light as a feather (=very light) to carry.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[not great]</strong> if something is light, there is not very much of it or it is not very great <em>OPP heavy</em>:</div><ul class=\"examples\"><li><em>Traffic is lighter before 8 a.m.</em></li><li><em>A light rain began to fall.</em></li><li><em>She was wearing only light make-up.</em></li><li><em>people who have suffered only light exposure to radiation</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[clothes]</strong> light clothes are thin and not very warm:</div><ul class=\"examples\"><li><em>She took a light sweater in case the evening was cool.</em></li><li><em>a light summer coat</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[wind]</strong> a light wind is blowing without much force <em>OPP strong</em>:</div><ul class=\"examples\"><li><em>Leaves were blowing about in the light wind.</em></li><li><em>There was a light easterly breeze.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[sound]</strong> a light sound is very quiet <em>OPP loud</em>:</div><ul class=\"examples\"><li><em>There was a light tap at the door.</em></li><li><em>Her voice was light and pleasant.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[touch]</strong> a light touch is gentle and soft:</div><ul class=\"examples\"><li><em>She gave him a light kiss on the cheek.</em></li><li><em>He felt a light tap on his shoulder.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[work/exercise]</strong> light work is not hard or tiring:</div><ul class=\"examples\"><li><em>I found him some light work to do.</em></li><li><em>She only has a few light duties around the house.</em></li><li><em>The doctor has advised me to take regular light exercise.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[food]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> food or drink that is light either does not have a strong taste or does not make you feel full very quickly, for example because it does not contain very much fat, sugar, or alcohol <em>OPP rich</em>:</div><ul class=\"examples\"><li><em>We had a light white wine with the fish.</em></li><li><em>a light, refreshing dessert</em></li><li><em>a new light cheese spread with virtually no fat</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a light meal is a small meal <em>OPP big</em>:</div><ul class=\"examples\"><li><em>I had a light lunch in town.</em></li><li><em>a delicious light snack</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> food that is light contains a lot of air:</div><ul class=\"examples\"><li><em>a type of light, sweet bread</em></li><li><em>Beat the mixture until it is light and fluffy.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[punishment]</strong> a light punishment is not very severe <em>OPP harsh</em>:</div><ul class=\"examples\"><li><em>a fairly light sentence</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>a light smoker/drinker/eater etc</strong> someone who does not smoke etc very much</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>light sleep/doze</strong> a sleep from which you wake up easily:</div><ul class=\"examples\"><li><em>I fell into a light sleep.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>a light sleeper</strong> someone who wakes up easily if there is any noise etc:</div><ul class=\"examples\"><li><em>She’s quite a light sleeper.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[not serious]</strong> not serious in meaning, style, or manner, and only intended to entertain people:</div><ul class=\"examples\"><li><em>His speech gradually became lighter in tone.</em></li><li><em>an evening of light music</em></li><li><em>It’s a really good book if you want a bit of light reading.</em></li><li><em>The show looks at some of the lighter moments from the world of politics.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>light relief</strong> something that is pleasant and amusing after something sad or serious:</div><ul class=\"examples\"><li><em>I’m glad you’ve arrived – we could all do with a little light relief!</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>make light of something</strong> to joke about something or treat it as not being very serious, especially when it is important:</div><ul class=\"examples\"><li><em>She tried to make light of the situation, but I could tell that she was worried.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>on a lighter note/in a lighter vein</strong> used when you are going to say something less sad or serious:</div><ul class=\"examples\"><li><em>On a lighter note, the concert raised over £300 for school funds.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>make light work of something</strong> to do something or deal with something quickly and easily:</div><ul class=\"examples\"><li><em>A freezer and microwave oven can make light work of cooking.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>be light on your feet</strong> to be able to move quickly and gracefully:</div><ul class=\"examples\"><li><em>She’s very agile and light on her feet.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>a light heart</strong> <em>literary</em> someone who has a light heart feels happy and not worried: → light-hearted</div><ul class=\"examples\"><li><em>I set off for work with a light heart.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>[soil]</strong> light soil is easy to break into small pieces <em>OPP heavy</em>:</div><ul class=\"examples\"><li><em>Carrots grow well in light soils.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\">(past tense and past participle lit or lighted)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to start to burn, or to make something start to burn:</div><ul class=\"examples\"><li><em>He stopped to light a cigarette.</em></li><li><em>I lit the fire and poured a drink.</em></li><li><em>I couldn’t get the candles to light.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to provide light for a place GRAMMAR Light is usually passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be lit by/with something</strong>: The room was lit by one large, central light.</em></li><li><em>The porch is always well lit at night.</em></li><li><em>The kitchen was warm and brightly lit.</em></li><li><em>a poorly lit car park</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>light the/somebody’s way</strong> to provide light for someone while they are going somewhere:</div><ul class=\"examples\"><li><em>We had only a few torches between us to light the way.</em></li></ul></div></div>","4065":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> light‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪtɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the lights that light a room, building, or street, or the quality of the light produced:</div><ul class=\"examples\"><li><em>Better street lighting might help to reduce crime.</em></li><li><strong><em>fluorescent/electric lighting</strong>: Fluorescent lighting is much cheaper to use than light bulbs.</em></li><li><strong><em>subdued/dim/soft lighting</strong> (=lighting that is not very bright)</em></li><li><strong><em>artificial/natural lighting</em></strong></li></ul></div>","4066":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> light‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪtli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> with only a small amount of weight or force <em>SYN gently</em>:</div><ul class=\"examples\"><li><em>I knocked lightly on the door.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> using or having only a small amount of something:</div><ul class=\"examples\"><li><em>a lightly greased pan</em></li><li><em>lightly armed soldiers</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>take/treat/approach something lightly</strong> to do something without serious thought:</div><ul class=\"examples\"><li><em>Divorce is not a matter you can afford to take lightly.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>get off lightly</strong> (also be let off lightly) to be punished in a way that is less severe than you deserve:</div><ul class=\"examples\"><li><em>He got off lightly because his father was a lawyer.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> without worrying, or without appearing to be worried:</div><ul class=\"examples\"><li><em>‘Things will be fine,’ he said lightly.</em></li></ul></div>","4067":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> light‧ning</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪtnɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a powerful flash of light in the sky caused by electricity and usually followed by thunder:</div><ul class=\"examples\"><li><em>Two farm workers were struck by lightning (=hit by lightning).</em></li><li><em>Lightning flashed overhead.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>like lightning</strong> extremely quickly:</div><ul class=\"examples\"><li><em>Mitch moved like lightning and caught the little girl before she fell.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>lightning never strikes twice</strong> something bad or unpleasant is not likely to happen to the same people or in the same place twice</div></div>","4068":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">preposition</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /laɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[similar]</strong> similar to something else, or happening in the same way:</div><ul class=\"examples\"><li><em>Her hair is dark brown like mine.</em></li><li><em>A club should be like a big family.</em></li><li><em>He eats like a pig!</em></li><li><strong><em>look/sound/feel/taste/seem like</strong>: The garden looked like a jungle. / At last he felt like a real soldier.</em></li><li><em>My experience is very much like that described in the book.</em></li><li><em>He’s very like his brother.</em></li><li><em>Sometimes you sound just like (=exactly like) my mum!</em></li><li><em>He’s growing more like his father every day.</em></li><li><em>He looked nothing like (=not at all like) the man in the police photograph.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>what is somebody/something like?</strong> <em>spoken</em> used when asking someone to describe or give their opinion of a person or thing:</div><ul class=\"examples\"><li><em>What’s their house like inside?</em></li><li><em>What are Dan’s parents like?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[example]</strong> for example: RegisterIn written English, people usually use for example, for instance, or such as rather than like:· packaging materials, for instance paper, glass, and plastic· Try to avoid fatty foods such as cakes and biscuits.</div><ul class=\"examples\"><li><em>Things like glass, paper, and plastic can all be recycled.</em></li><li><em>Try to avoid fatty foods like cakes and biscuits.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[typical]</strong> typical of a particular person</div><ul class=\"examples\"><li><strong><em>be like somebody to do something</strong>: It’s not like Steven to be late. / It’s just like her to run away from her responsibilities!</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>like this/that/so</strong> <em>spoken</em> used when you are showing someone how to do something:</div><ul class=\"examples\"><li><em>You have to fold the corners back, like so.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>just like that</strong> <em>informal</em> if you do something just like that, you do it without thinking about it or planning it carefully:</div><ul class=\"examples\"><li><em>You can’t give up your job just like that!</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>something like</strong> not much more or less than a particular amount <em>SYN about</em>:</div><ul class=\"examples\"><li><em>The machinery alone will cost something like thirty thousand pounds.</em></li><li><em>He’s scored something like 60 goals this season.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>nothing like</strong> <em>British English</em> not at all:</div><ul class=\"examples\"><li><em>Twenty years ago travel was nothing like as easy as it is now.</em></li><li><em>This will be nothing like enough money.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>there’s nothing like</strong> used to say that a particular thing is very enjoyable:</div><ul class=\"examples\"><li><em>There’s nothing like a nice cup of tea!</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>more like</strong> used when giving an amount or number that you think is closer to being right than one that has been mentioned:</div><ul class=\"examples\"><li><em>The builders say they’ll be finished in three months, but I think it’ll be more like six.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>that’s more like it/this is more like it</strong> <em>spoken</em> used to say that something is better, more correct, or more enjoyable than something else:</div><ul class=\"examples\"><li><em>That gives us a total of 52 – that’s more like it.</em></li><li><em>She sat down by the pool and took a sip of her wine. ‘This is more like it,’ she said.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>more like it</strong> <em>British English</em> <em>spoken</em> used when you want to change something that has been said, to make it more true:</div><ul class=\"examples\"><li><em>‘Poor David,’ she said. ‘Poor Harriet, more like it!’</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>what are you like!</strong> <em>British English</em> <em>spoken</em> <em>informal</em> used in a joking, friendly way, when you are surprised by what someone has just said or done:</div><ul class=\"examples\"><li><em>‘I think she’s a lovely lady.’ ‘What are you like!’</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[think something is nice]</strong> to enjoy something or think that it is nice or good → love <em>OPP dislike</em>:</div><ul class=\"examples\"><li><em>I like your jacket.</em></li><li><em>I don’t really like classical music.</em></li><li><em>Do you like this colour?</em></li><li><em>I like my coffee quite weak.</em></li><li><em>I don’t like it when you get angry.</em></li><li><em>How do you like living in London (=how much do you like it)?</em></li><li><strong><em>like doing something</strong>: I don’t like talking in public.</em></li><li><strong><em>like to do something</strong>: I like to see people enjoying themselves.</em></li><li><em>I quite like their new album.</em></li><li><em>We really liked the film.</em></li><li><em>The time I like best (=like most of all) is the evening when it’s cool.</em></li><li><strong><em>like something about somebody/something</strong>: One of the things I like about John is his sense of humour.</em></li><li><em>I didn’t like the idea of being a single parent.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[like a person]</strong> to think that someone is nice or enjoy being with them:</div><ul class=\"examples\"><li><em>Jessica’s really nice, but I don’t like her boyfriend.</em></li><li><em>You’ll like my brother.</em></li><li><em>I really like Sam.</em></li><li><em>She’s a lovely girl and I like her very much.</em></li><li><em>In time, I got to like her (=began to like her).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[approve of something]</strong> to approve of something and think that it is good or right:</div><ul class=\"examples\"><li><em>I don’t like dishonesty.</em></li><li><em>I don’t like the way he shouts at the children.</em></li><li><strong><em>like doing something</strong>: He’s never liked talking about people behind their backs.</em></li><li><strong><em>like somebody doing something</strong>: I don’t like him taking all the credit when he didn’t do any of the work.</em></li><li><strong><em>like to do something</strong>: She doesn’t like to swear in front of the children.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[do something regularly]</strong> to try to do something regularly or make something happen regularly</div><ul class=\"examples\"><li><strong><em>like to do something</strong>: I like to get up early and get a bit of work done before breakfast.</em></li><li><strong><em>like somebody to do something</strong>: We like our students to take part in college sports activities.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[want]</strong> <strong>would like</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say that you want something or want to do something → love:</div><ul class=\"examples\"><li><em>I’d like a cheeseburger, please.</em></li><li><strong><em>would like to do something</strong>: I’d like to see that film. / There’s something I’d like to tell you. / I’d like to apologize for my behaviour yesterday. / I’d just like to say how grateful we are for your help.</em></li><li><strong><em>would like somebody to do something</strong>: He would like us all to be at the meeting.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to ask someone if they want something or want to do something:</div><ul class=\"examples\"><li><em>Would you like a drink?</em></li><li><em>What would you like to eat?</em></li><li><em>Contact our office if you would like more information.</em></li><li><strong><em>would somebody like to do something</strong>: Would you like to come with us? / How would you like (=would you like) to spend the summer in Italy?</em></li><li><strong><em>would somebody like somebody to do something</strong>: Would you like me to pick you up in the morning?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>whatever/wherever/anything etc you like</strong> whatever thing you want, in whatever place you want etc:</div><ul class=\"examples\"><li><em>You can sit wherever you like.</em></li><li><em>You can choose anything you like from the menu.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>as long as you like/as much as you like etc</strong> as long, as much etc as you want:</div><ul class=\"examples\"><li><em>You know you’re welcome to stay with us as long as you like.</em></li><li><em>Take as many as you like.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>(whether you) like it or not</strong> used to emphasize that something unpleasant is true or will happen and cannot be changed:</div><ul class=\"examples\"><li><em>Like it or not, people are often judged by their appearance.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>I’d like to think/believe (that)</strong> used to say that you wish or hope something is true, when you are not sure that it is:</div><ul class=\"examples\"><li><em>I’d like to think that we offer an excellent service.</em></li><li><em>I would like to believe that the company can be successful in the future.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[Facebook]</strong> to click a Facebook ‘like’ button on a webpage to show that you like or agree with something</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>somebody’s likes and dislikes</strong> the things that someone likes and does not like:</div><ul class=\"examples\"><li><em>We all have our own likes and dislikes when it comes to food.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>and the like/and such like</strong> and similar things:</div><ul class=\"examples\"><li><em>Soldiers, policemen, and the like were all called in to help with the emergency.</em></li><li><em>They believe that the government does not spend enough money on health, education, and such like.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the likes of somebody/something</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to talk about someone you do not like or do not approve of:</div><ul class=\"examples\"><li><em>I don’t want you spending time with the likes of him.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to talk about people of a particular type:</div><ul class=\"examples\"><li><em>Information is collected through the likes of the FBI, CIA, and Scotland Yard.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the like of somebody/something</strong> (also somebody’s/something’s like) <em>formal</em> something similar to someone or a particular person or thing, or of equal importance or value:</div><ul class=\"examples\"><li><em>This will be a show the like of which has never been seen before.</em></li><li><em>The man was a genius. We shall not see his like again.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">conjunction</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in the same way as. Some people consider this use to be incorrect:</div><ul class=\"examples\"><li><em>No one else can score goals like he can!</em></li><li><em>Don’t talk to me like you talk to a child.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>like I say/said</strong> <em>spoken</em> used when you are repeating something that you have already said:</div><ul class=\"examples\"><li><em>Like I said, I don’t mind helping out on the day.</em></li><li><em>I’m sorry, but, like I say, she’s not here at the moment.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>informal</em> as if. Some people think that this use is not correct English:</div><ul class=\"examples\"><li><em>He looked at me like I was mad.</em></li><li><em>It looks like it’s going to rain.</em></li><li><em>This meat smells like it’s gone bad.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used in speech to fill a pause while you are thinking what to say next:</div><ul class=\"examples\"><li><em>The water was, like, really cold.</em></li><li><em>I was just, like, standing there.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>I’m/he’s/she’s like...</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to tell the exact words someone used:</div><ul class=\"examples\"><li><em>I asked Dave if he wanted to go, and he’s like, no way!</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to describe an event, feeling, or person, when it is difficult to describe or when you use a noise instead of words:</div><ul class=\"examples\"><li><em>She was like, huh? (=she did not understand)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>as like as not/like enough</strong> <em>British English</em> probably:</div><ul class=\"examples\"><li><em>The ambulance will be too late, as like as not.</em></li></ul></div></div>","4069":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> like‧li‧hood</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪklihʊd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[singular, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the degree to which something can reasonably be expected to happen <em>SYN probability</em></div><ul class=\"examples\"><li><strong><em>likelihood of</strong>: Using a seatbelt will reduce the likelihood of serious injury in a car accident.</em></li><li><strong><em>little/lower/high/greater etc likelihood</strong>: There was very little likelihood of her getting the job.</em></li><li><strong><em>likelihood (that)</strong>: They must face the likelihood that the newspaper might go bankrupt.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>in all likelihood</strong> almost certainly:</div><ul class=\"examples\"><li><em>If I refused, it would in all likelihood mean I’d lose my job.</em></li></ul></div>","4070":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> like‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪkli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(comparative likelier, superlative likeliest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that is likely will probably happen or is probably true <em>OPP unlikely</em>:</div><ul class=\"examples\"><li><em>Snow showers are likely tomorrow.</em></li><li><strong><em>likely outcome/effects/consequences etc</strong>: What are the likely effects of the law going to be?</em></li><li><em>the most likely cause of the problem</em></li><li><strong><em>likely to do/be something</strong>: Children who live in the country’s rural areas are very likely to be poor.</em></li><li><strong><em>more/less/most/least likely</strong>: Young drivers are far more likely to have accidents than older drivers.</em></li><li><em>It is more than likely (=almost certain) the votes will have to be counted again.</em></li><li><em>It could have been an accident, but that was hardly likely (=not very likely).</em></li><li><em>He could offer no likely explanation when I asked him.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> suitable for a particular purpose:</div><ul class=\"examples\"><li><em>the three most likely candidates for president</em></li><li><em>One likely source of energy is wind power.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a likely story</strong> <em>spoken</em> used to tell someone you do not believe what they have just said</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> probably</div><ul class=\"examples\"><li><strong><em>most/very likely</strong>: I’d very likely have done the same thing in your situation.</em></li><li><strong><em>(as) likely as not<em>spoken</em></strong> (=very probably): As likely as not, the meeting will take place in the village pub.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>not likely!</strong> <em>spoken</em> <em>especially British English</em> used to disagree strongly, or to say that something will not happen:</div><ul class=\"examples\"><li><em>‘He said you’d be giving them a lift.’ ‘Not likely!’</em></li></ul></div></div>","4071":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> like‧wise</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪk-waɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>formal</em> in the same way <em>SYN similarly</em>:</div><ul class=\"examples\"><li><em>Nanny put on a shawl and told the girls to do likewise.</em></li><li><em><span class=\"gram\">[sentence adverb]</span>: The clams were delicious. Likewise, the eggplant was excellent.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>likewise</strong> <em>spoken</em> used to return someone’s greeting or polite statement:</div><ul class=\"examples\"><li><em>‘You’re always welcome at our house.’ ‘Likewise.’</em></li></ul></div>","4072":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɪm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>out on a limb</strong> alone and without help or support:</div><ul class=\"examples\"><li><em>All the other countries signed the agreement, leaving Britain out on a limb.</em></li><li><em>He’d gone out on a limb (=taken a risk) to help us.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an arm or leg</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>strong-limbed/long-limbed etc</strong> having strong, long etc arms and legs</div><div class=\"sense\"><span class=\"snum\">4</span> a large branch of a tree</div></div>","4073":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /laɪm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a small juicy green fruit with a sour taste, or the tree this grows on</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a tree with pleasant-smelling yellow flowers <em>SYN linden</em></div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> a white substance obtained by burning limestone, used for making cement, marking sports fields etc <em>SYN quicklime</em></div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> a light yellowish green colour</div></div>","4074":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lim‧it</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪmɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[greatest/least allowed]</strong> the greatest or least amount, number, speed etc that is allowed:</div><ul class=\"examples\"><li><em>a 55 mph speed limit</em></li><li><strong><em>limit for</strong>: There’s no age limit for applicants.</em></li><li><strong><em>limit to/on</strong>: My wife and I set a limit on how much we spend on clothes.</em></li><li><strong><em>above/over/below a limit</strong>: Pesticide levels in drinking water are already above legal limits in many areas.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[greatest amount possible]</strong> (also limits) the greatest possible amount of something that can exist or be obtained</div><ul class=\"examples\"><li><strong><em>limit of</strong>: the limits of human knowledge / He’d reached the limit of his patience.</em></li><li><em>Our finances are already stretched to the limit (=we do not have any extra money).</em></li><li><em>There’s no limit to what you can do if you try.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[place]</strong> (also limits) the furthest point or edge of a place, often one that must not be passed:</div><ul class=\"examples\"><li><em>He had not been outside the limits of the prison walls for 20 years.</em></li><li><em>The public is not allowed within a 2-mile limit of the missile site.</em></li><li><em>Los Angeles city limits</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>off limits</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> beyond the area where someone is allowed to go:</div><ul class=\"examples\"><li><em>That area of beach was off limits to us ‘city kids’.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> beyond what you are allowed to do or have:</div><ul class=\"examples\"><li><em>His private life is off limits to the press.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>within limits</strong> within the time, level, amount etc considered acceptable:</div><ul class=\"examples\"><li><em>You can come and go when you want – within limits.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be over the limit</strong> to have drunk more alcohol than is legal or safe for driving</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>know your limits</strong> <em>informal</em> to know what you are good at doing and what you are not good at:</div><ul class=\"examples\"><li><em>I know my limits. I’m not an administrator.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>have your limits</strong> <em>spoken</em> to have a set of rules about what is reasonable behaviour, and to not accept behaviour that does not follow these rules:</div><ul class=\"examples\"><li><em>I have my limits. You will not use that kind of nasty language in class.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to stop an amount or number from increasing beyond a particular point:</div><ul class=\"examples\"><li><em>a decision to limit imports of foreign cars</em></li><li><strong><em>limit something to something</strong>: Seating is limited to 500.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to stop someone from doing what they want or from developing and improving beyond a particular point:</div><ul class=\"examples\"><li><em>A lack of formal education will limit your job opportunities.</em></li><li><strong><em>limit yourself to something</strong>: I limit myself to two cups of coffee a day.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be limited to something</strong> to exist or happen only in a particular place, group, or area of activity:</div><ul class=\"examples\"><li><em>The damage was limited to the roof.</em></li></ul></div></div>","4075":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lim‧i‧ta‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌlɪmɪˈteɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the act or process of controlling or reducing something → damage limitation at damage1(3)</div><ul class=\"examples\"><li><strong><em>limitation to</strong>: Any limitation to the king’s power could be permanent.</em></li><li><em>a nuclear limitation treaty</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually plural]</span> qualities that stop someone or something from being as good or as effective as you wish they could be <em>SYN weakness</em></div><ul class=\"examples\"><li><strong><em>limitation of</strong>: Despite the limitations of the survey, it did suggest some general trends.</em></li><li><em>It’s a good little car, but it has its limitations.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> a rule or condition that stops something from increasing beyond a particular point</div><ul class=\"examples\"><li><strong><em>limitation on/upon</strong>: a limitation on the number of hours children can work</em></li><li><strong><em>put/place/impose limitations</strong>: The new law imposes limitations on campaign contributions.</em></li></ul></div>","4076":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lim‧it‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪmɪtɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not very great in amount, number, ability etc</div><ul class=\"examples\"><li><strong><em>limited number/amount/time etc</strong>: There are only a limited number of tickets available.</em></li><li><em>My knowledge of the business is limited.</em></li><li><em>The organization has very limited resources.</em></li><li><em>So far, the education reforms have had only limited success.</em></li><li><strong><em>(be of) limited use/value</strong>: Unfortunately, the drug is of limited value in treating cancer.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>Limited</strong> (written abbreviation Ltd) used after the name of British business companies that have limited liability</div></div>","4077":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /laɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[on paper/on the ground]</strong> <span class=\"gram\">[countable]</span> a long thin mark on a piece of paper, the ground, or another surface:</div><ul class=\"examples\"><li><em>Draw a straight line across the top of the page.</em></li><li><em>Sign your name on the dotted line (=line made up of a series of dots).</em></li><li><em>The edges of the pitch are marked by white lines.</em></li><li><em>The goalkeeper just managed to stop the ball going over the line.</em></li><li><em>He raced towards the finishing line.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[between two areas]</strong> <span class=\"gram\">[countable]</span> an imaginary line on the surface of the Earth, for example showing where one country or area of land stops and another begins ► see thesaurus at border → International Date Line</div><ul class=\"examples\"><li><strong><em>county/state line<em>American English</em></strong>: He was born in a small town just across the state line.</em></li><li><strong><em>line of latitude/longitude</strong>: They were still travelling along the same line of longitude.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[of people/things]</strong> <span class=\"gram\">[countable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a row of people or things next to each other</div><ul class=\"examples\"><li><strong><em>line of</strong>: There was a line of fir trees on either side of the road.</em></li><li><em>The four men were standing in a line on the other side of the table.</em></li><li><em>A couple of the posts were out of line (=not in a straight row).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>especially American English</em> a row of people, cars etc that are waiting one behind the other SYN queue<em>British English</em>:</div><ul class=\"examples\"><li><em>I looked in despair at the long line in front of the ticket office.</em></li><li><strong><em>line of</strong>: I joined the line of vehicles waiting to get into the car park.</em></li><li><strong><em>stand/wait in line</strong>: Customers stood in line for 20 minutes at the cash register.</em></li><li><em>He tried to cut in line (=go in front of other people who are waiting).</em></li><li><em>The woman next in line began to mutter to herself.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[direction]</strong> <span class=\"gram\">[countable]</span> the direction or imaginary line along which something travels between two places:</div><ul class=\"examples\"><li><em>Light travels in a straight line.</em></li><li><em>A boat came into my line of vision (=the direction I was looking in).</em></li><li><strong><em>line of fire/attack/movement etc</strong> (=the direction in which someone shoots, attacks, moves etc): I was directly in the animal’s line of attack.</em></li><li><em>They knew they needed to block their enemy’s supply lines (=the direction used for carrying supplies of food etc).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[on your face]</strong> <span class=\"gram\">[countable]</span> a line on the skin of someone’s face → wrinkle:</div><ul class=\"examples\"><li><em>She frowned, and deep lines appeared between her eyebrows.</em></li><li><em>There were fine lines around her eyes.</em></li><li><em>No one can avoid lines and wrinkles as they get older.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[phone]</strong> <span class=\"gram\">[countable]</span> a telephone wire or connection:</div><ul class=\"examples\"><li><em>I’m sorry, the line is busy (=someone is already using it).</em></li><li><em>There seems to be a fault on the line.</em></li><li><em>There was a click, then the line went dead (=suddenly stopped working completely).</em></li><li><em>Henry is on the line (=on the phone) from New York.</em></li><li><em>I got on the line to (=phoned) the hospital as soon as I heard about the accident.</em></li><li><em>I wished he would just get off the line.</em></li><li><em>I’m sorry, it’s a bad line and I can’t hear you.</em></li><li><em>Hold the line (=wait on the phone), please, and I’ll put you through to our sales department.</em></li><li><em>Do you have a separate line for your modem?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[for trains]</strong> <span class=\"gram\">[countable]</span> a track that a train travels along:</div><ul class=\"examples\"><li><em>We were delayed because of a problem further along the line.</em></li><li><em>When you get to central London, take the Victoria Line to Finsbury Park.</em></li><li><strong><em>railway line<em>British English,</em></strong> <strong>railroad line</em>American English</strong><em>: The trail follows a disused railroad line along the edge of the valley.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[between two types of thing]</strong> <span class=\"gram\">[countable usually singular]</span> the point at which one type of thing can be considered to be something else or at which it becomes a particular thing</div><ul class=\"examples\"><li><strong><em>line between</strong>: There is a fine line between superstition and religion. / The dividing line between luxuries and necessities is constantly changing. / Sometimes he found it hard to draw the line between work and pleasure. / Her remarks did not quite cross the line into rudeness. / Large numbers of families are living on or near the poverty line (=the point at which people are considered to be very poor).</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[shape/edge]</strong> <span class=\"gram\">[countable usually plural]</span> the outer shape of something long or tall:</div><ul class=\"examples\"><li><em>She was wearing a loose dress which softened the lines of her body.</em></li><li><em>a modern building with clean, elegant lines.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[words]</strong> <span class=\"gram\">[countable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a line of written words, for example in a poem or a document:</div><ul class=\"examples\"><li><em>He quoted a few lines from Shakespeare.</em></li><li><em>Scroll down to line 29.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a remark:</div><ul class=\"examples\"><li><em>He liked to introduce himself with a witty opening line.</em></li><li><em>This was one of his favourite chat-up lines (=remark for impressing someone you want to attract).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <span class=\"gram\">[usually plural]</span> words that someone has to learn and say as part of a play or performance:</div><ul class=\"examples\"><li><em>Paul often messed up his lines.</em></li><li><em>It always took me ages to learn my lines.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[opinion/attitude]</strong> <span class=\"gram\">[singular]</span> an opinion or attitude, especially one that someone states publicly and that influences their actions → toe the line at toe2</div><ul class=\"examples\"><li><strong><em>line on</strong>: I can’t agree with the government’s line on immigration.</em></li><li><em>Journalists are often too willing to accept the official line (=the opinion that a government states officially).</em></li><li><em>He found it hard to accept the party line (=the official opinion of a political party) on every issue.</em></li><li><strong><em>take a tough/firm/hard line on something</strong>: The school takes a very tough line on drugs.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[way of doing something]</strong> <span class=\"gram\">[countable]</span> a particular way of doing something or of thinking about something</div><ul class=\"examples\"><li><strong><em>line of argument/reasoning/inquiry etc</strong>: It seemed useless to pursue this line of questioning. / Opposition parties soon realized they would have to try a different line of attack.</em></li><li><em>The police are following several different lines of enquiry.</em></li><li><em>We were both thinking along the same lines (=in the same way).</em></li><li><em>In South Africa, the press developed along very different lines (=in a very different way).</em></li><li><em>More groups will now be set up on these lines (=this way).</em></li><li><em>The company’s rapid success means it’s definitely on the right lines (=doing something the right way).</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[series of events]</strong> <span class=\"gram\">[countable usually singular]</span> a series of events that follow each other</div><ul class=\"examples\"><li><strong><em>line of</strong>: This is the latest in a long line of political scandals.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[in a war]</strong> <span class=\"gram\">[countable]</span> the edge of an area that is controlled by an army, where soldiers stay and try to prevent their enemy from moving forward:</div><ul class=\"examples\"><li><em>They finally broke through the German line.</em></li><li><em>young soldiers who were sent to the front line to fight</em></li><li><em>One regiment was trapped behind enemy lines.</em></li><li><em>Reinforcements were available just behind the lines.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[in a company/organization]</strong> <span class=\"gram\">[countable]</span> a series of levels of authority within an organization: → line manager</div><ul class=\"examples\"><li><em>Decisions are taken by senior officers and fed down through the line of command to the ordinary soldiers.</em></li><li><em>There should be more direct discussion between managers and workers lower down the line.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[of rope/wire]</strong> <span class=\"gram\">[countable]</span> a piece of strong string, rope, or wire used for a particular purpose:</div><ul class=\"examples\"><li><em>She hung the clothes out on the washing line (=line for hanging wet clothes on to dry).</em></li><li><em>The fishing line (=line for catching fish) snapped and the fish got away.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>[product]</strong> <span class=\"gram\">[countable]</span> a type of goods for sale in a shop:</div><ul class=\"examples\"><li><em>The company has just launched a new line of small, low-priced computers.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>along these/those lines</strong> (also along the lines of something) similar to something else:</div><ul class=\"examples\"><li><em>We usually start with general questions along the lines of, ‘How do you feel?’</em></li><li><em>They’re trying to organize a trip to the beach or something along those lines.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>along religious/ethnic/party etc lines</strong> if people divide along religious, party etc lines, they divide according to the religion, political party, or other group they belong to:</div><ul class=\"examples\"><li><em>The committee was split along party lines.</em></li><li><em>The community remains divided along religious lines.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>on line</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> using a computer to get information or to communicate with people: → online</div><ul class=\"examples\"><li><em>You can book tickets on line.</em></li><li><em>Most of our sales staff now work on line.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> working properly as planned:</div><ul class=\"examples\"><li><em>a new nuclear reactor which should be on line by 2005</em></li><li><em>If there is a power failure, the emergency generators should come on line within 15 minutes.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>drop somebody a line</strong> <em>informal</em> to write a short letter or email to someone:</div><ul class=\"examples\"><li><em>Drop me a line and let me know how you’re getting on.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>don’t give me that line</strong> <em>spoken</em> used to say that you do not believe someone’s excuse:</div><ul class=\"examples\"><li><em>I know for a fact you weren’t sick yesterday, so don’t give me that line.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>fall into line/bring somebody into line</strong> <em>informal</em> to start to do what someone else wants you to do, or to make someone do this:</div><ul class=\"examples\"><li><em>Now that France and Germany have signed up, other countries will soon fall into line.</em></li><li><em>The few party rebels were soon brought into line.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>in line with something</strong> if something changes in line with something else, it changes in the same way and at the same rate as it:</div><ul class=\"examples\"><li><em>Pensions will be increased in line with inflation.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>bring something into line with something</strong> to change a system so that it works according to a particular set of rules, laws etc:</div><ul class=\"examples\"><li><em>UK immigration procedures will have to be changed to bring them into line with the latest European ruling.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>be out of line</strong> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to say or do something that is not acceptable in a particular situation:</div><ul class=\"examples\"><li><em>You just keep quiet! You’re way out of line.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to not obey someone, or to do something that you should not do</div><ul class=\"examples\"><li><strong><em>get/step out of line</strong>: Anybody who steps out of line will be in deep trouble.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>be in line for something/be in line to do something</strong> to be very likely to get or be given something:</div><ul class=\"examples\"><li><em>I should be in line for promotion soon.</em></li><li><strong><em>first/second/next etc in line for</strong>: He must be first in line for the editor’s job.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>be first/second/next etc in line to the throne</strong> to be the person who has a right to become a future king or queen:</div><ul class=\"examples\"><li><em>As the eldest son, he was next in line to the throne.</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>be on the line</strong> if something important is on the line, there is a risk that you might lose it or something bad could happen to it:</div><ul class=\"examples\"><li><em>From now on, all our jobs are on the line.</em></li><li><em>She knew that her whole future was on the line.</em></li><li><strong><em>put yourself/your neck on the line (for somebody)</strong> (=risk something bad happening to you): I’ve already put myself on the line for you once, and I’m not going to do it again.</em></li></ul><div class=\"sense\"><span class=\"snum\">30</span> <strong>be in somebody’s line</strong> <em>informal</em> to be the type of thing that someone is interested in or good at:</div><ul class=\"examples\"><li><em>Acting’s not really in my line, I’m afraid.</em></li></ul><div class=\"sense\"><span class=\"snum\">31</span> <strong>get a line on somebody/something</strong> <em>especially American English</em> <em>informal</em> to get information about someone or something:</div><ul class=\"examples\"><li><em>We need to get some kind of a line on these guys.</em></li></ul><div class=\"sense\"><span class=\"snum\">32</span> <strong>somewhere along the line</strong> <em>informal</em> at some time during an activity or period of time:</div><ul class=\"examples\"><li><em>Somewhere along the line, Errol seemed to have lost interest in her.</em></li></ul><div class=\"sense\"><span class=\"snum\">33</span> <strong>down the line</strong> <em>informal</em> later, after an activity or situation has been continuing for a period of time:</div><ul class=\"examples\"><li><em>There may be more costs further down the line.</em></li><li><em>Now, three years down the line, we’re beginning to see the problems with the treatment.</em></li></ul><div class=\"sense\"><span class=\"snum\">34</span> <strong>in the line of duty</strong> happening or done as part of your job:</div><ul class=\"examples\"><li><em>firefighters dying in the line of duty</em></li></ul><div class=\"sense\"><span class=\"snum\">35</span> <strong>be in the firing line/in the line of fire</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be one of the people who could be criticized or blamed for something:</div><ul class=\"examples\"><li><em>As one of the president’s chief advisers, he’s bound to be in the firing line.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to be in a place where a bullet etc might hit you:</div><ul class=\"examples\"><li><em>A couple of civilians were caught in the firing line.</em></li></ul><div class=\"sense\"><span class=\"snum\">36</span> <strong>[punishment]</strong> <strong>lines</strong> <span class=\"gram\">[plural]</span> <em>British English</em> a punishment given to school children that consists of writing the same thing a lot of times:</div><ul class=\"examples\"><li><em>He got 50 lines for being cheeky to a teacher.</em></li></ul><div class=\"sense\"><span class=\"snum\">37</span> <strong>[family]</strong> <span class=\"gram\">[singular]</span> your family, considered as the people you are related to who lived before you and the people who will live after you:</div><ul class=\"examples\"><li><em>She comes from a long line of actors.</em></li><li><em>It looks as if Joe might be the last of the line (=the last in his family).</em></li><li><strong><em>the male/female line</strong>: This particular gene is passed down through the male line.</em></li><li><strong><em>line of succession</strong> (=the system by which an important position or property is passed from a parent to their children, and then to their children etc): Henry the Eighth wanted a male heir to ensure the Tudor line of succession.</em></li></ul><div class=\"sense\"><span class=\"snum\">38</span> <strong>[job]</strong> <span class=\"gram\">[countable usually singular]</span> the type of work someone does</div><ul class=\"examples\"><li><strong><em>line of work/business</strong>: What line of business is he in?</em></li><li><strong><em>in the building/retail etc line</strong>: She’s keen to do something in the fashion line.</em></li></ul><div class=\"sense\"><span class=\"snum\">39</span> <strong>[transport]</strong> <span class=\"gram\">[countable]</span> a company that provides transport for moving goods by sea, air, road etc:</div><ul class=\"examples\"><li><em>He runs a transatlantic shipping line.</em></li></ul><div class=\"sense\"><span class=\"snum\">40</span> <strong>[drug]</strong> <span class=\"gram\">[countable]</span> <em>informal</em> an amount of an illegal drug in powder form, arranged in a line so it can be breathed in through the nose</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to sew a piece of material onto the inside or back of another piece to make it stronger or warmer:</div><ul class=\"examples\"><li><em>Are those curtains lined?</em></li><li><strong><em>line something with something</strong>: a leather coat lined with silk</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to form a layer over the inner surface of something:</div><ul class=\"examples\"><li><em>The birds use small leaves for lining their nests.</em></li><li><strong><em>line something with something</strong>: The cage should be lined with straw.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to form rows along the sides of something:</div><ul class=\"examples\"><li><em>Crowds lined the route to the palace.</em></li><li><strong><em>be lined with something</strong>: The street was lined with small shops.</em></li><li><em>a tree-lined avenue</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>line your own pockets</strong> to make yourself richer, especially by doing something dishonest – used to show disapproval</div></div></div>","4078":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lin‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪnɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> sheets, tablecloths etc:</div><ul class=\"examples\"><li><em>bed linen</em></li><li><em>table linen</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> cloth made from the flax plant, used to make high quality clothes, home decorations etc:</div><ul class=\"examples\"><li><em>a linen jacket</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>old use</em> underwear</div></div>","4079":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lin‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪnə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a piece of material used inside something, especially in order to keep it clean:</div><ul class=\"examples\"><li><em>a dustbin liner</em></li><li><em>nappy liners</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a large ship for passengers: → cruise liner</div><ul class=\"examples\"><li><em>an ocean liner</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> <em>informal</em> eyeliner</div></div>","4080":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lin‧ger</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪŋɡə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (also linger on) to continue to exist, be noticeable etc for longer than is usual or desirable:</div><ul class=\"examples\"><li><em>a taste that lingers in your mouth</em></li><li><em>Unfortunately the tax will linger on until April.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also linger on) to stay somewhere a little longer, especially because you do not want to leave ► see thesaurus at stay</div><ul class=\"examples\"><li><strong><em>linger over</strong>: They lingered over coffee and missed the last bus.</em></li><li><em>I spent a week at Kandersteg and could happily have lingered on.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[always + adverb/preposition]</span> to continue looking at or dealing with something for longer than is usual or desirable</div><ul class=\"examples\"><li><strong><em>linger on/over</strong>: Mike let his eyes linger on her face.</em></li><li><em>There’s no need to linger over this stage of the interview.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> (also linger on) to continue to live although you are slowly dying:</div><ul class=\"examples\"><li><em>He surprised all the doctors by lingering on for several weeks.</em></li></ul></div>","4081":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lin‧guist</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪŋɡwɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is good at foreign languages, especially someone who speaks several</div><div class=\"sense\"><span class=\"snum\">2</span> someone who studies or teaches linguistics</div></div>","4082":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lin‧guis‧tic</span><span class=\"meta-item\"><strong>IPA:</strong> /lɪŋˈɡwɪstɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">related to language, words, or linguistics:</div><ul class=\"examples\"><li><em>a child’s linguistic development</em></li></ul></div>","4083":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lin‧guis‧tics</span><span class=\"meta-item\"><strong>IPA:</strong> /lɪŋˈɡwɪstɪks/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the study of language in general and of particular languages, their structure, grammar, and history</div></div>","4084":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lin‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪnɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a piece of material that covers the inside of something, especially a piece of clothing → lined: → every cloud has a silver lining at cloud1(6)</div><ul class=\"examples\"><li><em>a jacket with a silk lining</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a substance or material that covers the inside of part of the body:</div><ul class=\"examples\"><li><em>the lining of the womb</em></li></ul></div>","4085":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɪŋk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>be linked</strong> if two things are linked, they are related in some way:</div><ul class=\"examples\"><li><em>Police think the murders are linked.</em></li><li><strong><em>be linked to/with something</strong>: Some birth defects are linked to smoking during pregnancy.</em></li><li><strong><em>be closely/directly/strongly etc linked</strong>: Our economy is inextricably linked with America’s.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[make connection]</strong> <span class=\"gram\">[transitive]</span> to make a connection between two or more things or people:</div><ul class=\"examples\"><li><em>A love of nature links the two poets.</em></li><li><strong><em>link something/somebody to/with something</strong>: Exactly how do we link words to objects?</em></li><li><strong><em>link somebody/something together</strong>: Strong family ties still linked them together.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[join]</strong> <span class=\"gram\">[transitive]</span> to physically join two or more things, people, or places <em>SYN connect</em></div><ul class=\"examples\"><li><strong><em>link something/somebody to/with something</strong>: The pipe must be linked to the cold water supply.</em></li><li><strong><em>link somebody/something together</strong>: The climbers were linked together by ropes.</em></li><li><strong><em>link something and something</strong>: A long bridge links Venice and the mainland.</em></li><li><em>He walked with her, linking arms (=putting his arm around her arm).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[show connection]</strong> <span class=\"gram\">[transitive]</span> to show or say that there is a connection between two people, situations, or things</div><ul class=\"examples\"><li><strong><em>link something/somebody to/with something</strong>: He denied reports linking him to Colombian drug dealers.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[make something depend on something]</strong> <span class=\"gram\">[transitive]</span> to make one thing or situation depend on another thing or situation → index-linked</div><ul class=\"examples\"><li><strong><em>link something to something</strong>: Pay increases will now be linked to performance.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[connect equipment]</strong> <span class=\"gram\">[transitive]</span> (also link up) to connect computers, broadcast systems etc, so that electronic messages can be sent between them</div><ul class=\"examples\"><li><strong><em>link something to/with something</strong>: Local terminals are linked to the central computer.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[Internet]</strong> <span class=\"gram\">[intransitive]</span> to set up a link to a website or webpage:</div><ul class=\"examples\"><li><em>How can I find out who has linked to my blog?</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a way in which two things or ideas are related to each other</div><ul class=\"examples\"><li><strong><em>link between something (and something)</strong>: the link between drug use and crime / There are a number of links between the two theories.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a relationship or connection between two or more people, countries, organizations etc</div><ul class=\"examples\"><li><strong><em>link between</strong>: the close link between teacher and student</em></li><li><strong><em>link with</strong>: The company has strong links with big investors.</em></li><li><strong><em>forge/establish links</strong>: Organizers of the project hope that international links will be forged.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a person or thing that makes possible a relationship or connection with someone or something else</div><ul class=\"examples\"><li><strong><em>link with</strong>: For elderly people, TV is a vital link with the outside world.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>rail/road/telephone etc link</strong> something that makes communication or travel between two places possible:</div><ul class=\"examples\"><li><em>The office has direct computer links to over 100 firms.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> one of the rings in a chain</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>link in the chain</strong> one of the stages involved in a process</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>the links</strong> a piece of ground near the sea where golf is played <em>SYN golf links</em></div><div class=\"sense\"><span class=\"snum\">8</span> a special word or picture in an Internet document that you click on to move quickly to another part of the same document or to another document → hyperlink:</div><ul class=\"examples\"><li><em>Send an email to the above address to report a broken link (=a link that is not working properly).</em></li></ul></div></div>","4086":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> li‧on</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a large animal of the cat family that lives in Africa and parts of southern Asia. Lions have gold-coloured fur and the male has a mane (=long hair around its neck). → lioness</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>the lion’s share (of something)</strong> the largest part of something:</div><ul class=\"examples\"><li><em>The firm has captured the lion’s share of the UK market.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the lion’s den</strong> if you go into the lion’s den, you go among people who are your enemies</div></div>","4087":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɪp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> one of the two soft parts around your mouth where your skin is redder or darker → tight-lipped</div><ul class=\"examples\"><li><strong><em>upper/lower/top/bottom lip</strong>: His bottom lip was swollen.</em></li><li><em>She had big eyes and full lips (=large and round lips).</em></li><li><em>Matt opened the door with a smile on his lips.</em></li><li><em>Marty kissed me right on the lips!</em></li><li><strong><em>thin-lipped/thick-lipped/full-lipped</strong> (=having lips that are thin, or large and round)</em></li><li><em>Stephen pursed his lips with distaste (=brought them together tightly into a small circle).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> the edge of a hollow or deep place in the land</div><ul class=\"examples\"><li><strong><em>lip of</strong>: the old road that ran along the lip of the gorge</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable usually singular]</span> the edge of something you use to hold or pour liquid <em>SYN rim</em></div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> <em>informal</em> talk that is not polite or respectful – used especially by adults to children <em>SYN cheek</em>:</div><ul class=\"examples\"><li><em>Don’t give me any of your lip!</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>my lips are sealed</strong> <em>spoken</em> used to say that you will not tell anyone about a secret</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>on everyone’s lips</strong> being talked about by everyone:</div><ul class=\"examples\"><li><em>an actress whose name is on everyone’s lips</em></li></ul></div>","4088":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lip‧stick</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪpˌstɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[countable, uncountable]</span> something used for adding colour to your lips, in the shape of a small stick</div></div>","4089":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> liq‧uid</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪkwɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[countable, uncountable]</span> a substance that is not a solid or a gas, for example water or milk:</div><ul class=\"examples\"><li><em>Add a little more liquid to the sauce.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in the form of a liquid instead of a gas or solid:</div><ul class=\"examples\"><li><em>Children take antibiotics in liquid form.</em></li><li><em>liquid soap</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> easily changed into money by being sold or exchanged: → liquid assets</div><ul class=\"examples\"><li><em>Their shares are more liquid than those of many smaller companies.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>liquid refreshment</strong> drink, especially alcoholic drink – used humorously</div><div class=\"sense\"><span class=\"snum\">4</span> <em>literary</em> clear and shiny, like water:</div><ul class=\"examples\"><li><em>liquid green eyes</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>literary</em> liquid sounds are clear and pure</div></div></div>","4090":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> liq‧uor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪkə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>especially American English</em> a strong alcoholic drink such as whisky <em>SYN spirit</em> → liqueur</div><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> <em>technical</em> any alcoholic drink</div></div>","4091":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a set of names, numbers etc, usually written one below the other, for example so that you can remember or check them</div><ul class=\"examples\"><li><strong><em>list of</strong>: Make a list of all the things you have to do.</em></li><li><strong><em>on/in a list</strong>: The first person on my list is Mrs Gilling.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be high/low on a list (of something)</strong> (also be at the top/bottom of a list) to be considered very important or not very important:</div><ul class=\"examples\"><li><em>A good car is high on my list of priorities.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to write a list, or mention things one after the other:</div><ul class=\"examples\"><li><em>The guidebook lists 1,000 hotels and restaurants.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to put someone on an official list, especially a hospital or court list</div><ul class=\"examples\"><li><strong><em>list somebody in fair/stable etc condition</strong>: Several passengers were listed in critical condition.</em></li><li><em>The case was listed for trial in the Crown Court.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> if a ship lists, it leans to one side</div></div></div>","4092":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lis‧ten</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪsən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to pay attention to what someone is saying or to a sound that you can hear: ► see thesaurus at hear</div><ul class=\"examples\"><li><em>Listen! There’s a strange noise in the engine.</em></li><li><strong><em>listen to</strong>: We sat around listening to music.</em></li><li><strong><em>listen carefully/intently/hard etc</strong>: The whole class was listening attentively. / Liz stood still and listened hard (=very carefully).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>spoken</em> used to tell someone to pay attention to what you are going to say:</div><ul class=\"examples\"><li><em>Listen, I want you to come with me.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to consider what someone says and accept their advice:</div><ul class=\"examples\"><li><em>I told him not to go, but he just wouldn’t listen.</em></li><li><strong><em>listen to</strong>: I wish I’d listened to Dad. / She refused to listen to reason (=accept sensible advice).</em></li></ul></div>","4093":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lis‧ten‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪsənə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who listens to the radio → viewer:</div><ul class=\"examples\"><li><em>a new programme for younger listeners</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a good/sympathetic listener</strong> someone who listens carefully and sympathetically to other people</div></div>","4094":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> list‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪstɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> an official or public list</div><ul class=\"examples\"><li><strong><em>listing of</strong>: a listing of all households in the district</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>listings</strong> <span class=\"gram\">[plural]</span> lists of films, plays, and other events, with the times and places at which they will happen</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> if a company has a listing on the stock exchange, it can offer its shares for sale</div></div>","4095":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lit‧e‧ra‧cy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪtərəsi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the state of being able to read and write <em>OPP illiteracy</em> → numeracy: → computer-literate</div><ul class=\"examples\"><li><em>a new adult literacy campaign</em></li></ul></div>","4096":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lit‧e‧ral</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪtərəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the literal meaning of a word or expression is its basic or original meaning → figurative</div><ul class=\"examples\"><li><strong><em>literal meaning/sense/interpretation etc</strong>: A trade war is not a war in the literal sense.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>literal translation</strong> a translation that translates each word exactly instead of giving the general meaning in a more natural way <em>OPP free</em></div><div class=\"sense\"><span class=\"snum\">3</span> <strong>literal-minded</strong> not showing much imagination</div></div>","4097":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lit‧e‧ral‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪtərəli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> according to the most basic or original meaning of a word or expression:</div><ul class=\"examples\"><li><em>The name of the cheese is Dolcelatte, literally meaning ‘sweet milk’.</em></li><li><em>I said I felt like quitting, but I didn’t mean it literally (=I did not mean exactly what I said)!</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>take somebody/something literally</strong> to believe exactly what someone or something says rather than trying to understand their general meaning:</div><ul class=\"examples\"><li><em>She takes the Bible literally.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to emphasize that something, especially a large number, is actually true:</div><ul class=\"examples\"><li><em>The Olympic Games were watched by literally billions of people.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>spoken</em> used to emphasize a strong expression or word that is not being used in its real or original meaning. Some people consider this use to be incorrect:</div><ul class=\"examples\"><li><em>Dad was literally blazing with anger.</em></li></ul></div>","4098":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lit‧e‧ra‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪtərəri $ ˈlɪtəreri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to literature:</div><ul class=\"examples\"><li><em>a literary prize</em></li><li><em>literary criticism (=the study of the methods used in writing literature)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> typical of the style of writing used in literature rather than in ordinary writing and talking:</div><ul class=\"examples\"><li><em>a literary style of writing</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> liking literature very much, and studying or producing it:</div><ul class=\"examples\"><li><em>a literary woman</em></li></ul></div>","4099":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lit‧e‧ra‧ture</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪtərətʃə $ -tʃʊr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> books, plays, poems etc that people think are important and good: ► see thesaurus at book</div><ul class=\"examples\"><li><em>He has read many of the major works of literature.</em></li><li><em>Italian literature</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> all the books, articles etc on a particular subject</div><ul class=\"examples\"><li><strong><em>literature on</strong>: literature on the history of science</em></li><li><strong><em>in the literature</strong>: Several cases of mercury poisoning have been recorded in the literature.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> printed information produced by people who want to sell you something or tell you about something:</div><ul class=\"examples\"><li><em>sales literature</em></li></ul></div>","4100":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> li‧tre</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈliːtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> (written abbreviation l) the basic unit for measuring liquid in the metric system</div><ul class=\"examples\"><li><strong><em>litre of</strong>: a litre of water</em></li><li><strong><em>litre bottle/drum/container etc</strong>: a litre bottle of wine</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>2.6/3.5 etc litre engine</strong> a measurement that shows the size and power of a vehicle’s engine → cc:</div><ul class=\"examples\"><li><em>the Ford’s 2.8 litre engine</em></li></ul></div>","4101":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lit‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[waste]</strong> <span class=\"gram\">[uncountable]</span> waste paper, cans etc that people have thrown away and left on the ground in a public place <em>SYN rubbish</em> <em>, trash</em> <em>, garbage</em>: GRAMMAR: Countable or uncountable?• Litter is an uncountable noun and is not used in the plural. You say: · The ground is covered in litter. ✗Don’t say: The ground is covered in litters.• Litter is always followed by a singular verb: · Litter was left all over the field.• When talking about one piece of paper, can etc, you say a piece of litter: · I didn’t see a single piece of litter.</div><ul class=\"examples\"><li><em>People who drop litter can be fined in some cities.</em></li><li><em>a town with a litter problem</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[baby animals]</strong> <span class=\"gram\">[countable]</span> a group of baby animals that a mother gives birth to at the same time ► see thesaurus at baby, group</div><ul class=\"examples\"><li><strong><em>litter of</strong>: a litter of kittens</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[for cat’s toilet]</strong> <span class=\"gram\">[uncountable]</span> small grains of a dry substance that is put in a container that a cat uses as a toilet indoors:</div><ul class=\"examples\"><li><em>cat litter</em></li><li><em>a litter tray</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[forest]</strong> <span class=\"gram\">[uncountable]</span> (also leaf litter) dead leaves and other decaying plants on the ground in a forest</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>a litter of something</strong> <em>literary</em> a group of things that look very untidy:</div><ul class=\"examples\"><li><em>A litter of notes, papers, and textbooks were strewn on the desk.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[for animal’s bed]</strong> <span class=\"gram\">[uncountable]</span> a substance such as straw that a farm animal sleeps on</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[bed]</strong> <span class=\"gram\">[countable]</span> a chair or bed for carrying important people, used in past times</div></div>","4102":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lit‧tle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪtl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[size]</strong> <span class=\"gram\">[usually before noun]</span> small in size: ► see thesaurus at small</div><ul class=\"examples\"><li><em>a little house</em></li><li><em>a cake decorated with little flowers</em></li><li><em>She was cutting the meat up into little bits.</em></li><li><strong><em>little tiny/tiny little<em>spoken</em></strong> (=extremely small): a little tiny puppy</em></li><li><strong><em>little bitty<em>American English</em></strong> </em>spoken<em> (=extremely small)</em></li><li><strong><em>a little something<em>informal</em></strong> (=a small present, or a small amount of food): I’d like to buy him a little something to thank him.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[something you like or dislike]</strong> <span class=\"gram\">[only before noun]</span> used between an adjective and a noun to emphasize that you like or dislike something or someone, although they are not important, impressive etc:</div><ul class=\"examples\"><li><em>It could be a nice little business.</em></li><li><em>a useful little gadget</em></li><li><em>It was another of her silly little jokes.</em></li><li><em>a boring little man</em></li><li><strong><em>poor little thing</strong> (=used to show sympathy): The poor little thing had hurt its wing.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a little bit</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a small amount of something</div><ul class=\"examples\"><li><strong><em>little of</strong>: With a little bit of luck we should finish by five o’clock. / I’m going to give you a little bit of advice.</em></li><li><em>Let me tell you a little bit about myself.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> slightly or to a small degree:</div><ul class=\"examples\"><li><em>I was a little bit disappointed.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[time/distance]</strong> <span class=\"gram\">[only before noun]</span> short in time or distance:</div><ul class=\"examples\"><li><em>You could have a little sleep in the car.</em></li><li><em>We walked a little way along this path.</em></li><li><em>He arrived a little while ago.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[young]</strong> little children are young: ► see thesaurus at young</div><ul class=\"examples\"><li><em>We didn’t have toys like this when I was little.</em></li><li><strong><em>little boy/girl</strong>: two little boys playing in the street</em></li><li><strong><em>somebody’s little boy/girl</strong> (=someone’s son or daughter who is still a child): Mum, I’m 17 – I’m not your little girl any longer.</em></li><li><strong><em>somebody’s little brother/sister</strong> (=a younger brother or sister who is still a child): Her little brother and sister were fighting again.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[slight]</strong> <span class=\"gram\">[only before noun]</span> done in a way that is not very noticeable:</div><ul class=\"examples\"><li><em>a little smile</em></li><li><em>Nicolo gave a little nod of his head.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[unimportant]</strong> <span class=\"gram\">[only before noun]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> not important:</div><ul class=\"examples\"><li><em>She gets very angry over little things.</em></li><li><em>There isn’t time to discuss every little detail.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> not important – used when you really think that something is important:</div><ul class=\"examples\"><li><em>There’s just that little matter of the £5,000 you owe me.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>(just) that little bit better/easier etc</strong> better, easier etc by a small amount that will have an important effect:</div><ul class=\"examples\"><li><em>Working fewer hours will make life just that little bit easier for me.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>the little woman</strong> <em>old-fashioned</em> someone’s wife – often used humorously but now considered offensive by many women</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">determiner</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> only a small amount or hardly any of something:</div><ul class=\"examples\"><li><em>There’s little doubt in my mind that he’s guilty.</em></li><li><em>I paid little attention to what the others were saying.</em></li><li><em>Little is known about the causes of the problem.</em></li><li><em>Changes in the law have done little to improve the situation.</em></li><li><strong><em>little of</strong>: Little of their wealth now remains.</em></li><li><em>There’s very little money left.</em></li><li><em>Many of the students speak little or no English.</em></li><li><em>He knew little or nothing (=almost nothing) about fixing cars.</em></li><li><em>My lawyer advised me to say as little as possible.</em></li><li><em>He did precious little (=very little) to help.</em></li><li><em>The laboratory tests are of little real value.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a little</strong> a small amount:</div><ul class=\"examples\"><li><em>Fortunately I had a little time to spare.</em></li><li><em>Susan speaks a little French.</em></li><li><em>A little over half the class can swim.</em></li><li><em>He walked on a little (=a short distance) and then turned back.</em></li><li><strong><em>a little more/less</strong>: Would you like a little more milk in your coffee?</em></li><li><strong><em>little of</strong>: The city is regaining a little of its former splendour.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>as little as £5/3 months/10 feet etc</strong> used to emphasize how surprisingly small an amount is:</div><ul class=\"examples\"><li><em>Prices for his paintings start from as little as £100.</em></li><li><em>The weather can change completely in as little as half an hour.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>what little</strong> (also the little (that)) used to emphasize how small an amount there is, how small an amount is possible etc:</div><ul class=\"examples\"><li><em>We did what little we could to help.</em></li><li><em>I handed over what little money I had left.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>a little (of something) goes a long way</strong> <em>spoken</em> used to say that only a small amount of something is needed or has a great effect:</div><ul class=\"examples\"><li><em>A little kindness goes a long way.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>a little</strong> slightly or to a small degree <em>SYN a bit</em>:</div><ul class=\"examples\"><li><em>She trembled a little as she spoke.</em></li><li><em>He was a little surprised at her request.</em></li><li><strong><em>a little more/better/further etc</strong>: We’ll have to wait a little longer to see what happens.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not much or only slightly:</div><ul class=\"examples\"><li><em>The town has changed little over the years.</em></li><li><em>The situation has improved very little.</em></li><li><strong><em>little known/understood etc</strong> (=not known about by many people): a little known corner of the world</em></li><li><strong><em>little more/better etc (than something)</strong>: His voice was little more than a whisper.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>little did somebody know/realize/think etc</strong> used to say that someone did not know or think that something would happen or was true:</div><ul class=\"examples\"><li><em>Little did I know that the course of my life was about to change.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>little by little</strong> gradually:</div><ul class=\"examples\"><li><em>Little by little he became accepted by the family.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>more than a little/not a little</strong> <em>literary</em> extremely:</div><ul class=\"examples\"><li><em>Graham was more than a little frightened by what he had seen.</em></li></ul></div></div>","4103":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[in a place/home]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if you live in a place, you have your home there</div><ul class=\"examples\"><li><strong><em>live in/at/near etc</strong>: They lived in Holland for ten years. / He lives just across the street from me. / We live only a few miles from the coast.</em></li><li><em>A rather odd family came to live next door to us.</em></li><li><em>As soon as I saw the place, I knew I didn’t want to live there.</em></li><li><em>Does Paul still live here?</em></li><li><em>We’re still looking for somewhere to live.</em></li><li><em>They’ve finally found a place to live.</em></li><li><strong><em>live with</strong>: My grandmother came to live with us when I was ten.</em></li><li><em>Most seventeen-year-olds still live at home (=live with their parents).</em></li><li><em>I’m quite happy living alone.</em></li><li><em>The house has 3,600 square feet of living space (=the areas of a house you live in).</em></li><li><strong><em>live rough<em>British English</em></strong> (=live outside because of having no home): I ran away from home and lived rough for nine months.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[plant/animal]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> a plant or animal that lives in a particular place grows there or has its home there</div><ul class=\"examples\"><li><strong><em>live in/on etc</strong>: These particular birds live on only one island in the Pacific.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[at a particular time]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if you live at a particular time, you are alive then</div><ul class=\"examples\"><li><strong><em>live before/in/at</strong>: He lived in the eighteenth century. / She lived at a time when women were not expected to work. / Gladstone lived during a period of great social change.</em></li><li><strong><em>the best/greatest etc that/who ever lived</strong> (=the best, greatest etc who has been alive at any time): He’s probably the best journalist who ever lived.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[be/stay alive]</strong> <span class=\"gram\">[intransitive]</span> to be alive or be able to stay alive:</div><ul class=\"examples\"><li><em>Without light, plants couldn’t live.</em></li><li><em>He is extremely ill and not expected to live.</em></li><li><em>The baby only lived a few hours.</em></li><li><em>People on average are living much longer than before.</em></li><li><em>I’ll never forget this for as long as I live.</em></li><li><strong><em>live to (be) 80/90 etc/live to the age of 80/90 etc</strong>: My grandmother lived to 85. / She lived to the age of 79.</em></li><li><strong><em>have two weeks/six months etc to live</strong>: He knows he’s only got a few months to live.</em></li><li><em>He did not live to see (=live long enough to see) the realization of his dream.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[way of life]</strong> <span class=\"gram\">[intransitive always + adverb/preposition, transitive]</span> to have a particular type of life, or live in a particular way</div><ul class=\"examples\"><li><strong><em>live in peace/poverty etc</strong>: The people in this country just want to live in peace. / People should not live in fear of crime. / We live in hope that a cure will be found.</em></li><li><strong><em>live peacefully/quietly/happily etc</strong>: The two communities live peacefully alongside each other. / She thought that she would get married and live happily ever after (=like in a children’s story). / Some people like to live dangerously. / Most elderly people prefer to live independently if they can.</em></li><li><em>They earn enough money to live well (=have plenty of food, clothes etc).</em></li><li><em>I just want to live my life in my own way.</em></li><li><em>He’s not well enough to live a normal life.</em></li><li><strong><em>live a quiet/active/healthy etc life</strong>: She lives a very busy life.</em></li><li><em>He had chosen to live the life of a monk.</em></li><li><em>She’s now in Hollywood living a life of luxury.</em></li><li><strong><em>live by</strong>: I have always tried to live by my faith (=according to my religion).</em></li><li><em>We struggle on, living from day to day (=trying to find enough money each day to buy food etc).</em></li><li><em>He was tired of living out of a suitcase (=spending a lot of time travelling).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[earn a living]</strong> <span class=\"gram\">[intransitive]</span> the way that someone lives is the way that they earn money to buy food etc:</div><ul class=\"examples\"><li><em>Fishing is the way their families have lived for generations.</em></li><li><strong><em>live by doing something</strong>: They live by hunting and killing deer.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[exciting life]</strong> <span class=\"gram\">[intransitive]</span> to have an exciting life:</div><ul class=\"examples\"><li><em>She wanted to get out and live a little.</em></li><li><em>We’re beginning to live at last!</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[imagine something]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to imagine that things are happening to you</div><ul class=\"examples\"><li><strong><em>live in</strong>: He lives in a fantasy world.</em></li><li><strong><em>live through</strong>: She lived through her children’s lives.</em></li><li><em>You must stop living in the past (=imagining that things from the past are still happening).</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[be kept somewhere]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> <em>British English</em> <em>informal</em> the place where something lives is the place where it is kept:</div><ul class=\"examples\"><li><em>Where do these cups live?</em></li><li><em>Those big dishes live in the cupboard next to the fridge.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[still exist/have influence]</strong> <span class=\"gram\">[intransitive]</span> if an idea lives, it continues to exist and influence people:</div><ul class=\"examples\"><li><em>Democracy still lives!</em></li><li><em>His name will live forever.</em></li><li><em>That day will always live in my memory.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>living quarters</strong> the part of a building where people live, especially a building that is used by many people or is used for several different purposes:</div><ul class=\"examples\"><li><em>the White House living quarters</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>living expenses</strong> the money you need to spend in order to live, for example on food or a house:</div><ul class=\"examples\"><li><em>His tuition is paid, but he’ll work to cover his living expenses.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>living arrangements</strong> the way someone organizes how and where they will live:</div><ul class=\"examples\"><li><em>Her mother disapproved of the living arrangements, saying that two girls living with four boys was bound to cause problems.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>live it up</strong> <em>informal</em> to do things that you enjoy and spend a lot of money:</div><ul class=\"examples\"><li><em>Sam was living it up in London.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>live by your wits</strong> to get money by being clever or dishonest, and not by doing an ordinary job</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>live a lie</strong> to pretend all the time that you feel or believe something when actually you do not feel that way:</div><ul class=\"examples\"><li><em>I knew that I could not continue to live a lie.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>be living on borrowed time</strong> to be still alive after the time that you were expected to die:</div><ul class=\"examples\"><li><em>She’s been living on borrowed time for the last year.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>live in sin</strong> <em>old-fashioned</em> if people live in sin, they live together and have a sexual relationship without being married → live together</div><div class=\"sense\"><span class=\"snum\">19</span> <strong>live and breathe something</strong> to enjoy doing something so much that you spend most of your time on it:</div><ul class=\"examples\"><li><em>Politics is the stuff I live and breathe.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>you live and learn</strong> <em>spoken</em> used to say that you have just learned something that you did not know before</div><div class=\"sense\"><span class=\"snum\">21</span> <strong>live and let live</strong> used to say that you should accept other people’s behaviour, even if it seems strange</div><div class=\"sense\"><span class=\"snum\">22</span> <strong>you haven’t lived (if/until...)</strong> <em>spoken</em> used to say that someone’s life will be boring if they do not do a particular exciting thing:</div><ul class=\"examples\"><li><em>You haven’t lived until you’ve tasted champagne.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>somebody will live to regret it</strong> used to say that someone will wish that they had not done something:</div><ul class=\"examples\"><li><em>If you marry him, you’ll live to regret it.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>live to see/fight another day</strong> to continue to live or work after a failure or after you have dealt with a difficult situation:</div><ul class=\"examples\"><li><em>Hopefully, the company will live to fight another day.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>live life to the full</strong> to enjoy doing a lot of different things:</div><ul class=\"examples\"><li><em>She believes in living life to the full.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>live high on the hog</strong> used to say that someone has a nice life because they have a lot of money and buy expensive things – often used to show disapproval</div><div class=\"sense\"><span class=\"snum\">27</span> <strong>live from hand to mouth</strong> to have only just enough money to buy food:</div><ul class=\"examples\"><li><em>We lived from hand to mouth, never knowing where the next meal was coming from.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>live the dream</strong> to have the kind of life that you always wanted to have, especially after becoming very successful or rich:</div><ul class=\"examples\"><li><em>I always wanted to be a famous singer, and now I&#x27;m living the dream.</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>long live the King/Queen! etc</strong> <em>spoken</em> used as an expression of loyal support for a person</div><div class=\"sense\"><span class=\"snum\">30</span> <strong>long live democracy/freedom etc</strong> used to say that you hope something continues to exist for a long time:</div><ul class=\"examples\"><li><em>Long live free education!</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /laɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[living]</strong> <span class=\"gram\">[only before noun]</span> not dead or artificial <em>SYN living</em> <em>OPP dead</em>:</div><ul class=\"examples\"><li><em>experiments on live animals</em></li><li><em>Protesters want to stop the export of live sheep and cattle.</em></li><li><em>the number of live births per 1,000 population</em></li><li><em>We were so excited to see real live elephants.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[tv/radio]</strong> a live television or radio programme is seen or heard on television or radio at the same time as it is actually happening <em>OPP prerecorded</em>:</div><ul class=\"examples\"><li><em>a live radio phone-in show</em></li><li><em>There will be live TV coverage of tonight’s big match.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[music/theatre]</strong> a live performance is one in which the entertainer performs for people who are watching, rather than for a film, record etc:</div><ul class=\"examples\"><li><em>A lot of the bars have live music.</em></li><li><em>The band will be giving a live concert performance next week.</em></li><li><em>We’ll be playing you a track from his new live album (=album that was recorded from a live performance).</em></li><li><em>It’s always different when you perform in front of a live audience (=an audience watching a live performance).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[electricity]</strong> a wire or piece of equipment that is live has electricity flowing through it:</div><ul class=\"examples\"><li><em>Be careful – those wires are live.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[bombs]</strong> a live bomb still has the power to explode because it has not been used:</div><ul class=\"examples\"><li><em>They came across a field of live, unexploded mines.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[bullets]</strong> live bullets are real ones that are made of metal and can kill people <em>OPP blank</em>:</div><ul class=\"examples\"><li><em>Troops fired live ammunition to disperse the crowd.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[issue]</strong> a live subject or problem is one that still interests or worries people:</div><ul class=\"examples\"><li><em>Drink-driving is still very much a live issue.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>live coals</strong> pieces of coal that are burning:</div><ul class=\"examples\"><li><em>She threw the paper onto the live coals.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[yoghurt]</strong> live yoghurt contains bacteria that are still alive</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /laɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if something is broadcast live, it is broadcast on television or radio as it is actually happening → prerecorded:</div><ul class=\"examples\"><li><em>The ceremony will be broadcast live on television.</em></li><li><em>The match will be shown live by the BBC.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if people perform live, they perform in front of people who have come to watch, rather than for a film, record etc:</div><ul class=\"examples\"><li><em>I love their music, but I’ve never seen them perform live.</em></li><li><em>The band is playing live in Birmingham tonight.</em></li><li><em>Their latest CD was recorded live (=recorded at a live performance) in New York.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>go live</strong> when a system or project goes live, people start to use it after it has been planned and discussed for a long time:</div><ul class=\"examples\"><li><em>Their new information retrieval system went live last month.</em></li><li><em>a new security project which will go live in October</em></li></ul></div></div>","4104":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> live‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪvli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\">(comparative livelier, superlative liveliest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[people]</strong> someone who is lively has a lot of energy and is very active:</div><ul class=\"examples\"><li><em>a lively child</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[place/situation]</strong> a place or situation that is lively is exciting because a lot of things are happening:</div><ul class=\"examples\"><li><em>The hotel is situated next to the lively bustling port.</em></li><li><em>the city’s lively nightlife</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[movements/music]</strong> lively movements or music are very quick and exciting:</div><ul class=\"examples\"><li><em>a lively Spanish dance</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[discussion/description etc]</strong> a lively discussion, description etc is very interesting and involves a lot of ideas:</div><ul class=\"examples\"><li><em>The book offers a lively account of her travels.</em></li><li><em>a lively debate on environmental issues</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[mind/thoughts]</strong> someone who has a lively mind is intelligent and interested in a lot of things:</div><ul class=\"examples\"><li><em>Even Paula has shown a lively interest in politics.</em></li><li><em>Charlie has a very lively imagination (=he often invents stories, descriptions etc that are not true).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[colour]</strong> very bright:</div><ul class=\"examples\"><li><em>a lively combination of colours</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[taste]</strong> something that has a lively taste has a strong but pleasant taste:</div><ul class=\"examples\"><li><em>The wine has a lively fruity flavour.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>look lively!</strong> <em>BrE spoken</em>, step lively!<em>American English</em> <em>spoken</em> used to tell someone to hurry</div></div>","4105":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> liv‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪvə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a large organ in your body that produces bile and cleans your blood</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the liver of an animal, used as food</div></div>","4106":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> live‧stock</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlaɪvstɒk $ -stɑːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[plural, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">animals such as cows and sheep that are kept on a farm → cattle</div></div>","4107":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> liv‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪvɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> alive now <em>OPP dead</em>:</div><ul class=\"examples\"><li><em>He’s one of the greatest living composers.</em></li><li><em>The sun affects all living things (=people, animals, and plants).</em></li><li><em>a living language (=one that people still use)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>living proof</strong> if someone is living proof of a particular fact, they are a good example of how true it is</div><ul class=\"examples\"><li><strong><em>living proof (that)</strong>: I’m living proof that you don’t need a college degree to be successful.</em></li><li><strong><em>living of</strong>: the living proof of government economic incompetence</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in/within living memory</strong> during the time that anyone can remember:</div><ul class=\"examples\"><li><em>It was the worst storm in living memory.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a living death</strong> a life that is so unpleasant that it seems better to be dead</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>a living hell</strong> a very unpleasant situation that makes you suffer for a long time:</div><ul class=\"examples\"><li><em>These past few days have been a living hell.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>living legend</strong> someone who is famous for being extremely good at something, and who still does that activity:</div><ul class=\"examples\"><li><em>His music has made him a living legend.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually singular]</span> the way that you earn money or the money that you earn:</div><ul class=\"examples\"><li><em>It’s not a great job, but it’s a living.</em></li><li><em>What do you do for a living? (=what do you do as a job?)</em></li><li><strong><em>earn/make a living</strong>: It’s hard to make a decent living as a musician.</em></li><li><strong><em>scrape/scratch a living</strong> (=get just enough to eat or live)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the living</strong> all the people who are alive as opposed to dead people <em>OPP the dead</em></div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the way in which someone lives their life:</div><ul class=\"examples\"><li><em>the stresses of city living</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> the position or income of a parish priest</div></div></div>","4108":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈliving room</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the main room in a house where people relax, watch television etc <em>SYN lounge</em></div></div>","4109":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> liz‧ard</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪzəd $ -ərd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a type of reptile that has four legs and a long tail</div></div>","4110":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ləʊd $ loʊd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[amount of something]</strong> a large quantity of something that is carried by a vehicle, person etc</div><ul class=\"examples\"><li><strong><em>load of</strong>: a load of wood</em></li><li><em>The lorry had shed its load (=the load had fallen off).</em></li><li><em>The plane was carrying a full load of fuel.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a load (of something)</strong> (also loads (of something)<em>British English</em>) <em>informal</em> a lot of something:</div><ul class=\"examples\"><li><em>We got a load of complaints about the loud music.</em></li><li><em>Don’t worry, there’s loads of time</em></li><li><strong><em>loads to do/see/eat etc</strong>: There’s loads to see in Paris.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a bus load/car load/truck load etc</strong> the largest amount of something that a vehicle can carry:</div><ul class=\"examples\"><li><em>a bus load of tourists</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a load of crap/bull etc</strong> (also a load of rubbish<em>British English</em>) <em>spoken</em> <em>not polite</em> used to say that something is bad, untrue, or stupid:</div><ul class=\"examples\"><li><em>· I thought the game was a load of crap.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[work]</strong> the amount of work that a person or machine has to do:</div><ul class=\"examples\"><li><em>The computer couldn’t handle the load and crashed.</em></li><li><strong><em>a light/heavy load</strong> (=not much or a lot of work): Hans has a heavy teaching load this semester.</em></li><li><em>My work load has doubled since Henry left.</em></li><li><em>They hired more staff in order to spread the load.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[worry]</strong> a problem or worry that is difficult to deal with:</div><ul class=\"examples\"><li><em>When someone is depressed, the extra load of having financial problems can make the situation worse.</em></li><li><em>Knowing he was safe was a load off my mind (=I felt less worried).</em></li><li><em>Coping with ill health was a heavy load to bear.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[washing]</strong> a quantity of clothes that are washed together in a washing machine:</div><ul class=\"examples\"><li><em>I’ve already done three loads of laundry this morning.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>get a load of somebody/something</strong> <em>spoken</em> used to tell someone to look at or listen to something that is surprising or funny:</div><ul class=\"examples\"><li><em>Get a load of this! Your stars say you are going to meet someone who’s rich.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[weight]</strong> the amount of weight that something is supporting:</div><ul class=\"examples\"><li><em>a load-bearing wall</em></li><li><em>It increased the load on the wheels.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[electricity]</strong> <em>technical</em> an amount of electrical power that is being produced</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> (also load up) to put a large quantity of something into a vehicle or container <em>OPP unload</em>: ► see thesaurus at fill</div><ul class=\"examples\"><li><em>Have you finished loading up?</em></li><li><em>It took an hour to load the van.</em></li><li><em>Will you help me load the dishwasher?</em></li><li><strong><em>load something into/onto something</strong>: Emma loaded all the groceries into the car. / He loaded the cups onto a tray.</em></li><li><strong><em>load something with something</strong>: She loaded up the car with camping gear.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to put a necessary part into something in order to make it work, for example bullets into a gun or film into a camera</div><ul class=\"examples\"><li><strong><em>load something with something</strong>: Did you load it with 200 or 400 film?</em></li><li><strong><em>load something into something</strong>: Can you load the CD into the player, please?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> to put a program into a computer:</div><ul class=\"examples\"><li><em>The program takes a while to load.</em></li><li><em>To load the file, press the ‘return’ key.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive]</span> (also load up) if a ship, aircraft etc loads, goods are put onto it:</div><ul class=\"examples\"><li><em>The first ship to load at the new port was the ‘Secil Angola’.</em></li><li><strong><em>load with</strong>: The boat called at Lerwick to load up with fresh vegetables.</em></li></ul></div></div>","4111":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ləʊf $ loʊf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\">(plural loaves /ləʊvz $ loʊvz/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> bread that is shaped and baked in one piece and can be cut into slices:</div><ul class=\"examples\"><li><em>a loaf of bread</em></li><li><strong><em>white/wholemeal/granary etc loaf<em>British English</em></strong></em></li><li><strong><em>a sliced loaf<em>British English</em></strong></em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> food that has been cut into very small pieces, pressed together, and baked:</div><ul class=\"examples\"><li><em>a meat loaf</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>use your loaf</strong> <em>British English</em> <em>old-fashioned</em> used to tell someone to think more carefully about what they are doing</div></div>","4112":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ləʊn $ loʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> an amount of money that you borrow from a bank etc</div><ul class=\"examples\"><li><strong><em>loan of</strong>: a loan of £60,000</em></li><li><em>I had to take out a loan to buy my car.</em></li><li><em>It’ll be years before we’ve paid off the loan.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> when you lend something to someone</div><ul class=\"examples\"><li><strong><em>loan of</strong>: Thanks for the loan of your camera.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>on loan (from somebody/something)</strong> if something or someone is on loan, they have been borrowed:</div><ul class=\"examples\"><li><em>The book I wanted was out on loan.</em></li><li><em>paintings on loan from the Louvre</em></li><li><em>Cantona initially went on loan to Leeds United.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>American English</em> to lend someone something, especially money</div><ul class=\"examples\"><li><strong><em>loan somebody something</strong>: Can you loan me $5? / Jeff’s loaned us his car for the weekend.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also loan out<em>British English</em>) to lend something valuable to someone:</div><ul class=\"examples\"><li><em>The National Library has loaned several manuscripts.</em></li><li><strong><em>loan something to somebody/something</strong>: Two of the steam trains have been loaned to other railways.</em></li></ul></div></div>","4113":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lob‧by</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɒbi $ ˈlɑːbi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural lobbies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a wide passage or large hall just inside the entrance to a public building <em>SYN foyer</em>:</div><ul class=\"examples\"><li><em>a hotel lobby</em></li><li><em>I’ll meet you in the entrance lobby.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> a hall in the British parliament where members of parliament and the public meet</div><div class=\"subsense\"><span class=\"subnum\">b)</span> one of the two passages in the British parliament where members go to vote for or against a bill</div><div class=\"sense\"><span class=\"snum\">3</span> a group of people who try to persuade a government that a particular law or situation should be changed: GRAMMAR: Singular or plural verb?• In this meaning, lobby is usually followed by a singular verb: · The business lobby has warned the government against raising taxes.• In British English, you can also use a plural verb: · The business lobby have warned the government against raising taxes.Grammar guide ‒ NOUNS</div><ul class=\"examples\"><li><em>the anti-foxhunting lobby</em></li><li><em>a powerful environmental lobby group</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> an attempt to persuade a government to change a law, make a new law etc:</div><ul class=\"examples\"><li><em>a mass lobby of Parliament by women’s organizations</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span><span class=\"meta-item\">(past tense and past participle lobbied, present participle lobbying, third person singular lobbies)</span></div><div class=\"entry-body\"><div class=\"sense\">to try to persuade the government or someone with political power that a law or situation should be changed</div><ul class=\"examples\"><li><strong><em>lobby for/against</strong>: The group is lobbying for a reduction in defence spending.</em></li><li><strong><em>lobby somebody to do something</strong>: We’ve been lobbying our state representative to support the new health plan.</em></li></ul></div></div>","4114":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lob‧ster</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɒbstə $ ˈlɑːbstər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a sea animal with eight legs, a shell, and two large claws</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the flesh of a lobster, which is eaten</div></div>","4115":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lo‧cal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈləʊkəl $ ˈloʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[usually before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to the particular area you live in, or the area you are talking about:</div><ul class=\"examples\"><li><em>local hospital</em></li><li><em>local residents</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> affecting or limited to one part of your body:</div><ul class=\"examples\"><li><em>a local infection</em></li></ul></div>","4116":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lo‧cal‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈləʊkəli $ ˈloʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in or near the area where you are, or the area you are talking about:</div><ul class=\"examples\"><li><em>I live locally, so it’s easy to get to the office.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in particular small areas: ► see thesaurus at near</div><ul class=\"examples\"><li><em>Most of the country will be dry, but there will be some rain locally.</em></li></ul></div>","4117":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lo‧cate</span><span class=\"meta-item\"><strong>IPA:</strong> /ləʊˈkeɪt $ ˈloʊkeɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>be located in/near etc something</strong> to be in a particular position or place <em>SYN be situated</em>:</div><ul class=\"examples\"><li><em>The business is located right in the center of town.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to find the exact position of something: ► see thesaurus at find</div><ul class=\"examples\"><li><em>We couldn’t locate the source of the radio signal.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to put or build something in a particular place:</div><ul class=\"examples\"><li><em>Large retail chains are usually only prepared to locate stores in areas of high population density.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> <em>American English</em> to come to a place and start a business, company etc there</div><ul class=\"examples\"><li><strong><em>locate in/at etc</strong>: We are offering incentives for companies to locate in our city.</em></li></ul></div>","4118":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lo‧ca‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ləʊˈkeɪʃən $ loʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a particular place, especially in relation to other areas, buildings etc: ► see thesaurus at place RegisterLocation is often used when talking about buying or selling property. In everyday English in other contexts, people usually say place:· It can be stressful moving to a new place.</div><ul class=\"examples\"><li><em>His apartment is in a really good location.</em></li><li><em>its isolated geographical location</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> the position of something</div><ul class=\"examples\"><li><strong><em>location of</strong>: The map shows the precise location of the crash.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> a place away from a film studio where scenes are filmed:</div><ul class=\"examples\"><li><em>It was hard to find a suitable location for the desert scenes.</em></li><li><strong><em>on location</strong>: Most of the movie was shot on location in Africa.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> the act of finding the position of something:</div><ul class=\"examples\"><li><em>The main problem for engineers was the location of underground rivers in the area.</em></li></ul></div>","4119":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɒk $ lɑːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[fasten something]</strong> <span class=\"gram\">[intransitive, transitive]</span> to fasten something, usually with a key, so that other people cannot open it, or to be fastened like this:</div><ul class=\"examples\"><li><em>Did you lock the car?</em></li><li><em>I can’t get this drawer to lock.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[keep in a safe place]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to put something in a place and fasten the door, lid etc with a key</div><ul class=\"examples\"><li><strong><em>lock something in something</strong>: Lock the cat in the kitchen.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[fixed position]</strong> <span class=\"gram\">[intransitive, transitive]</span> to become fixed in one position and impossible to move, or to make something become fixed:</div><ul class=\"examples\"><li><em>The wheels suddenly locked.</em></li><li><strong><em>lock something around/round something</strong>: He locked his hands around the younger man’s throat.</em></li><li><em>A moment later they were locked in an embrace (=holding each other very tightly in a loving or friendly way).</em></li><li><em>Their eyes locked together (=they could not look away from each other) for an instant.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[fixed situation]</strong> <span class=\"gram\">[transitive]</span> if you are locked in a situation, you cannot get out of it GRAMMAR Lock is usually passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be locked in/into something</strong>: The two groups are locked in a vicious cycle of killing. / The company is locked into a five-year contract.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be locked in battle/combat/dispute etc</strong> to be involved in a long, serious argument or fight with someone:</div><ul class=\"examples\"><li><em>They are now locked in a bitter custody battle over the three children.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>lock arms</strong> if people lock arms, they join their arms tightly with the arms of the people on each side:</div><ul class=\"examples\"><li><em>The police locked arms to form a barrier against the protesters.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>lock horns (with somebody)</strong> to argue or fight with someone:</div><ul class=\"examples\"><li><em>The band have now locked horns with their record company over the album.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[fastening]</strong> <span class=\"gram\">[countable]</span> a thing that keeps a door, drawer etc fastened and is usually opened with a key or by moving a small metal bar: → pick a lock at pick1(10)</div><ul class=\"examples\"><li><em>I’m sorry, there isn’t a lock on the bathroom door.</em></li><li><em>The key turned stiffly in the lock.</em></li><li><em>a bike lock</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>under lock and key</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> kept safely in a box, cupboard etc that is locked:</div><ul class=\"examples\"><li><em>Dad keeps all his liquor under lock and key.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> kept in a place such as a prison</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>lock, stock, and barrel</strong> including every part of something:</div><ul class=\"examples\"><li><em>He moved the whole company, lock, stock, and barrel, to Mexico.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[hair]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[countable]</span> a small number of hairs on your head that grow and hang together</div><ul class=\"examples\"><li><strong><em>lock of</strong>: He gently pushed a lock of hair from her eyes.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>locks</strong> <span class=\"gram\">[plural]</span> <em>literary</em> someone’s hair:</div><ul class=\"examples\"><li><em>long flowing locks</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[on a river etc]</strong> <span class=\"gram\">[countable]</span> a part of a canal or river that is closed off by gates so that the water level can be raised or lowered to move boats up or down a slope</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[in a fight]</strong> <span class=\"gram\">[countable]</span> a hold which wrestlers use to prevent their opponent from moving:</div><ul class=\"examples\"><li><em>a head lock</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[vehicle]</strong> <span class=\"gram\">[countable, uncountable]</span> <em>British English</em> the degree to which a vehicle’s front wheels can be turned in order to turn the vehicle</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[rugby]</strong> <span class=\"gram\">[countable]</span> a playing position in the game of rugby</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>a lock on something</strong> <em>American English</em> complete control of something:</div><ul class=\"examples\"><li><em>Pro football still has a lock on male viewers aged 18 to 34.</em></li></ul></div></div>","4120":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lock‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɒkə $ ˈlɑːkər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small cupboard with a lock in a school, sports building, office etc, where you can leave clothes or possessions while you do something</div><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> a very cold room used for storing food in a restaurant or factory:</div><ul class=\"examples\"><li><em>a meat locker</em></li></ul></div>","4121":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɒdʒ $ lɑːdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>lodge a complaint/protest/appeal etc</strong> <em>British English</em> to make a formal or official complaint, protest etc</div><ul class=\"examples\"><li><strong><em>lodge with</strong>: He lodged an appeal with the High Court.</em></li><li><strong><em>lodge against</strong>: They lodged a complaint against the doctor for negligence.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[become stuck]</strong> <span class=\"gram\">[intransitive, transitive always + adverb/preposition]</span> to become firmly stuck somewhere, or to make something become stuck <em>OPP dislodge</em> GRAMMAR Lodge is usually passive when used as a transitive verb.</div><ul class=\"examples\"><li><strong><em>lodge in</strong>: The fishbone lodged in her throat.</em></li><li><strong><em>be lodged in/between/behind etc something</strong>: The bullet was lodged in his spine.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[put somebody somewhere]</strong> <span class=\"gram\">[transitive]</span> to provide someone with a place to stay for a short time:</div><ul class=\"examples\"><li><em>a building used to lodge prisoners of war</em></li><li><strong><em>lodge somebody in/at something</strong>: The refugees were lodged in old army barracks.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[put something somewhere]</strong> <span class=\"gram\">[transitive]</span> <em>British English</em> <em>formal</em> to put something important in an official place so that it is safe</div><ul class=\"examples\"><li><strong><em>lodge something with somebody</strong>: Be sure to lodge a copy of the contract with your solicitor.</em></li><li><strong><em>lodge something in something</strong>: The money was lodged in a Swiss bank account.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[stay somewhere]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> <em>old-fashioned</em> to pay to live in a room in someone’s house</div><ul class=\"examples\"><li><strong><em>lodge at/with etc</strong>: John lodged with a family in Bristol when he first started work.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small house on the land of a large country house, usually at the main entrance gate</div><div class=\"sense\"><span class=\"snum\">2</span> a room or small building at the entrance to a college, institution etc for someone whose job is to watch who enters and leaves:</div><ul class=\"examples\"><li><em>the porter’s lodge</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a house or hotel in the country or mountains where people can stay when they want to go hunting, shooting etc</div><div class=\"sense\"><span class=\"snum\">4</span> a local meeting place for some organizations, or the group of people who belong to one of these organizations:</div><ul class=\"examples\"><li><em>He was a member of a Masonic lodge.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> a beaver’s home</div><div class=\"sense\"><span class=\"snum\">6</span> <em>American English</em> a traditional home of Native Americans, or the group of people that live in it</div></div></div>","4122":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɒft $ lɒːft/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[under a roof]</strong> <em>British English</em> a room or space under the roof of a building, usually used for storing things in <em>SYN attic</em>:</div><ul class=\"examples\"><li><em>Our neighbours have just done a loft conversion (=changed the loft into bedrooms).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[on a farm]</strong> a raised area in a barn used for keeping hay or other crops in:</div><ul class=\"examples\"><li><em>a hayloft</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[part of a room]</strong> <em>American English</em> a raised area above the main part of a room, usually used for sleeping</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[type of apartment]</strong> a space above a business, factory etc that was once used for storing goods, but has been changed into living space:</div><ul class=\"examples\"><li><em>She’s just bought a loft in Manhattan.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[for birds]</strong> a set of cages used to keep pigeons in</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[in a church]</strong> the raised place in a church where the organ or choir is</div></div>","4123":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɒɡ $ lɒːɡ, lɑːɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a thick piece of wood from a tree:</div><ul class=\"examples\"><li><em>a roaring log fire</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an official record of events, especially on a journey in a ship or plane:</div><ul class=\"examples\"><li><em>The captain always keeps a log.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a logarithm</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle logged, present participle logging)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to make an official record of events, facts etc:</div><ul class=\"examples\"><li><em>All phone calls are logged.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to travel a particular distance or for a particular length of time, especially in a plane or ship:</div><ul class=\"examples\"><li><em>The pilot has logged 1,200 flying hours.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> to cut down trees</div></div></div>","4124":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lo‧gic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɒdʒɪk $ ˈlɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular, uncountable]</span> a way of thinking about something that seems correct and reasonable, or a set of sensible reasons for doing something</div><ul class=\"examples\"><li><strong><em>logic behind</strong>: The logic behind this statement is faulty.</em></li><li><strong><em>logic of</strong>: What’s the logic of your argument?</em></li><li><strong><em>accept/follow/see somebody’s logic</strong>: It’s easy to understand his logic.</em></li><li><em>There is a certain logic in their choice of architect.</em></li><li><strong><em>commercial/industrial/economic logic</strong>: Commercial logic has forced the two parts of the company closer together.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a formal method of reasoning, in which ideas are based on previous ideas</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>technical</em> a set of choices that a computer uses to solve a problem</div></div>","4125":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lo‧gic‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɒdʒɪkəl $ ˈlɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> seeming reasonable and sensible <em>OPP illogical</em>:</div><ul class=\"examples\"><li><em>It’s a logical site for a new supermarket, with the housing development nearby.</em></li><li><em>a logical conclusion</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> using a thinking process in which facts and ideas are connected in a correct way:</div><ul class=\"examples\"><li><em>The detective has to discover the murderer by logical deduction.</em></li></ul></div>","4126":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lo‧go</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈləʊɡəʊ $ ˈloʊɡoʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a small design that is the official sign of a company or organization</div></div>","4127":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lone‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈləʊnli $ ˈloʊn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\">(comparative lonelier, superlative loneliest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> unhappy because you are alone or do not have anyone to talk to SYN lonesome<em>American English</em>: ► Do not use lonely to mean ‘without anyone else’. Use alone: She is afraid to travel alone (NOT travel lonely).</div><ul class=\"examples\"><li><em>a lonely old man</em></li><li><em>Don’t you get lonely being on your own all day?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a lonely experience or situation makes you unhappy because you are alone or do not have anyone to talk to:</div><ul class=\"examples\"><li><em>a lonely journey</em></li><li><strong><em>lonely life/existence</strong>: He led a lonely life with few friends.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the lonely</strong> <span class=\"gram\">[plural]</span> people who are lonely</div><div class=\"sense\"><span class=\"snum\">4</span> a lonely place is a long way from where people live and very few people go there SYN lonesome<em>American English</em> <em>, remote</em> <em>, desolate</em></div><ul class=\"examples\"><li><strong><em>lonely place/road/spot etc</em></strong></li></ul></div>","4128":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lone‧some</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈləʊnsəm $ ˈloʊn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very unhappy because you are alone or have no friends <em>SYN lonely</em>:</div><ul class=\"examples\"><li><em>Beth is lonesome without the children.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a lonesome place is a long way from where people live and very few people go there <em>SYN lonely</em> <em>, remote</em>:</div><ul class=\"examples\"><li><em>a lonesome spot near the canyon</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>on/by your lonesome</strong> <em>informal</em> alone</div></div>","4129":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɒŋ $ lɒːŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(comparative longer, superlative longest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[great length]</strong> measuring a great length from one end to the other <em>OPP short</em>:</div><ul class=\"examples\"><li><em>a long table</em></li><li><em>long hair</em></li><li><em>the longest tunnel in the world</em></li><li><em>He stretched out his long legs.</em></li><li><em>a long line of people</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[great distance]</strong> continuing or travelling a great distance from one place to another <em>OPP short</em>:</div><ul class=\"examples\"><li><em>a long distance</em></li><li><em>Springfield is a long way from Chicago.</em></li><li><em>Liz lives in Cheltenham, which is a long way away.</em></li><li><strong><em>long journey/walk/flight/drive etc</strong> (=a journey etc over a large distance that takes a lot of time): It’s a long walk to the shops from here.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[large amount of time]</strong> continuing for a large amount of time, or for a larger amount of time than usual <em>OPP short</em>:</div><ul class=\"examples\"><li><em>a long period of time</em></li><li><em>a long history of success</em></li><li><em>He has a long memory.</em></li><li><strong><em>(for) a long time/while</strong>: He’s been gone a long time. / I haven’t been there for a long while. / It took a long time to get everything ready. / She died a long time ago.</em></li><li><strong><em>long silence/pause/delay etc</strong>: There was a long silence before anybody spoke.</em></li><li><em>She’s recovering from a long illness.</em></li><li><em>Doctors often work long hours (=work for more time than is usual).</em></li><li><strong><em>the longest time<em>American English</em></strong> </em>spoken<em> (=a very long time): It took me the longest time to figure out how to open the windows.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[particular length/distance/time]</strong> used to talk or ask about a particular length, distance, or time:</div><ul class=\"examples\"><li><em>How long is your garden?</em></li><li><em>How long is the film?</em></li><li><em>The cable is not quite long enough.</em></li><li><strong><em>two metres/three miles etc long</strong>: The bridge is 140 feet long.</em></li><li><strong><em>two hours/three days etc long</strong>: The speech was twenty minutes long.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[writing]</strong> containing a lot of words, letters, names, or pages <em>OPP short</em>:</div><ul class=\"examples\"><li><em>a long novel</em></li><li><em>a long list</em></li><li><em>He has a very long name.</em></li><li><em>He owes money to a list of people as long as your arm (=a very long list).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[clothing]</strong> covering all of your arms or legs <em>OPP short</em>:</div><ul class=\"examples\"><li><em>a long dress</em></li><li><em>a long-sleeved shirt</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[tiring/boring]</strong> <em>spoken</em> making you feel tired or bored:</div><ul class=\"examples\"><li><em>It’s been a long day.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[vowel]</strong> <em>technical</em> a long vowel in a word is pronounced for a longer time than a short vowel with the same sound <em>OPP short</em></div><div class=\"sense\"><span class=\"snum\">9</span> <strong>how long is a piece of string?</strong> <em>British English</em> <em>spoken</em> used when there is no definite answer to a question:</div><ul class=\"examples\"><li><em>‘How long will it take to finish the project?’ ‘How long is a piece of string?’</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>the long and (the) short of it</strong> <em>spoken</em> used when you are telling someone the most important facts about something rather than all the details:</div><ul class=\"examples\"><li><em>The long and the short of it is that we missed the train.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>the long arm of somebody/something</strong> <em>written</em> the power of someone or something that has authority, especially to catch and punish someone:</div><ul class=\"examples\"><li><em>He won’t escape the long arm of the law.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>long face</strong> a sad or disappointed expression on someone’s face</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>long in the tooth</strong> <em>informal</em> too old – used humorously:</div><ul class=\"examples\"><li><em>I’m getting a bit long in the tooth for this sort of thing.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>not long for this world</strong> <em>literary</em> likely to die or stop existing soon</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>long on something</strong> having a lot of a quality:</div><ul class=\"examples\"><li><em>He was short on patience, but long on a sense of his own worth.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>long odds</strong> if there are long odds against something happening, it is very unlikely that it will happen</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>in the long run/term</strong> used when talking about what will happen at a later time or when something is finished:</div><ul class=\"examples\"><li><em>All our hard work will be worth it in the long run.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>long shot</strong> someone or something with very little chance of success:</div><ul class=\"examples\"><li><em>Chelsea are a 20–1 long shot to win the championship.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>long time no see</strong> <em>spoken</em> used humorously to say hello when you have not seen someone for a long time</div><div class=\"sense\"><span class=\"snum\">20</span> <strong>take the long view (of something)</strong> to think about the effect that something will have in the future rather than what happens now</div><div class=\"sense\"><span class=\"snum\">21</span> <strong>a long way</strong> very much, far, or a great amount or degree:</div><ul class=\"examples\"><li><em>We’re still a long way from achieving our sales targets.</em></li><li><em>Psychiatry has come a long way (=developed a lot) since the 1920s.</em></li><li><em>Your contributions will go a long way towards helping children in need (=will help to reach a goal).</em></li><li><strong><em>by a long way/shot<em>informal</em></strong> (also<strong>by a long chalk</em>)British English</strong><em> (=used when something is much better, quicker, cheaper etc): It was his best performance this year, by a long way.</em></li><li><strong><em>not by a long way/shot<em>informal</em></strong> (also<strong>not by a long chalk</em>)British English</strong><em> (=not at all or not nearly): He had not told Rory everything, not by a long shot.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>long weekend</strong> three or more days, including Saturday and Sunday, when you do not have to go to work or school</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> for a long time:</div><ul class=\"examples\"><li><em>Have you been waiting long?</em></li><li><em>Reform of the law is long overdue.</em></li><li><em>long established traditions</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to ask and talk about particular amounts of time:</div><ul class=\"examples\"><li><em>How long will it take to get there?</em></li><li><em>Try to keep going for as long as possible.</em></li><li><em>It took me longer than I thought it would.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> at a time that is a long time before or after a particular time</div><ul class=\"examples\"><li><strong><em>long before/after something</strong>: This all happened long before you were born.</em></li><li><strong><em>long ago/since</strong>: He should have left her long ago.</em></li><li><em>It wasn’t long before (=soon) Lisa arrived.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>for long</strong> <span class=\"gram\">[usually in questions and negatives]</span> for a long time:</div><ul class=\"examples\"><li><em>Have you known them for long?</em></li><li><em>I haven’t seen her for so long that I’ve forgotten what she looks like.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>as/so long as</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say that one thing can happen or be true only if another thing happens or is true:</div><ul class=\"examples\"><li><em>You can go out to play as long as you stay in the back yard.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that one thing will continue to happen or be true if another thing happens or is true at the same time:</div><ul class=\"examples\"><li><em>As long as we keep playing well, we’ll keep winning games.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>(for) as long as</strong> used to talk about something continuing for the amount of time that you want, need, or is possible:</div><ul class=\"examples\"><li><em>You can stay for as long as you want.</em></li><li><em>She tried to stay awake for as long as she could.</em></li><li><em>The fruit should be left on the tree as long as possible.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>no longer/not any longer</strong> used when something used to happen or be true in the past but does not happen or is not true now: RegisterIn everyday English, people usually say not any longer or not anymore (especially AmE)/not any more (BrE), rather than no longer, which sounds slightly formal or literary: He no longer lives here. ➔ He doesn’t live here any longer OR anymore.</div><ul class=\"examples\"><li><em>The extra workers won’t be needed any longer.</em></li><li><em>It’s no longer a secret.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>before long</strong> soon or in a short time:</div><ul class=\"examples\"><li><em>Before long a large crowd had gathered outside the building.</em></li><li><em>It’s likely that the law will be abolished before long.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>somebody/something/it won’t be long</strong> <em>spoken</em> used to say that someone or something will be ready, will be back, will happen etc soon:</div><ul class=\"examples\"><li><em>Wait here – I won’t be long.</em></li><li><em>Dinner won’t be long.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>all day/year/summer etc long</strong> during all of the day etc</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>so long</strong> <em>spoken especially</em> <em>American English</em> goodbye</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>long live somebody/something</strong> used to show support for a person, idea, principle, or nation:</div><ul class=\"examples\"><li><em>Long live the King!</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to want something very much, especially when it seems unlikely to happen soon</div><ul class=\"examples\"><li><strong><em>long to do something</strong>: He longed to see her again.</em></li><li><strong><em>long for</strong>: She longed for the chance to speak to him in private.</em></li><li><strong><em>long for somebody to do something</strong>: She longed for him to return.</em></li></ul></div></div>","4130":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌlong-ˈdistance</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> travelling over a long distance</div><ul class=\"examples\"><li><strong><em>long-distance runner</em></strong></li><li><strong><em>long-distance lorry driver</em></strong></li><li><strong><em>long-distance travel/journey/flight/commuting etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>long-distance call</strong> a telephone call to a place that is far away <em>OPP local</em></div></div>","4131":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌlong-ˈterm</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[usually before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">continuing for a long period of time, or relating to what will happen in the distant future <em>OPP short-term</em>:</div><ul class=\"examples\"><li><em>the long-term future of the fishing industry</em></li><li><em>the long-term interests of the company</em></li><li><strong><em>the long-term unemployed</strong> (=people who have not had a job for a long time)</em></li><li><em>the long-term effects of alcohol on the body</em></li><li><strong><em>long-term plan/strategy/solution</em></strong></li><li><strong><em>long-term loan/investment</em></strong></li></ul></div>","4132":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lʊk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[see]</strong> <span class=\"gram\">[intransitive]</span> to turn your eyes towards something, so that you can see it: GRAMMAR: Prepositions with look• You look at someone or something: · She was looking at the baby.· I looked at the screen. ✗Don’t say: She was looking to the baby. | I looked to the screen.• If you look to someone, you depend on them: · He always looked to his father for advice.</div><ul class=\"examples\"><li><em>We sneaked out while Jessie’s mom wasn’t looking.</em></li><li><em>If you look carefully you can see that the painting represents a human figure.</em></li><li><em>Gina covered her eyes, afraid to look.</em></li><li><strong><em>look at</strong>: ‘It’s time we left,’ Ian said, looking at his watch. / The men all turned to look at her as she entered the room.</em></li><li><strong><em>look away/over/down etc</strong>: Dad looked up from his paper and smiled. / ‘We can’t go out in this weather,’ said Bob, looking out of the window.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[search]</strong> <span class=\"gram\">[intransitive]</span> to try to find something:</div><ul class=\"examples\"><li><em>I looked everywhere but Jimmy was nowhere to be found.</em></li><li><strong><em>look for</strong>: Could you help me look for my contact lens? / If you’re looking for a bargain, try the local market.</em></li><li><strong><em>look in/under/between etc</strong>: Try looking under the bed.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[seem]</strong> <span class=\"gram\">[linking verb]</span> to seem:</div><ul class=\"examples\"><li><em>From the way things look at the moment, the Republicans are unlikely to win this election.</em></li><li><strong><em>look good/bad etc</strong>: The future’s looking good.</em></li><li><strong><em>it looks as if/as though/like</strong> (=it seems likely that): It looks as if it might rain later. / It looks like they won’t be needing us anymore.</em></li><li><em>You made me look really stupid in front of all my friends!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[appearance]</strong> <span class=\"gram\">[linking verb]</span> to have a particular appearance: → look like a million dollars at million(4) GRAMMAR: Linking verbsLook is a linking verb in meanings 3 and 4. This type of verb links the subject of the sentence with an adjective or noun: · It looks windy outside.· You look beautiful.· She made him look a fool.</div><ul class=\"examples\"><li><em>How do I look?</em></li><li><strong><em>look tired/happy/sad etc</strong>: You look tired. You should go to bed.</em></li><li><strong><em>look as if/as though/like</strong>: He looked as if he hadn’t washed for a week.</em></li><li><em>What did the man look like?</em></li><li><em>My sister doesn’t look anything like me.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>look daggers at somebody</strong> <em>informal</em> to look at someone with a very angry expression on your face</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>look somebody up and down</strong> to look at someone carefully from their head to their feet, as if you are forming an opinion about them</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>look somebody in the eye</strong> to look directly at someone when you are speaking to them, especially to show that you are not afraid of them or that you are telling the truth:</div><ul class=\"examples\"><li><em>Owen didn’t dare look his father in the eye.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>look down your nose at somebody/something</strong> to behave as if you think that someone or something is not good enough for you:</div><ul class=\"examples\"><li><em>He looks down his nose at anyone foreign.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>look the other way</strong> to ignore something bad that is happening and not try to stop it:</div><ul class=\"examples\"><li><em>Prison guards looked the other way as the man was attacked by fellow prisoners.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>look no further</strong> used to say that something you are offering is exactly what someone has been trying to find:</div><ul class=\"examples\"><li><em>Want a quiet country retreat for your weekend break? Then look no further!</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[face a direction]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if a building looks in a particular direction, it faces that direction:</div><ul class=\"examples\"><li><em>The cabin looks east, so we get the morning sun.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>look before you leap</strong> used to say that it is sensible to think about the possible dangers or difficulties of something before doing it</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>be looking to do something</strong> <em>informal</em> to be planning or expecting to do something:</div><ul class=\"examples\"><li><em>We’re looking to buy a new car early next year.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>look under the bonnet</strong> <em>British English</em>, look under the hood<em>American English</em> to look at or find out about the less noticeable features of something:</div><ul class=\"examples\"><li><em>Look under the bonnet of the company before investing in it.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[look at]</strong> <span class=\"gram\">[countable usually singular]</span> an act of looking at something</div><ul class=\"examples\"><li><strong><em>have/take a look (at somebody/something)</strong>: Let me have a look at that – I think it’s mine. / Take a good look at the photo and see if you recognize anyone in it.</em></li><li><em>I took one look at the coat and decided it wasn’t worth £50.</em></li><li><strong><em>have/take a look around<strong> (also</strong>have/take a look round<em>)British English</em></strong> (=look at all the things in a particular place): I have a special interest in old houses. Do you mind if I take a look around?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[expression]</strong> <span class=\"gram\">[countable]</span> an expression that you make with your eyes or face</div><ul class=\"examples\"><li><strong><em>give somebody a look</strong>: Mike gave him such a severe look he didn’t dare argue.</em></li><li><em>Why has Jake been giving me dirty looks (=unfriendly looks) all morning?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[consider]</strong> <span class=\"gram\">[singular]</span> an act of examining something and thinking about it</div><ul class=\"examples\"><li><strong><em>have/take a look (at somebody/something)</strong>: Have you had a chance to take a look at my proposal yet?</em></li><li><em>I asked the vet to have a quick look at the puppies as well.</em></li><li><em>It’s time to take a fresh look at the old problem of low pay.</em></li><li><em>This month, take a long hard look (=examine very carefully) at where your money is going.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[search]</strong> <span class=\"gram\">[singular]</span> an attempt to find something:</div><ul class=\"examples\"><li><em>I can’t find them anywhere. Have a look yourself.</em></li><li><em>She had a good look (=searched carefully) through the files.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[appearance]</strong> <span class=\"gram\">[countable usually singular]</span> the appearance that someone or something has:</div><ul class=\"examples\"><li><em>The area has a very seedy look to it.</em></li><li><em>Mr Flynn had a tired, ill look in his eyes.</em></li><li><strong><em>not like the look of somebody/something</strong> (=think that something bad has happened or will happen because of something’s appearance): We should turn back now. It’s getting dark and I don’t like the look of those rain clouds.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[way something seems]</strong> <span class=\"gram\">[countable]</span> the way something seems to be:</div><ul class=\"examples\"><li><em>The neighbours are back from holiday by the looks of it (=that is how it seems).</em></li><li><em>I don’t like the look of this new policy (=I do not like the way it seems).</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[beauty]</strong> <strong>looks</strong> <span class=\"gram\">[plural]</span> physical attractiveness:</div><ul class=\"examples\"><li><em>Fiona’s got everything – looks, money and youth.</em></li><li><em>You get your good looks from your mother.</em></li><li><em>When she lost her looks (=became less attractive) she found it difficult to get work.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[fashion]</strong> <span class=\"gram\">[singular]</span> a particular style in clothes, hair, furniture etc:</div><ul class=\"examples\"><li><em>The hippy look is back again.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>if looks could kill</strong> used to say that someone is looking at someone else in a very angry or unfriendly way</div></div></div>","4133":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /luːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[always + adverb/preposition]</span> to appear as a large unclear shape, especially in a threatening way</div><ul class=\"examples\"><li><strong><em>loom up/out/ahead etc</strong>: Suddenly a mountain loomed up in front of them.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if a problem or difficulty looms, it is likely to happen very soon:</div><ul class=\"examples\"><li><em>An economic crisis is looming on the horizon.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>loom large</strong> to seem important, worrying, and difficult to avoid:</div><ul class=\"examples\"><li><em>Fear of failure loomed large in his mind.</em></li></ul></div>","4134":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /luːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[shape or line]</strong> a shape like a curve or a circle made by a line curving back towards itself, or a piece of wire, string etc that has this shape</div><ul class=\"examples\"><li><strong><em>loop of wire/rope/string etc</strong>: A loop of wire held the gate shut.</em></li><li><strong><em>belt loop</strong> (=a loop of material for holding a belt on trousers etc)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[computer]</strong> a set of operations in a computer program that are continuously repeated</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[film/music]</strong> a film or music loop contains images or sounds that are continuously repeated</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>be in the loop/be out of the loop</strong> <em>informal</em> to be or not be part of a group of people who make important decisions</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>knock/throw somebody for a loop</strong> <em>American English</em> <em>informal</em> to surprise and upset someone</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[road/railway]</strong> <em>British English</em> a road or railway line that leaves the main road or track and then joins it again further on</div></div>","4135":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /luːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not firmly attached]</strong> not firmly fastened in place: ► Do not confuse the adjective loose /luːs/ with the verb lose /luːz/ (=stop having something, become unable to find something etc): They thought they might lose their jobs.</div><ul class=\"examples\"><li><em>a loose floorboard</em></li><li><em>This tooth feels very loose.</em></li><li><em>The screw has come loose (=became loose).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[not attached]</strong> not attached to anything else:</div><ul class=\"examples\"><li><em>loose papers</em></li><li><em>His rear wheel spun on the loose stones.</em></li><li><em>The potatoes are sold loose (=not packed in a container).</em></li><li><em>The driver had forgotten to fasten the safety chain and the trailer came loose (=became unattached).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[not tied tightly]</strong> not tied or fastened very tightly:</div><ul class=\"examples\"><li><em>a loose knot</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[hair]</strong> if your hair is loose, it hangs freely rather than being tied back:</div><ul class=\"examples\"><li><em>Her hair fell loose around her shoulders.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[clothes]</strong> loose clothes are big and do not fit your body tightly <em>SYN loose-fitting</em> <em>, baggy</em> <em>OPP tight</em>:</div><ul class=\"examples\"><li><em>a loose sweatshirt</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[free]</strong> free from being controlled or held in a cage, prison, or institution</div><ul class=\"examples\"><li><strong><em>break/get loose</strong> (=escape): A 34-year-old inmate broke loose from the sheriff’s office yesterday.</em></li><li><strong><em>turn/let/set something loose</strong> (=let something go free): Don’t let your dog loose on the beach.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[not exact]</strong> <span class=\"gram\">[usually before noun]</span> not exact or thoroughly done:</div><ul class=\"examples\"><li><em>a loose translation</em></li><li><em>a loose interpretation of the law</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[not very controlled]</strong> not strictly controlled or organized</div><ul class=\"examples\"><li><strong><em>loose federation/alliance/group etc</strong>: a loose federation of political groups</em></li><li><em>loose arrangement (=an arrangement that can easily be changed)</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[not solid]</strong> not pressed tightly together in a solid mass</div><ul class=\"examples\"><li><strong><em>loose soil/earth</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[sport]</strong> not under the control of either team in a game of football, rugby etc:</div><ul class=\"examples\"><li><em>Sheringham was the first player to reach the loose ball.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>cut loose</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to free yourself from someone or something, or their influence</div><ul class=\"examples\"><li><strong><em>cut yourself loose (from something)</strong>: He cut himself loose from the constraints of family life.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>American English</em> <em>informal</em> to start enjoying yourself in a happy noisy way after a period of controlled behaviour:</div><ul class=\"examples\"><li><em>I’m ready to cut loose and enjoy the weekend.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>let (something ↔) loose</strong> to speak or behave in an uncontrolled way:</div><ul class=\"examples\"><li><em>She let loose a string of four-letter words.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>let somebody loose on something</strong> to allow someone to deal with something in the way they want to, when you think they will make mistakes or do something wrong:</div><ul class=\"examples\"><li><em>Whatever you do, don’t let Derek loose on the garden.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>be at a loose end</strong> (also be at loose ends<em>American English</em>) to have nothing to do:</div><ul class=\"examples\"><li><em>I was at a loose end so I decided to go see an old movie.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>loose ends</strong> parts of something that have not been completed or correctly done:</div><ul class=\"examples\"><li><em>We’ve nearly finished, but there are still a few loose ends to be tied up (=dealt with or completed).</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>loose change</strong> coins that you have in your bag or pocket</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>loose cannon</strong> someone who cannot be trusted because they say or do things you do not want them to</div><div class=\"sense\"><span class=\"snum\">18</span> <strong>hang/stay loose</strong> <em>American English</em> <em>spoken</em> used to tell someone to stay calm, or not to worry about something</div><div class=\"sense\"><span class=\"snum\">19</span> <strong>[body waste]</strong> having a problem in which the waste from your bowels has too much liquid in it:</div><ul class=\"examples\"><li><em>loose bowels</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>[immoral]</strong> <em>old-fashioned</em> behaving in a way that is considered to be sexually immoral:</div><ul class=\"examples\"><li><em>a loose woman</em></li><li><em>loose morals</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>[talk]</strong> <em>old-fashioned</em> not careful about what you say or who is listening:</div><ul class=\"examples\"><li><em>There’s been a bit of loose talk about it.</em></li></ul></div>","4136":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> loose‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈluːsli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a way that is not firm or tight:</div><ul class=\"examples\"><li><em>A towel was loosely wrapped around his neck.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in a way that is not exact:</div><ul class=\"examples\"><li><em>The film is loosely based on the novel.</em></li><li><em>‘El Libre’ was loosely translated as ‘the free one’.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> in a way that is not strictly controlled or organized:</div><ul class=\"examples\"><li><em>a loosely structured organization</em></li></ul></div>","4137":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> loos‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈluːsən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to make something less tight or less firmly fastened, or to become less tight or less firmly fastened <em>OPP tighten</em>:</div><ul class=\"examples\"><li><em>You’ll need a spanner to loosen that bolt.</em></li><li><em>The screws have loosened.</em></li><li><em>Harry loosened his tie.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to make laws, rules etc less strict <em>SYN relax</em> <em>OPP tighten</em>:</div><ul class=\"examples\"><li><em>Congress has loosened the restrictions on immigration.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>loosen your grip/hold</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to reduce the control or power you have over someone or something</div><ul class=\"examples\"><li><strong><em>loosen on</strong>: The government has loosened its hold on the media considerably.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to start holding someone or something less tightly than you were before <em>OPP tighten</em></div><ul class=\"examples\"><li><strong><em>loosen on</strong>: He loosened his grip on David’s arm.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>loosen somebody’s tongue</strong> to make someone talk more than usual, especially about things they should not talk about</div></div>","4138":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lor‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɒri $ ˈlɔːri, ˈlɑːri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural lorries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a large vehicle for carrying heavy goods <em>SYN truck</em></div><div class=\"sense\"><span class=\"snum\">2</span> <strong>it fell off the back of a lorry</strong> <em>spoken</em> used humorously to say that something was probably stolen</div></div>","4139":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /luːz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle lost /lɒst $ lɒːst/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[stop having attitude/quality etc]</strong> <span class=\"gram\">[transitive]</span> to stop having a particular attitude, quality, ability etc, or to gradually have less of it → loss:</div><ul class=\"examples\"><li><em>I’ve lost my appetite.</em></li><li><strong><em>lose confidence/interest/hope etc</strong>: The business community has lost confidence in the government. / Carol lost interest in ballet in her teens. / Try not to lose heart (=become sad and hopeless) – there are plenty of other jobs.</em></li><li><strong><em>lose face</strong> (=stop having as much respect from other people): A settlement was reached in which neither side lost face.</em></li><li><strong><em>lose weight/height/speed etc</strong>: You’re looking slim. Have you lost weight? / The plane emptied its fuel tanks as it started losing altitude.</em></li><li><strong><em>lose your sight/hearing/voice/balance etc</strong>: Mr Eyer may lose the sight in one eye. / The tour was postponed when the lead singer lost his voice. / Julian lost his balance and fell.</em></li><li><strong><em>lose your touch</strong> (=become less skilled at doing something you used to do well): This latest movie proves Altman is by no means losing his touch.</em></li><li><em>By the time the ambulance arrived, Douglas had lost consciousness.</em></li><li><strong><em>lose all sense of time/direction/proportion etc</strong>: When he was writing, he lost all sense of time.</em></li><li><strong><em>lose sight of something</strong> (=forget an important fact about a situation): We must never lose sight of the fact that man must work in harmony with nature.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[not win]</strong> <span class=\"gram\">[intransitive, transitive]</span> to not win a game, argument, election, war etc <em>OPP win</em> → defeat:</div><ul class=\"examples\"><li><em>They played so badly they deserved to lose.</em></li><li><em>Klinger lost his seat in the election.</em></li><li><em>Arkansas just lost three games in a row.</em></li><li><em>He just can’t bear to lose an argument.</em></li><li><strong><em>lose to</strong>: The Beavers have dropped only one game since losing to Oregon in January.</em></li><li><strong><em>lose (something) by 1 goal/10 votes/20 points etc</strong>: The government lost by one vote. / The Communist candidate lost by a whisker (=a very small amount).</em></li><li><em>Freddie died in 1982 after losing his battle against AIDS.</em></li><li><strong><em>lose somebody something</strong>: It was a rash decision, and it lost him the race (=caused him to lose the race).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[cannot find something]</strong> <span class=\"gram\">[transitive]</span> to become unable to find someone or something: → lost property</div><ul class=\"examples\"><li><em>I’ve lost the tickets for tonight’s show.</em></li><li><em>I followed her on foot, but lost her in the crowd.</em></li><li><em>It was thought the manuscript had been lost forever.</em></li><li><strong><em>be/get lost in the post<em>British English,</em></strong> <strong>be/get lost in the mail</em>American English</strong><em>: The parcel must have got lost in the post.</em></li><li><strong><em>lose track of something/somebody</strong> (=stop knowing where someone or something is): He lost track of her after her family moved away.</em></li><li><strong><em>lose sight of something/somebody</strong> (=stop being able to see someone or something): Don’t try to walk in a heavy snowstorm as you may lose sight of your vehicle.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[stop having something]</strong> <span class=\"gram\">[transitive]</span> if you lose something that is important or necessary, you then no longer have it, especially because it has been taken from you or destroyed → loss:</div><ul class=\"examples\"><li><em>David’s very upset about losing his job.</em></li><li><em>Hundreds of people lost their homes in the floods.</em></li><li><em>My family lost everything in the war.</em></li><li><em>He was over the limit and will lose his licence.</em></li><li><em>Ninety naval aircraft were lost and thirty damaged.</em></li><li><strong><em>lose a chance/opportunity</strong>: If you hesitate, you may lose the opportunity to compete altogether.</em></li><li><strong><em>lose something to somebody/something</strong>: We were losing customers to cheaper rivals. / She was about to lose her husband to a younger woman. / California has lost 90% of its wetlands to development.</em></li><li><strong><em>lose an arm/leg/eye etc</strong>: He lost his leg in a motorcycle accident.</em></li><li><em>He’s lost a lot of blood but his life is not in danger.</em></li><li><strong><em>lose somebody something</strong>: the mistakes which lost him his kingdom (=caused him to lose his kingdom)</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[death]</strong> <span class=\"gram\">[transitive]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>lose your life</strong> to die:</div><ul class=\"examples\"><li><em>a memorial to honor those who lost their lives in the war</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if you lose a relative or friend, they die – use this when you want to avoid saying the word ‘die’ → loss:</div><ul class=\"examples\"><li><em>One woman in Brooklyn lost a husband and two sons in the gang wars.</em></li><li><em>Sadly, Anna lost the baby (=her baby died before it was born).</em></li><li><strong><em>lose somebody to cancer/AIDS etc</strong>: He lost his father to cancer (=his father died of cancer) last year.</em></li><li><em>Peter was lost at sea when his ship sank.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[money]</strong> <span class=\"gram\">[intransitive, transitive]</span> if you lose money, you then have less money than you had before → loss</div><ul class=\"examples\"><li><strong><em>lose on</strong>: The company is in debt after losing an estimated $30 million on its dotcom enterprise.</em></li><li><em>Creditors and investors stand to lose (=risk losing) vast sums after the company’s collapse.</em></li><li><em>A lot of people lost their shirts (=lost a lot of money) on Ferraris in the eighties.</em></li><li><em>It’s a great deal – we can’t lose!</em></li><li><strong><em>lose somebody something</strong>: The stock market crash lost the banks £70 million (=caused them to lose £70 million).</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>have nothing to lose</strong> <em>spoken</em> if you have nothing to lose, it is worth taking a risk because you cannot make your situation any worse:</div><ul class=\"examples\"><li><em>You might as well apply for the job – you’ve got nothing to lose.</em></li><li><strong><em>have nothing to lose but your pride/reputation etc</strong>: The working class has nothing to lose but its chains (=disadvantages, restrictions etc).</em></li><li><strong><em>have a lot/too much to lose</strong> (=used to say that you could make your situation much worse): These youngsters know they have too much to lose by protesting against the system.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[time]</strong> <span class=\"gram\">[transitive]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if you lose time, you do not make progress as quickly as you want to or should</div><ul class=\"examples\"><li><strong><em>lose time/2 days/3 hours etc</strong>: Vital minutes were lost because the ambulance took half an hour to arrive. / In 1978, 29 million days were lost in industrial action.</em></li><li><em>Come on, there’s no time to lose (=do not waste time).</em></li><li><strong><em>lose no time in doing something</strong> (=do something immediately): Murdock lost no time in taking out a patent for his invention.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if a watch, clock etc loses time, it runs too slowly and shows an earlier time than it should <em>OPP gain</em></div><div class=\"sense\"><span class=\"snum\">9</span> <strong>lose your way/bearings</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to stop knowing where you are or which direction you should go in:</div><ul class=\"examples\"><li><em>I lost my way in the network of tiny alleys.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to become uncertain about your beliefs or what you should do:</div><ul class=\"examples\"><li><em>The company seems to have lost its way of late.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>lose touch (with somebody/something)</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if two people lose touch, they gradually stop communicating, for example by no longer phoning or writing to each other:</div><ul class=\"examples\"><li><em>I’ve lost touch with all my old school friends.</em></li><li><em>They lost touch when Di got married and moved away.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if you lose touch with a situation or group, you are then no longer involved in it and so do not know about it or understand it:</div><ul class=\"examples\"><li><em>They claim the prime minister has lost touch with the party.</em></li><li><em>It sometimes appears that the planners have lost touch with reality.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>lose your temper/cool/rag</strong> to become angry</div><ul class=\"examples\"><li><strong><em>lose with</strong>: Diana was determined not to lose her temper with him.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>lose your head</strong> to become unable to behave calmly or sensibly:</div><ul class=\"examples\"><li><em>You’ve all heard that Nadal lost his head over a girl?</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>lose your mind</strong> to become crazy <em>SYN go crazy</em> <em>, go mad</em>:</div><ul class=\"examples\"><li><em>Nicholas looked at her as if she’d lost her mind.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>lose it</strong> <em>spoken</em> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to become very angry and upset:</div><ul class=\"examples\"><li><em>She completely lost it with one of the kids in class.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> (also lose the plot) to become crazy or confused:</div><ul class=\"examples\"><li><em>I could see people thinking I’d totally lost the plot.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>lose yourself in something</strong> to be paying so much attention to something that you do not notice anything else:</div><ul class=\"examples\"><li><em>She listened intently to the music, losing herself in its beauty.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[escape]</strong> <span class=\"gram\">[transitive]</span> if you lose someone who is chasing you, you manage to escape from them:</div><ul class=\"examples\"><li><em>There’s a better chance of losing him if we take the back route.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>[confuse somebody]</strong> <span class=\"gram\">[transitive]</span> <em>spoken</em> <em>informal</em> to confuse someone when you are trying to explain something to them:</div><ul class=\"examples\"><li><em>Explain it again – you’ve lost me already.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>[remove something]</strong> <span class=\"gram\">[transitive]</span> to remove a part or feature of something that is not necessary or wanted:</div><ul class=\"examples\"><li><em>You could lose the last paragraph to make it fit on one page.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>lose something in the translation/telling</strong> to be less good than the original form:</div><ul class=\"examples\"><li><em>The joke loses something in the translation.</em></li></ul></div>","4140":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> los‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈluːzə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is in a worse situation than they were, because of something that has happened <em>OPP winner</em>:</div><ul class=\"examples\"><li><em>If the strike continues, the people of Galway will be the real losers.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is never successful in life, work, or relationships:</div><ul class=\"examples\"><li><em>What a loser!</em></li><li><em>The guy’s a born loser.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> someone who has lost a competition, game, election etc <em>OPP winner</em></div><ul class=\"examples\"><li><strong><em>good/bad loser</strong> (=someone who behaves well or badly after losing)</em></li></ul></div>","4141":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɒs $ lɒːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the fact of no longer having something, or of having less of it than you used to have, or the process by which this happens</div><ul class=\"examples\"><li><strong><em>loss of</strong>: The court awarded Ms Dixon £7,000 for damages and loss of earnings. / a disease which causes fever and a loss of appetite / This did not explain his apparent loss of interest in his wife. / her loss of confidence in herself / a certain feeling of loss of control / a temporary loss of memory / The animal was weak through loss of blood.</em></li><li><em>The company is closing down two of its factories, leading to 430 job losses.</em></li><li><em>Weight loss should be gradual.</em></li><li><em>a type of hearing loss that affects language development</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> if a business makes a loss, it spends more than it earns:</div><ul class=\"examples\"><li><em>The company made a loss of $250,000 last year.</em></li><li><em>The magazine’s losses totaled almost $5 million.</em></li><li><em>profit and loss</em></li><li><strong><em>run/operate etc at a loss</strong> (=to earn less money from something you sell than it costs you to produce it): Two of the mines are running at a loss.</em></li><li><em>a loss-making rural railway</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> the death of someone</div><ul class=\"examples\"><li><strong><em>loss of</strong>: She must be feeling very lonely after the loss of her husband.</em></li><li><em>I’m sorry to hear of your family’s sad loss (=the death of someone you love).</em></li><li><em>US forces withdrew after suffering heavy losses (=many deaths).</em></li><li><em>The war has led to a tragic loss of life.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be at a loss</strong> to be confused and uncertain about what to do or say:</div><ul class=\"examples\"><li><em>When her son finally left home, Emily felt completely at a loss.</em></li><li><strong><em>be at a loss to do something</strong>: Detectives are so far at a loss to explain the reason for his death.</em></li><li><em>He seemed, for once, at a loss for words (=unable to think what to say).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[uncountable]</span> a feeling of being sad or lonely because someone or something is not there anymore:</div><ul class=\"examples\"><li><em>the deep sense of loss I felt after my divorce</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[singular]</span> a disadvantage caused by someone or something leaving or being removed</div><ul class=\"examples\"><li><strong><em>loss to</strong>: We see your going as a great loss to the company.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>that’s/it’s somebody’s loss</strong> <em>spoken</em> said when you think someone is being stupid for not taking a good opportunity:</div><ul class=\"examples\"><li><em>Well, if he doesn’t want to come, it’s his loss.</em></li></ul></div>","4142":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[cannot find your way]</strong> if you are lost, you do not know where you are and are unable to find your way somewhere:</div><ul class=\"examples\"><li><em>‘Are you lost?’ the driver asked.</em></li><li><em>I got thoroughly lost on the way here.</em></li><li><em>a lost child</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[cannot be found]</strong> if something is lost, you had it but cannot now find it <em>SYN missing</em>:</div><ul class=\"examples\"><li><em>two boys searching for a lost ball</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[wasted]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> lost time or opportunities have not been used in the way that would have given you the greatest advantage:</div><ul class=\"examples\"><li><em>It’ll be impossible to make up the lost time.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>lost sales/business/earnings etc</strong> sales, business etc that you could have had but did not:</div><ul class=\"examples\"><li><em>The strike has cost the company £2 million in lost revenue.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>feel/be lost</strong> to not feel confident about what to do or how to behave:</div><ul class=\"examples\"><li><em>It’s not unusual to feel rather lost when you first start college.</em></li><li><em>She’s a great friend and I’d be lost without her.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>Get lost!</strong> <em>spoken</em> used to rudely tell someone to go away or to stop annoying you</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[not noticing]</strong> <span class=\"gram\">[not before noun]</span> thinking so hard about something, or being so interested in something, that you do not notice what is happening around you</div><ul class=\"examples\"><li><strong><em>lost in</strong>: Harry just stood there, lost in thought. / Amy lay on her bed, totally lost in her book.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>get lost (in something)</strong> to be forgotten or not noticed in a complicated process or in a busy time:</div><ul class=\"examples\"><li><em>It’s easy for your main points to get lost in a long speech.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[not understand]</strong> <strong>be lost</strong> to be completely confused by a complicated explanation:</div><ul class=\"examples\"><li><em>‘Do you understand what I mean?’ ‘Not really. I’m a bit lost.’</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>be lost on somebody</strong> if something is lost on someone, they do not understand or want to accept it:</div><ul class=\"examples\"><li><em>The joke was completely lost on Chris.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>be lost for words</strong> to be unable to say anything because you are very surprised, upset etc:</div><ul class=\"examples\"><li><em>For once in her life, she was lost for words.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[not existing]</strong> <span class=\"gram\">[only before noun]</span> that no longer exists or that you no longer have:</div><ul class=\"examples\"><li><em>the relics of a lost civilization</em></li><li><em>She wept for her broken dreams and lost youth.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>lost cause</strong> something that has no chance of succeeding:</div><ul class=\"examples\"><li><em>Trying to interest my son in classical music is a lost cause.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>lost soul</strong> someone who does not seem to know where they are or what to do – often used humorously</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>all is not lost</strong> used to say that success is still possible, even though there have been problems or failures</div></div>","4143":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">pronoun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɒt $ lɑːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>a lot</strong> (also lots<em>informal</em>) a large amount or number: GRAMMAR: Comparisona lot of• A lot of is fairly informal and is mainly used in spoken English or informal written English.• You can use a lot of with a plural noun and a plural verb: · A lot of people were hurt.• You can use a lot of with an uncountable noun and a singular verb: · A lot of money was spent on it.lots of• Lots of is more informal than a lot of, but is used in exactly the same way.• You say: · Lots of people were hurt.· Lots of money was spent on it.many, a large amount of• In written English, you usually use many or a large amount of.• You use many with a plural noun and a plural verb: · Many people were hurt.• You use a large amount of with an uncountable noun and a singular verb: · A large amount of money was spent on it.• When talking about years, days, weeks etc, you usually use many instead of a lot of: · The book took many years to write. ✗Don’t say: The book took a lot of years to write.</div><ul class=\"examples\"><li><em>We’ve spent a lot on the children’s education.</em></li><li><em>‘How many CDs have you got?’ ‘Lots.’</em></li><li><strong><em>lot of</strong>: They paid a lot of money for that house. / I eat a lot of vegetables. / There were lots of people at the party.</em></li><li><strong><em>an awful lot<strong> (also</strong>a whole lot<em>informal)</em></strong> (=a very large amount or number): He spends an awful lot of time on the computer.</em></li><li><strong><em>a lot to do/learn/say etc</strong>: I still have a lot to learn. / It’s a great city, with lots to see and do.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a lot</strong> (also lots<em>informal</em>) if someone or something is a lot better, faster, easier etc, they are much better, faster etc <em>SYN much</em>:</div><ul class=\"examples\"><li><em>My headache is lots better, thanks.</em></li><li><em>She has a lot more contact with clients these days.</em></li><li><em>You’ll get there a lot quicker if you take the motorway.</em></li><li><em>The house is a lot tidier now Chris has left home.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a lot</strong> used to say that something happens to a great degree or often:</div><ul class=\"examples\"><li><em>Things have changed a lot since I was a child.</em></li><li><em>Paul travels a lot on business.</em></li><li><em>I’ve been worrying a lot about my health.</em></li><li><em>She likes you a lot.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>have a lot on your plate</strong> <em>informal</em> to have a large number of problems to deal with or a large amount of work to do</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>have a lot on your mind</strong> to have a lot of problems that you are worried about:</div><ul class=\"examples\"><li><em>‘You’re quiet today.’ ‘I’ve got a lot on my mind.’</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>have a lot on</strong> <em>British English</em> to be very busy, with a large number of things to do in a short time:</div><ul class=\"examples\"><li><em>I can’t help you now – I’ve got rather a lot on.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[group of people/things]</strong> <span class=\"gram\">[countable]</span> a group of people or things considered together:</div><ul class=\"examples\"><li><em>Could you help me carry this lot upstairs?</em></li><li><strong><em>lot of</strong>: The last lot of people offered £70,000. / I did three lots of exams last summer.</em></li><li><em>Come on, you lot, hurry up!</em></li><li><em>His friends are a strange lot.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the lot</strong> <em>especially British English</em> the whole of an amount or number of things, people etc:</div><ul class=\"examples\"><li><em>We’ll do everything – cooking, washing, ironing – the lot.</em></li><li><em>I can’t believe you ate the whole lot.</em></li><li><em>I think that’s the lot (=everything is included).</em></li><li><strong><em>the lot of you/them/us</strong> (=all of you, them, or us): Shut up, the lot of you!</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[somebody’s situation]</strong> <span class=\"gram\">[singular]</span> your lot is your work, duties, social position etc, especially when they could be better:</div><ul class=\"examples\"><li><em>She seems happy enough with her lot.</em></li><li><em>The unions have always tried to improve the lot of their members.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[land]</strong> <span class=\"gram\">[countable]</span> <em>especially American English</em> an area of land used for building on or for another purpose: → parking lot</div><ul class=\"examples\"><li><em>the vacant lot (=empty land) behind the Commercial Hotel</em></li><li><em>a used-car lot</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[film]</strong> <span class=\"gram\">[countable]</span> a building and the land surrounding it where films are made <em>SYN studio</em>:</div><ul class=\"examples\"><li><em>the Universal Studios lot</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[thing to be sold]</strong> <span class=\"gram\">[countable]</span> something, or a group of things, that is sold at an auction:</div><ul class=\"examples\"><li><em>Lot 54 is a Victorian lamp.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[choosing]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>by lot</strong> if someone is chosen by lot, several people each take a piece of paper or an object from a container, and the person who is chosen is the one who gets a particular marked paper or object:</div><ul class=\"examples\"><li><em>In Athens at that time, judges were chosen by lot.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>draw/cast lots</strong> to choose something or someone by lot:</div><ul class=\"examples\"><li><em>We drew lots to decide who should go first.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>throw in/cast your lot with somebody/something</strong> to join or support someone or something, and accept that what happens to them will affect what happens to you:</div><ul class=\"examples\"><li><em>In 1915 Italy threw in her lot with the Allies.</em></li></ul></div></div>","4144":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lot‧te‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɒtəri $ ˈlɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(plural lotteries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a game used to make money for a state or a charity in which people buy tickets with a series of numbers on them. If their number is picked by chance, they win money or a prize → raffle, draw:</div><ul class=\"examples\"><li><em>a lottery ticket</em></li><li><em>Do you really think winning the lottery would make you happy?</em></li><li><strong><em>national/state lottery</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> <em>American English</em> a system of deciding who will get something by choosing people’s names by chance</div><ul class=\"examples\"><li><strong><em>by lottery</strong>: The State Department issues 55,000 visas each year by lottery.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a lottery</strong> a situation in which what happens depends on chance and is not certain to be successful:</div><ul class=\"examples\"><li><em>That’s the trouble with capitalism. It’s a lottery.</em></li></ul></div>","4145":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /laʊd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\">(comparative louder, superlative loudest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> making a lot of noise <em>OPP quiet</em>:</div><ul class=\"examples\"><li><em>The book fell to the floor with a loud bang.</em></li><li><em>The music was so loud that I had to shout.</em></li><li><em>‘Who’s there?’ asked David in a loud voice.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is loud talks too loudly and confidently:</div><ul class=\"examples\"><li><em>The more Tom drank, the louder he became.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> loud clothes are too bright or have too many bright patterns <em>SYN garish</em> <em>, gaudy</em>:</div><ul class=\"examples\"><li><em>a loud checked suit</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be loud in your praise/opposition/support etc</strong> to express your approval or disapproval very strongly:</div><ul class=\"examples\"><li><em>The local business community was loud in its support for the scheme.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\">(comparative louder, superlative loudest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>spoken</em> in a way that makes a lot of noise <em>SYN loudly</em>:</div><ul class=\"examples\"><li><em>Could you speak a little louder?</em></li><li><em>You’ve got the telly on too loud.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>loud and clear</strong> in a way that is very easy to understand:</div><ul class=\"examples\"><li><em>The message came through loud and clear.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>out loud</strong> in such a way that people can hear you <em>SYN aloud</em>:</div><ul class=\"examples\"><li><em>Read it out loud, so we can all hear.</em></li><li><em>Harriet laughed out loud in astonishment.</em></li></ul></div></div>","4146":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /laʊndʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a waiting room at an airport:</div><ul class=\"examples\"><li><em>the departure lounge</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a public room in a hotel or other building, that is used by many people as a place to relax:</div><ul class=\"examples\"><li><em>the television lounge</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> the main room in a house where people relax, watch television etc <em>SYN living room</em></div><div class=\"sense\"><span class=\"snum\">4</span> <em>British English</em> a lounge bar</div><div class=\"sense\"><span class=\"snum\">5</span> <em>American English</em> a cocktail bar</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[always + adverb/preposition]</span> to stand, sit, or lie in a lazy or relaxed way: ► see thesaurus at sit</div><ul class=\"examples\"><li><em>Nathan was lounging on the grass bank outside the cottage.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>lounge around</strong> (also lounge about<em>British English</em>) to spend time relaxing and doing nothing, often when you should be doing something <em>SYN laze around</em>:</div><ul class=\"examples\"><li><em>James does nothing but lounge around the apartment.</em></li></ul></div></div>","4147":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lʌv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[romantic attraction]</strong> <span class=\"gram\">[transitive not in progressive]</span> to have a strong feeling of affection for someone, combined with sexual attraction:</div><ul class=\"examples\"><li><em>I love you, Tracy.</em></li><li><em>He was the only man she had ever loved.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[care about]</strong> <span class=\"gram\">[transitive not in progressive]</span> to care very much about someone, especially a member of your family or a close friend:</div><ul class=\"examples\"><li><em>I love my grandad so much.</em></li><li><em>I’ve always loved children.</em></li><li><strong><em>much-loved/well-loved</strong>: In 1941, her much-loved sister was killed in an accident.</em></li><li><em>Many people feel guilty after the death of a loved one.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[like/enjoy]</strong> <span class=\"gram\">[transitive]</span> to like something very much or enjoy doing something very much: ► see thesaurus at like</div><ul class=\"examples\"><li><em>I love carrots.</em></li><li><em>Jeff loves his work.</em></li><li><em>I love the way she sings that song.</em></li><li><em>Amy had always loved New York.</em></li><li><strong><em>love doing something</strong>: I love going out to restaurants.</em></li><li><strong><em>love to do something</strong>: We all love to talk about ourselves.</em></li><li><strong><em>I’d love to (do something)<em>spoken</em></strong> (=used to say that you would really like to do something): ‘Would you like to come swimming with us?’ ‘I’d love to.’ / I’d have loved to have stayed till the end. / I’d love to know just why they did that.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[loyalty]</strong> <span class=\"gram\">[transitive not in progressive]</span> to have a strong feeling of loyalty to your country, an institution etc:</div><ul class=\"examples\"><li><em>Dad’s always loved the navy.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>I love it!</strong> <em>spoken</em> used when you are amused by something, especially by someone else’s mistake or bad luck:</div><ul class=\"examples\"><li><em>‘And then her boyfriend walked in and saw her kissing Ray.’ ‘I love it!’</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>somebody’s going to love something</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say that someone will enjoy something:</div><ul class=\"examples\"><li><em>Listen guys, you’re going to love this.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that someone will not be pleased about something:</div><ul class=\"examples\"><li><em>I’m going to love telling him we’ve changed our minds again.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[for family/friends]</strong> <span class=\"gram\">[uncountable]</span> a strong feeling of caring about someone, especially a member of your family or a close friend <em>OPP hate</em> <em>, hatred</em>:</div><ul class=\"examples\"><li><em>What these kids need is love and support.</em></li><li><strong><em>love for</strong>: a mother’s love for her child</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[romantic]</strong> <span class=\"gram\">[uncountable]</span> a strong feeling of liking someone a lot combined with sexual attraction</div><ul class=\"examples\"><li><strong><em>love for</strong>: Their love for each other grew deeper every day.</em></li><li><em>Tara is madly in love with you.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[person you love]</strong> <span class=\"gram\">[countable]</span> someone that you feel a strong romantic and sexual attraction to:</div><ul class=\"examples\"><li><em>He was her first love.</em></li><li><strong><em>the love of your life</strong> (=the person that you feel or felt the most love for)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[pleasure/enjoyment]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[singular, uncountable]</span> a strong feeling of pleasure and enjoyment that something gives you</div><ul class=\"examples\"><li><strong><em>love of/for</strong>: my love of nature / He had a great love of music.</em></li><li><em>I fell in love with Amsterdam the very first time I visited the city.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[countable]</span> something that gives you a lot of pleasure and enjoyment:</div><ul class=\"examples\"><li><em>Sailing was her great love.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>make love (to/with somebody)</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to have sex with someone that you love</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>old use</em> to say loving things to someone, to kiss them etc</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>send/give your love (to somebody),</strong> send/give somebody your love to ask someone to give your loving greetings to someone else when they see them, write to them etc:</div><ul class=\"examples\"><li><em>Aunt Mary sends her love.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>love (from somebody)/lots of love/all my love</strong> <em>written</em> used at the end of a letter to a friend, a member of your family, or someone you love:</div><ul class=\"examples\"><li><em>See you soon. Lots of love, Clare.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>(my) love</strong> <em>British English</em> <em>spoken</em> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a word used when you are talking to someone you love <em>SYN darling</em>:</div><ul class=\"examples\"><li><em>‘Hello, love,’ said her father.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a friendly way of talking to someone who you do not know, especially to a woman or child. Many women consider this to be impolite or offensive:</div><ul class=\"examples\"><li><em>What’s your name, love?</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>be a love and.../... there’s a love</strong> <em>British English</em> <em>spoken</em> used when you are asking someone, especially children and members of your family, to do something:</div><ul class=\"examples\"><li><em>Give these to your sisters, there’s a love.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>there is no love lost between somebody and somebody</strong> if there is no love lost between two people, they dislike each other</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>[tennis]</strong> <span class=\"gram\">[uncountable]</span> an expression meaning ‘no points’, used in the game of tennis</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>not for love or/nor money</strong> <em>informal</em> if you cannot get something or do something for love or money, it is impossible to obtain or to do:</div><ul class=\"examples\"><li><em>I can’t get hold of that book for love nor money.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>love triangle</strong> a situation in which someone is having a sexual relationship with the partner of a close friend – used especially in newspapers</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>for the love of God</strong> (also for the love of Mike/Pete) <em>old-fashioned</em> <em>spoken</em> used to show that you are extremely angry, disappointed etc</div></div></div>","4148":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> love‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlʌvli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span><span class=\"meta-item\">(comparative lovelier, superlative loveliest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>especially British English</em> beautiful or attractive: ► see thesaurus at beautiful</div><ul class=\"examples\"><li><em>She had a lovely face.</em></li><li><em>What a lovely house!</em></li><li><em>You look lovely in that dress.</em></li><li><em>He was a lovely little boy.</em></li><li><em>What a lovely day!</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>spoken</em> <em>especially British English</em> very pleasant, enjoyable, or good: ► see thesaurus at nice</div><ul class=\"examples\"><li><em>Thank you for a lovely evening.</em></li><li><em>That was a lovely cup of tea.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>informal</em> <em>especially British English</em> friendly and pleasant:</div><ul class=\"examples\"><li><em>Richard’s a lovely person.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>British English</em> <em>spoken</em> used to say that something is not at all enjoyable or good:</div><ul class=\"examples\"><li><em>‘The cat threw up all over the carpet!’ ‘Lovely!’</em></li><li><em>You’ve made a lovely mess in here.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>lovely and warm/fresh/clean etc</strong> <em>British English</em> <em>spoken</em> used to emphasize how good something is:</div><ul class=\"examples\"><li><em>This bread’s lovely and fresh.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <em>British English</em> <em>spoken</em> used to show that you are pleased with something:</div><ul class=\"examples\"><li><em>Push it right across. That’s it, lovely.</em></li></ul></div>","4149":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lov‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlʌvə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone’s lover is the person they are having a sexual relationship with but who they are not married to → mistress:</div><ul class=\"examples\"><li><em>He killed his wife’s lover.</em></li><li><em>Nicola and I were lovers.</em></li><li><em>a pair of young lovers</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who likes something very much:</div><ul class=\"examples\"><li><em>music lovers</em></li><li><em>animal lovers</em></li><li><strong><em>lover of</strong>: lovers of the outdoors</em></li></ul></div>","4150":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lov‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlʌvɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[only before noun]</span> behaving in a way that shows you love someone</div><ul class=\"examples\"><li><strong><em>loving wife/family/parents etc</strong>: the confidence he had gained from having a warm and loving family</em></li><li><em>What that child needs is plenty of loving care.</em></li><li><em>He’s very loving and affectionate with his sister.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>peace-loving/fun-loving/home-loving etc</strong> thinking that peace, having fun etc is very important:</div><ul class=\"examples\"><li><em>a peace-loving nation</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> done with a lot of care and attention:</div><ul class=\"examples\"><li><em>the loving care with which the house has been restored</em></li></ul></div>","4151":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ləʊ $ loʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(comparative lower, superlative lowest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[small amount/level/value]</strong> ► see thesaurus at cheap, small</div><div class=\"subsense\"><span class=\"subnum\">a)</span> small, or smaller than usual, in amount, level, or value <em>OPP high</em></div><ul class=\"examples\"><li><strong><em>low income/pay/wages</strong>: families existing on very low incomes</em></li><li><em>In May, the price of cocoa fell to its lowest level since 1975–76.</em></li><li><em>Morale has been low since the latest round of job cuts.</em></li><li><em>In this sort of investment, the risks are fairly low.</em></li><li><em>low temperatures</em></li><li><em>the need for low-cost housing</em></li><li><em>a low-security prison</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>low in something</strong> having less than the usual amount of a substance or chemical <em>OPP high</em>:</div><ul class=\"examples\"><li><em>food that is low in calories</em></li><li><strong><em>low-fat/low-salt etc</strong>: low-alcohol beer</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <strong>in the low 20s/30s etc</strong> if a number, temperature, or level is in the low 20s, 30s etc, it is between 21 and 23, 31 and 33 etc:</div><ul class=\"examples\"><li><em>Tonight, temperatures in most areas will be in the low 50s.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[height]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> having a top that is not far above the ground <em>OPP high</em>:</div><ul class=\"examples\"><li><em>a low wall</em></li><li><em>a long low building</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> at a point that is not far above the ground or near the bottom of something <em>OPP high</em>:</div><ul class=\"examples\"><li><em>low clouds</em></li><li><em>The sun was low in the sky now.</em></li><li><em>Store raw meat on the lowest shelf.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> below the usual height <em>OPP high</em>:</div><ul class=\"examples\"><li><em>a low bridge</em></li><li><em>a low ceiling</em></li><li><em>The river is very low today.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[standards/quality]</strong> bad, or below an acceptable or usual level or quality <em>SYN poor</em> <em>OPP high</em>:</div><ul class=\"examples\"><li><em>Their safety standards seem to be pretty low.</em></li><li><em>Cost-cutting has led to a lower quality of service.</em></li><li><em>the children’s low achievement in school</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[supply]</strong> if you are low on something, or if your supply of something is low, there is not much of it left</div><ul class=\"examples\"><li><strong><em>be/get/run low (on something)</strong>: We’re running low on gas. / Stocks are getting low.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[voice/sound]</strong> ► see thesaurus at quiet</div><div class=\"subsense\"><span class=\"subnum\">a)</span> not loud:</div><ul class=\"examples\"><li><em>I heard a low moaning noise.</em></li><li><em>The volume is too low – turn it up.</em></li><li><em>a low whisper</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> not high:</div><ul class=\"examples\"><li><em>a low note</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[light]</strong> a light that is low is not bright <em>SYN dim</em>:</div><ul class=\"examples\"><li><em>Use low lighting to give the room a romantic atmosphere.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[heat]</strong> if you cook something over a low heat or in a low oven, you cook it using only a small amount of heat <em>OPP high</em></div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[battery]</strong> a battery that is low does not have much power left in it</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[clothes]</strong> a low dress, blouse etc does not cover your neck and the top of your chest → low-cut</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>[unhappy]</strong> <span class=\"gram\">[not before noun]</span> unhappy and without much hope for the future <em>SYN depressed</em>:</div><ul class=\"examples\"><li><em>He was feeling a bit low, so I did my best to cheer him up.</em></li><li><em>Terry seems to be in rather low spirits today.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W1</span><span class=\"meta-item\">(comparative lower, superlative lowest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in or to a low position or level:</div><ul class=\"examples\"><li><em>He bent low over the engine.</em></li><li><em>She pulled her hat low down over her eyes.</em></li><li><em>I had the radio on low.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> near the ground or the bottom of something:</div><ul class=\"examples\"><li><em>That plane’s flying too low!</em></li><li><em>There was a hole low down in the hedge.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if you play or sing musical notes low, you play or sing them with deep notes:</div><ul class=\"examples\"><li><em>Sing those bars an octave lower.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be brought low</strong> <em>old-fashioned</em> to become much less rich or important</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a low price, level, or value <em>OPP high</em></div><ul class=\"examples\"><li><strong><em>fall to/hit/reach etc a new low</strong> (=be worth less than ever before): The euro has fallen to a new low against the dollar.</em></li><li><em>Public confidence in the legal system is at an all-time low (=much lower or worse than ever before).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a very difficult time in someone’s personal or working life</div><ul class=\"examples\"><li><strong><em>highs and lows (of something)</strong> (=good times and bad times): the highs and lows of an actor’s life</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> the lowest point that the temperature reaches during a particular time <em>OPP high</em>:</div><ul class=\"examples\"><li><em>The overnight low will be 8°C.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> an area of low pressure in the air <em>OPP high</em>:</div><ul class=\"examples\"><li><em>a low moving in over the Pacific</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the lowest of the low</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>informal</em> someone you think is completely unfair, cruel, immoral etc</div><div class=\"subsense\"><span class=\"subnum\">b)</span> someone from a low social class – often used humorously</div></div></div>","4152":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> low‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈləʊə $ ˈloʊər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[only before noun]</span> below something else, especially below something of the same type <em>OPP upper</em>:</div><ul class=\"examples\"><li><em>Nina chewed her lower lip anxiously.</em></li><li><em>Ruth went down to the lower deck (=lower level on a ship).</em></li><li><strong><em>your lower limbs</strong> (=your legs)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> at or near the bottom of something <em>OPP upper</em>:</div><ul class=\"examples\"><li><em>the lower slopes of the mountain</em></li><li><em>She suffers with pain in her lower back.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> smaller in number or amount <em>OPP higher</em>:</div><ul class=\"examples\"><li><em>Temperatures will be lower over the weekend.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[only before noun]</span> less important than something else of the same type <em>OPP higher</em>:</div><ul class=\"examples\"><li><em>the lower levels of management</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[reduce]</strong> <span class=\"gram\">[intransitive, transitive]</span> to reduce something in amount, degree, strength etc, or to become less: ► see thesaurus at reduce RegisterIn everyday English, people usually say that someone turns down the temperature or volume rather than lowers it:· Can you turn the heating down?</div><ul class=\"examples\"><li><em>Do you think we should lower the price?</em></li><li><em>After 20 minutes lower the temperature to 325°.</em></li><li><em>drugs to lower blood pressure</em></li><li><em>Helen lowered her voice (=made it quieter) as they approached.</em></li><li><em>His voice lowered (=became quieter).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[move down]</strong> <span class=\"gram\">[transitive]</span> to move something down from higher up <em>OPP raise</em>:</div><ul class=\"examples\"><li><em>Very gently, he lowered the dog onto the rug by the fire.</em></li><li><em>The flags were lowered to half-mast.</em></li><li><em>Greg watched as the coffin was lowered.</em></li><li><strong><em>lower yourself</strong>: He lowered himself carefully down from the top of the wall.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>lower your eyes/head</strong> to look down <em>OPP raise</em>:</div><ul class=\"examples\"><li><em>Christina blushed and lowered her eyes.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>lower yourself</strong> <span class=\"gram\">[usually in negatives]</span> to behave in a way that makes people respect you less:</div><ul class=\"examples\"><li><em>I wouldn’t lower myself to speak to her after what she’s done.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>lower the tone (of something)</strong> to make something not as nice as it was:</div><ul class=\"examples\"><li><em>They thought an influx of students would lower the tone of the neighborhood.</em></li><li><em>Trust you to lower the tone of the conversation (=include rude jokes etc in what you say)!</em></li></ul></div></div>","4153":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> loy‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɔɪəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">always supporting your friends, principles, country etc <em>OPP disloyal</em></div><ul class=\"examples\"><li><strong><em>loyal to</strong>: The army has remained loyal to the government.</em></li><li><em>a loyal supporter of the team</em></li><li><em>her many years of loyal service to the company</em></li><li><em>loyal customers</em></li></ul></div>","4154":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> loy‧al‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɔɪəlti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(plural loyalties)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the quality of remaining faithful to your friends, principles, country etc</div><ul class=\"examples\"><li><strong><em>loyalty to/towards</strong>: Elizabeth understood her husband’s loyalty to his sister.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually plural]</span> a feeling of support for someone or something</div><ul class=\"examples\"><li><strong><em>local/regional/tribal/family etc loyalty/loyalties</strong>: In the rural areas, family and tribal loyalties continue to be important.</em></li><li><em>the agony of divided loyalties (=loyalty to two different or opposing people) for the children in a divorce</em></li></ul></div>","4155":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lʌk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[success]</strong> (also good luck) good things that happen to you by chance:</div><ul class=\"examples\"><li><em>You’re not having much luck today, are you?</em></li><li><em>He’s had good luck with his roses this year.</em></li><li><em>It was an incredible piece of luck.</em></li><li><strong><em>by luck</strong>: It was only by luck that they managed to avoid hitting the rocks near the shore.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>bad luck</strong> the bad things that happen to someone by chance, not because of something they did:</div><ul class=\"examples\"><li><em>I’ve had nothing but bad luck since I moved to this town.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[chance]</strong> when good or bad things happen to people by chance:</div><ul class=\"examples\"><li><em>Roulette is a game of luck.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>with (any) luck/with a bit of luck</strong> <em>spoken</em> if things happen in the way that you want <em>SYN hopefully</em>:</div><ul class=\"examples\"><li><em>With a bit of luck, you might get a flight tomorrow.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>wish somebody (the best of) luck</strong> to tell someone that you hope they will be successful in something they are going to do:</div><ul class=\"examples\"><li><em>She wished me luck in the exam, then left.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>good luck/best of luck</strong> <em>spoken</em> used to tell someone that you hope they will be successful in something they are going to do:</div><ul class=\"examples\"><li><em>Good luck in this enormous project you are undertaking.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>good luck to somebody</strong> <em>spoken</em> used to say that you do not mind what someone does because it does not affect you:</div><ul class=\"examples\"><li><em>I say, good luck to him.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>any luck?/no luck?</strong> <em>spoken</em> used to ask someone if they have succeeded in doing something:</div><ul class=\"examples\"><li><em>‘Oh, there you are. Any luck?’ ‘No, I didn’t catch a single fish.’</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>be in luck</strong> to be able to do or get something, especially when you did not expect to:</div><ul class=\"examples\"><li><em>You’re in luck – it’s stopped snowing.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>be out of luck</strong> to be prevented from getting or doing something by bad luck:</div><ul class=\"examples\"><li><em>The team were out of luck again at Scarborough on Saturday.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>do something for luck</strong> to do something because you think it might bring you good luck:</div><ul class=\"examples\"><li><em>She crossed her fingers for luck.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>just my luck</strong> <em>spoken</em> used to say that you are not surprised something bad has happened to you, because you are usually unlucky:</div><ul class=\"examples\"><li><em>I didn’t get to the phone in time. Just my luck!</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>no such luck</strong> <em>spoken</em> used to say you are disappointed because something good that you hoped would happen did not happen:</div><ul class=\"examples\"><li><em>‘Have you got Sunday off?’ ‘No such luck.’</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>better luck next time</strong> used to say that you hope someone will be more successful the next time they try to do something</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>as luck would have it</strong> used to say that something happened by chance:</div><ul class=\"examples\"><li><em>As luck would have it, my best friend is the most wonderful cook in the world.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>try/chance your luck</strong> to do something because you hope you will be successful, even though you know you may not be:</div><ul class=\"examples\"><li><em>After the war my father went to Canada to try his luck at farming there.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>be down on your luck</strong> to have no money because you have had a lot of bad luck over a long period of time:</div><ul class=\"examples\"><li><em>When someone is down on their luck, friends are very difficult to find.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>the luck of the draw</strong> the result of chance rather than something you can control</div><div class=\"sense\"><span class=\"snum\">19</span> <strong>some people have all the luck</strong> <em>spoken</em> used to say that you wish you had what someone else has</div><div class=\"sense\"><span class=\"snum\">20</span> <strong>bad/hard/tough luck</strong> <em>British English</em> <em>spoken</em> used to express sympathy when something unpleasant has happened to someone → tough luck at tough1(7)</div><div class=\"sense\"><span class=\"snum\">21</span> <strong>with/knowing somebody’s luck</strong> <em>spoken</em> used to say that you expect something bad to happen to someone because bad things often do happen to them:</div><ul class=\"examples\"><li><em>With my luck, I’d lose if I backed the only horse in a one horse race.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>worse luck</strong> <em>British English</em> <em>spoken</em> unfortunately:</div><ul class=\"examples\"><li><em>‘Would your boyfriend like a drink?’ ‘He’s not my boyfriend, worse luck!’</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>luck is on somebody’s side</strong> if luck is on someone’s side, things go well for them:</div><ul class=\"examples\"><li><em>Luck was on my side; all the traffic lights were green.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>(one) for luck</strong> <em>spoken</em> used when you take, add, or do something for no particular reason, or in order to say that you hope good things happen</div></div>","4156":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> luck‧i‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlʌkəli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[sentence adverb]</span> used to say that it is good that something happened or was done because if it had not, the situation would be unpleasant or difficult <em>SYN fortunately</em>:</div><ul class=\"examples\"><li><em>Luckily the museum was not damaged by the earthquake.</em></li><li><strong><em>luckily for somebody</strong>: Luckily for them, he braked in time.</em></li></ul></div>","4157":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> luck‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlʌki/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\">(comparative luckier, superlative luckiest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having good luck <em>SYN fortunate</em> <em>OPP unlucky</em></div><ul class=\"examples\"><li><strong><em>be lucky to do/be something</strong>: The children were lucky to survive the fire which destroyed their home.</em></li><li><strong><em>lucky enough to do something</strong>: those of us lucky enough to own our own homes</em></li><li><strong><em>lucky if</strong>: I’ll be lucky if I get any of my money back.</em></li><li><strong><em>lucky (that)</strong>: I was tremendously lucky that I didn’t die in the accident.</em></li><li><strong><em>lucky with</strong>: We’ve been very lucky with the weather.</em></li><li><strong><em>count/consider/think yourself lucky</strong>: Count yourself lucky you’ve got a husband like Jack.</em></li><li><strong><em>get lucky</strong> (=be lucky on a particular occasion): You might get lucky and find a bargain.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> resulting from good luck:</div><ul class=\"examples\"><li><em>I didn’t really know your name – it was just a lucky guess.</em></li><li><em>A middle-aged woman had a lucky escape when a tree crashed down onto her car.</em></li><li><strong><em>it is lucky (that)</strong>: It’s lucky that no-one was hurt.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> bringing good luck:</div><ul class=\"examples\"><li><em>a lucky charm</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>lucky you/me etc</strong> <em>spoken</em> used to say that someone is fortunate to be able to do something:</div><ul class=\"examples\"><li><em>‘My husband’s a rich man, and devoted to me.’ ‘Lucky you.’</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be somebody’s lucky day</strong> <em>spoken</em> used to say that something good and often unexpected will happen to someone:</div><ul class=\"examples\"><li><em>We’re going to win. I just know it’s our lucky day</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>you’ll/you’d be lucky!</strong> <em>spoken</em> used to tell someone that what they want probably will not happen:</div><ul class=\"examples\"><li><em>‘Fifty pounds should be enough.’ ‘You’ll be lucky!’</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>I/you should be so lucky!</strong> <em>spoken</em> used to tell someone that what they want is not likely to happen, especially because it is unreasonable:</div><ul class=\"examples\"><li><em>You want three weeks holiday? You should be so lucky!</em></li></ul></div>","4158":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lu‧cra‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈluːkrətɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">a job or activity that is lucrative lets you earn a lot of money <em>SYN profitable</em></div><ul class=\"examples\"><li><strong><em>lucrative business/market/contract etc</strong>: He inherited a lucrative business from his father.</em></li></ul></div>","4159":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lug‧gage</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlʌɡɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the cases, bags etc that you carry when you are travelling SYN baggage<em>American English</em>: → hand luggage</div><ul class=\"examples\"><li><em>They searched his luggage for illegal drugs.</em></li></ul></div>","4160":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lʌmp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small piece of something solid, without a particular shape: ► see thesaurus at piece</div><ul class=\"examples\"><li><em>Strain the custard to remove lumps.</em></li><li><strong><em>lump of</strong>: Melt a lump of butter in your frying-pan.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a small hard swollen area that sticks out from someone’s skin or grows in their body, usually because of an illness:</div><ul class=\"examples\"><li><em>You should never ignore a breast lump.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a small square block of sugar:</div><ul class=\"examples\"><li><em>One lump or two?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a lump in/to somebody’s throat</strong> a feeling that you want to cry:</div><ul class=\"examples\"><li><em>There was a lump in her throat as she gazed at the child.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>take your lumps</strong> <em>American English</em> <em>informal</em> to accept the bad things that happen and not let them affect you:</div><ul class=\"examples\"><li><em>According to experts, the company took its lumps but is on the road to profitability.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <em>British English</em> <em>spoken</em> someone who is stupid or clumsy:</div><ul class=\"examples\"><li><em>He’s a big fat lump.</em></li></ul></div>","4161":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lʌntʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a meal eaten in the middle of the day: GRAMMAR: Patterns with lunchfor lunch• You eat something for lunch: · I had chicken for lunch. ✗Don’t say: I had chicken on lunch. | I had chicken at lunch.at lunch• You use at lunch to talk about something that happens while you are eating lunch: · We can talk about it at lunch.• You also use at lunch to say that someone has gone somewhere else to eat lunch: · I went to see her, but she was at lunch.</div><ul class=\"examples\"><li><em>What’s for lunch?</em></li><li><em>I&#x27;ve just had lunch with John.</em></li><li><strong><em>at lunch</strong>: I’m afraid he’s at lunch until two.</em></li><li><strong><em>over lunch</strong>: A dozen senators met over lunch with the Chinese ambassador.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>there’s no (such thing as a) free lunch</strong> used to say that you cannot get anything without working for it or paying for it</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>out to lunch</strong> <em>informal</em> behaving or talking in a strange or crazy way</div></div>","4162":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lunch‧time</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlʌntʃtaɪm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the time in the middle of the day when people usually eat their lunch</div><ul class=\"examples\"><li><strong><em>at lunchtime</strong>: Some people prefer to eat their main meal at lunchtime.</em></li><li><em>a lunchtime drink</em></li></ul></div>","4163":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lʌŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">one of the two organs in your body that you breathe with: → iron lung</div><ul class=\"examples\"><li><em>Smoking can cause lung cancer.</em></li></ul></div>","4164":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lʊə, ljʊə $ lʊr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to persuade someone to do something, especially something wrong or dangerous, by making it seem attractive or exciting</div><ul class=\"examples\"><li><strong><em>lure somebody into (doing) something</strong>: People may be lured into buying tickets by clever advertising.</em></li><li><strong><em>lure somebody away</strong>: Computer games are luring youngsters away from their lessons.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to attract customers, workers, money etc from another company or place</div><ul class=\"examples\"><li><strong><em>lure somebody back/away</strong>: The bank launched an advertising campaign to lure back its traditional customers. / It’s very difficult to lure talent away from Silicon Valley.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[usually singular]</span> something that attracts people, or the quality of being able to do this</div><ul class=\"examples\"><li><strong><em>lure of</strong>: the lure of easy money / Malc wasn’t mature enough to resist the lure of drink and drugs.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an object used to attract animals or fish so that they can be caught <em>SYN decoy</em></div></div></div>","4165":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /lɜːk $ lɜːrk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to wait somewhere quietly and secretly, usually because you are going to do something wrong</div><ul class=\"examples\"><li><strong><em>lurk in/behind/beneath/around etc</strong>: She didn’t see the figure lurking behind the bushes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if something such as danger, a feeling etc lurks somewhere, it exists, but you may not see it or know about it:</div><ul class=\"examples\"><li><em>a dark formless danger, lurking in the shadows</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if you lurk in a chat room on the Internet, you read what other people are writing to each other, but you do not write any messages yourself</div><ul class=\"examples\"><li><strong><em>lurk in</strong>: I think it’s sort of creepy how people lurk in chat rooms.</em></li></ul></div>","4166":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lux‧u‧ri‧ous</span><span class=\"meta-item\"><strong>IPA:</strong> /lʌɡˈzjʊəriəs, ləɡˈʒʊəriəs $ ləɡˈʒʊriəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">very expensive, beautiful, and comfortable:</div><ul class=\"examples\"><li><em>a luxurious 30-room villa</em></li></ul></div>","4167":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lux‧u‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlʌkʃəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(plural luxuries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> very great comfort and pleasure, such as you get from expensive food, beautiful houses, cars etc</div><ul class=\"examples\"><li><strong><em>in luxury</strong>: She stole to keep her boyfriend in luxury.</em></li><li><em>He was leading a life of luxury in Australia.</em></li><li><strong><em>luxury hotel/car/home etc</strong> (=expensive and large): We stayed in a five-star luxury hotel.</em></li><li><em>The dress is lambswool – pure luxury.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> something expensive that you do not need, but you buy for pleasure and enjoyment <em>OPP necessity</em>:</div><ul class=\"examples\"><li><em>luxuries like chocolate and perfume</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>afford/have/enjoy the luxury of something</strong> to have something that is very pleasant or convenient, that you are not always able to have:</div><ul class=\"examples\"><li><em>For the first time in three years, they actually had the luxury of a whole day together.</em></li></ul></div>","4168":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> lyr‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈlɪrɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>lyrics</strong> <span class=\"gram\">[plural]</span> the words of a song:</div><ul class=\"examples\"><li><em>He wrote some great music, but the lyrics weren’t that good.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> (also ˌlyric ˈpoem) <em>technical</em> a poem, usually a short one, written in a lyric style</div></div>"};